const V2_REVIEW_CORRECTIONS = {
  kjøtt:{ word:"kjøtt", forms:["kjøtt","kjøttet"], labels:["物质名词/不定形式","定指形式"], note:"kjøtt（肉）通常作不可数物质名词，不定形式不加 et：spise kjøtt（吃肉）。定指形式 kjøttet 指具体语境中的肉；谈种类可说 kjøttsorter，也可用 svinekjøtt（猪肉）、kylling（鸡肉）等。" },
  laks:{ note:"可指鲑鱼这种鱼，也可指作为食材的三文鱼；泛指食材时通常不加冠词，如 spise laks（吃三文鱼）。具体一条鱼或一份鱼肉可按语境使用 en laks / et stykke laks。" },
  ingenting:{ pos:"代词", levelBasis:"基础否定代词；暂标 A1", note:"ingenting 是固定形式的代词，表示“什么都没有/没有任何事情或东西”，可独立使用：Jeg forstår ingenting（我什么也不懂）。修饰名词时改用 ingen：ingen penger（没有钱）。" },
  undertøy:{ word:"undertøy", forms:["undertøy","undertøyet"], labels:["不定形式","定指形式"], note:"undertøy 常作集合/物质名词，不定形式一般不加冠词，例如 Jeg må vaske undertøy（我得洗内衣）。定指形式是 undertøyet；要说一件具体衣物，可用 plagg 或具体衣物名称，如 en BH。" },
  for:{ note:"本卡聚焦介词用法：en gave til deg（给你的礼物；收礼人用 til，不用 for）、for barn（供儿童使用/适合儿童）。for 也可作连词“因为”，那时后接完整分句。" },
  kart:{ zh:"地图；图表；清单/概览（依语境）", note:"出行语境通常是地图；数字地图可说 digitalt kart。中性名词的不定复数与单数同形。不要和 en kart（未成熟果实）或 et kort（卡片）混淆。" },
  snø:{ word:"snø", forms:["snø","snøen"], labels:["物质名词词头","定指单数"], note:"雪通常作不可数物质名词，不说 en snø；snøen 指具体的积雪/雪层。同形动词 snø 表示“下雪”，如 Det snør。" },
  tidlig:{ forms:["tidlig","tidlig","tidlig","tidlige","tidligere","tidligst"], labels:["阳性/阴性单数","中性单数","复数","定指复数","比较级（形容词/副词）","最高级"], note:"作形容词时随名词变化：en tidlig buss、et tidlig tog、tidlige avganger；作副词修饰动作时不变，如 stå opp tidlig。比较级 tidligere 可表示“更早/以前”，最高级 tidligst。" },
  feber:{ forms:["en feber","feberen","febere / febrer","feberne / febrene"], labels:["不定单数","定指单数","不定复数（少见）","定指复数（少见）"], note:"Bokmålsordboka 将其列为阳性名词，词形有 en feber、feberen；复数形式 febere/febrer、feberne/febrene。说“发烧”时通常用无冠词搭配 ha feber；医学义为体温升高，也可比喻忙乱或紧张状态。" },
  sentrum:{ forms:["et sentrum","sentrumet","sentrum / sentra / sentre","sentrumene / sentraene / sentrene"], labels:["不定单数","定指单数","不定复数（多种形式）","定指复数（多种形式）"], note:"指城市中心时常说 i sentrum / til sentrum（在/去市中心）；词典认可 sentrumet、sentrumene，也列有 sentra/sentre、sentraene/sentrene 等复数变体。本卡优先练最直观的 sentrum-et/ene。" },
  stor:{ forms:["stor","stort","store","større","størst / største"], labels:["阳性/阴性","中性","复数/定指","比较级","最高级（表语/定指）"], note:"和名词性数一致：en stor bil、et stort hus、store biler。比较级 større 后常接 enn；最高级可用 størst（表语）或 bestemt form største（定指名词前）。" },
  liten:{ forms:["liten","lite","små","mindre","minst / minste"], labels:["阳性","中性","复数","比较级","最高级（表语/定指）"], note:"不规则变化：en liten bil、et lite hus、små biler；比较级 mindre，最高级 minst（表语）/minste（定指），如 det minste rommet。" },
  ny:{ forms:["ny","nytt","nye","nyere","nyest / nyeste"], labels:["阳性/阴性","中性","复数/定指","比较级","最高级（表语/定指）"], note:"en ny bil、et nytt hus、nye bøker；比较级 nyere，最高级 nyest（表语）/nyeste（定指），如 den nyeste boka。" },
  gammel:{ forms:["gammel","gammelt","gamle","eldre","eldst / eldste"], labels:["阳性","中性","复数/定指","比较级","最高级（表语/定指）"], note:"物品可指旧，人可指年长；en gammel venn、et gammelt hus。比较级 eldre，最高级 eldste（定指）/eldst（表语）。" },
  varm:{ forms:["varm","varmt","varme","varmere","varmest / varmeste"], labels:["阳性/阴性","中性","复数/定指","比较级","最高级（表语/定指）"], note:"描述天气、衣物或食物温度：en varm jakke、varmt vann；比较级 varmere，最高级 varmest（表语）/varmeste（定指）。" },
  kald:{ forms:["kald","kaldt","kalde","kaldere","kaldest / kaldeste"], labels:["阳性/阴性","中性","复数/定指","比较级","最高级（表语/定指）"], note:"描述天气或物体温度：kaldt vær、kaldt vann；说“我觉得冷”常用 Jeg fryser。最高级为 kaldest（表语）/kaldeste（定指）。" },
  trøtt:{ forms:["trøtt","trøtt","trøtte","trøttere","trøttest / trøtteste"], labels:["阳性/阴性","中性","复数/定指","比较级","最高级（表语/定指）"], note:"表示疲倦或困倦：Jeg er trøtt。中性单数同形；复数/定指 trøtte；比较级 trøttere，最高级 trøttest（表语）/trøtteste（定指）。" },
  glad:{ forms:["glad","glad","glade","gladere","gladest / gladeste"], labels:["阳性/阴性","中性","复数/定指","比较级","最高级（表语/定指）"], note:"常见搭配 være glad for noe（为某事高兴）、være glad i noen（喜欢/爱某人）；最高级可作 gladest（表语）或 gladeste（定指）。" },
  trist:{ forms:["trist","trist","triste","tristere","tristest / tristeste"], labels:["阳性/阴性","中性","复数/定指","比较级","最高级（表语/定指）"], note:"可描述人的情绪，也可描述令人难过的事；常说 være trist over noe。最高级为 tristest（表语）/tristeste（定指）。" },
  bra:{ forms:["bra","bedre","best / beste"], labels:["原级","比较级","最高级（表语/定指）"], note:"常见于 Det går bra（进展顺利）、ha det bra（保重/过得好）。比较级 bedre；最高级 best（表语）/beste（定指）。" },
  de:{ note:"复数主格 de、宾格 dem，所有格另用 deres。现代日常挪威语 de/dem 通常读作 /di/，写法按句法区分；句首大写 De 也可作正式的“您”，但日常较少见。" },
  bagasje:{ zh:"行李；旅行时携带的物品（通常作集合名词）", forms:["bagasje","bagasjen"], labels:["无冠词/不定形式（集合名词）","定指单数"], note:"通常整体指一批行李，不像 koffert 那样指一个具体箱子；reise med lite bagasje=轻装出行。" },
  bagasjerom:{ zh:"（汽车）行李舱；后备箱", note:"指汽车内专门放行李的空间，通常位于车尾；不是行李箱 koffert，也不是行李集合名词 bagasje。" },
  flybillett:{ zh:"机票；乘飞机旅行的票证", note:"范围是乘飞机旅行的票证；通常说 bestille/kjøpe en flybillett。" },
  sykkel:{ zh:"自行车；（体育语境）自行车运动", note:"日常主要指两轮脚踏车；词典也收录 sykling som idrett（自行车运动）这一用法。骑车这个动作是动词 sykle。" },
  sykle:{ zh:"骑自行车；骑车出行；用自行车运送", note:"可接目的地/路线（sykle til jobben）或表示骑车送物品（sykle varene bort）；不要与名词 sykling 混淆。" },
  parkeringsplass:{ zh:"停车位；停车场/停车区域（依范围）", note:"词典核心义是可以停放汽车的地方；可能指一个车位，也可在具体场景中指整个停车区域。" },
  dagsbillett:{ zh:"日票；当天有效的票/通票", note:"由 dag + billett 构成；交通语境常指一日通票，但适用区域、交通工具及有效时段应看售票方规则。" },
  helårskort:{ zh:"全年卡；有效期覆盖一整年的通票或会员卡（依服务）", note:"复合词 helår（全年）+ kort（卡/票证）；具体可能是交通通票、场馆年卡等，不能脱离售卖服务断定用途。" },
  sete:{ zh:"座位；席位；（身体）臀部（依语境）", note:"et sete på bussen=公交车上的一个座位；ha sete i regjeringen=在政府中占有席位；i setet 也可指臀部。" },
  parkere:{ zh:"停车；把车辆停放在某处；（引申）暂搁置", note:"parkere bilen 是把车停好；也可引申为暂时搁置一个议题（parkere saken）。" },
  rute:{ zh:"路线/班次；窗格/方格（依词义和语境）", note:"交通义 rute 是按时间运行的固定线路，也可指班次表；另有独立词义“方格、窗玻璃”，如 rutene på et sjakkbrett / vindusrute。不要把这些都理解成行车路线。" },
  sykling:{ zh:"骑自行车；骑行活动/自行车运动", note:"是动作或活动名词（det å sykle），不是自行车这个物件；自行车是 sykkel。" },
  hyttetur:{ zh:"去小木屋的一趟旅行/短住", note:"由 hytte + tur 构成，强调一次去小木屋的出行；可用于度假，也可只是周末短住，不一定是长期“度假”。" },
  tursekk:{ zh:"徒步/出游背包；户外旅行用的背包", note:"由 tur + sekk 构成，说明用途；一般装在背上的包是 ryggsekk，sekk 本身则可泛指袋子或麻袋。" },
  ryggsekk:{ zh:"背包；背在背上的包", note:"字面由 rygg（背）+ sekk（袋）构成，指背在身上的包，不专指登山包；徒步用途可进一步说 tursekk。" },
  sekk:{ zh:"袋子；大袋/麻袋（依材质和用途）；背包（特定语境）", note:"泛指可装物品的袋状容器；ryggsekk 才明确是背在背上的包。不要把 sekk 单独固定翻成“背包”。" },
  guide:{ zh:"导游；指南/使用指南（依指人还是资料）", note:"en guide 可指带领游客的人，也可指帮助读者了解或使用某事物的指南；动词 å guide 是带领/指导。结合冠词和句子对象判断。" },
  "sjekke-inn":{ zh:"办理值机；办理入住；办理登记（依场景）", note:"机场语境是办理乘机值机，酒店语境是办理入住；sjekke inn bagasje 则是托运行李。这个分离动词短语在主句中可拆开：Jeg sjekker inn på hotellet。" },
  bensinstasjon:{ zh:"加油站；为机动车加注燃料的场所" },
  bil:{ zh:"汽车；机动车（通常指轿车）" },
  billett:{ zh:"票；车票；入场券（凭票乘车或进入活动/场所）" },
  buss:{ zh:"公共汽车；公交车" },
  bussjåfør:{ zh:"公交车司机；驾驶公共汽车的人" },
  bussrute:{ zh:"公交线路；公交车固定行驶的路线", note:"指线路/路线，不等于时刻表；“时刻表”通常是 rutetabell。" },
  busstur:{ zh:"一趟公交车程；乘公交的一次行程" },
  by:{ zh:"城市；市镇；（定指 byen 依语境可指）城里/市中心", note:"常见 byen 可表示“城里、进城”；byen 不总是抽象的整座城市，需结合方向与搭配理解。" },
  bytte:{ zh:"更换；交换；换乘（依宾语和结构）", note:"bytte tog/buss=换乘火车/公交；bytte klær=换衣服；bytte én ting mot en annen=以一物换另一物。" },
  båt:{ zh:"船；船只（常见水上交通工具）" },
  dra:{ zh:"去；出发/前往；拉、拽（依结构和语境）", note:"dra hjem=回家，dra til Bergen=去卑尔根；dra i døra=拉门。先看方向补语或宾语来区分出行与拉拽。" },
  fly:{ zh:"飞机；（依语境）航班/班机", note:"此条是中性名词 et fly，指飞机；注意与阴性名词 ei flue（苍蝇）以及动词 å fly（飞）区分。" },
  flybuss:{ zh:"机场巴士；往返机场与市区等地点的巴士" },
  fra:{ zh:"从；来自；自……起（表示地点、来源或时间起点）", note:"fra Oslo=从奥斯陆；et brev fra henne=她寄来的信；fra mandag=从周一开始。结合后面的地点、来源或时间判断。" },
  jernbanestasjon:{ zh:"铁路车站；火车站" },
  kart:{ zh:"地图；图表/菜单等以图示或列表呈现的内容（依语境）", note:"et kart over Norge=挪威地图；词典也列有 spisekart（菜单）、vinkart（酒单）等复合词用法。另有同形阳性词 kart，指未成熟果实，需由词性/语境区分。" },
  kilometer:{ zh:"公里；千米（长度单位，1 公里 = 1,000 米）" },
  kjøre:{ zh:"驾驶；开车；乘车行驶；开车运送（依句型）", note:"kjøre bil=开车；bussen kjører=公交车行驶；kjøre noen hjem=开车送某人回家。结合主语和宾语判断动作关系。" },
  koffert:{ zh:"行李箱；旅行箱" },
  kontrollere:{ zh:"检查；核对；控制（依对象和语境）", note:"kontrollere passet/billetten=检查护照/车票；核对信息时译“核对”；对设备操作时才译“控制”。通常比 sjekke 正式。" },
  lastebil:{ zh:"卡车；货车（用于载运货物的较大型汽车）" },
  lufthavn:{ zh:"机场；航空港（较正式说法）" },
  sjåfør:{ zh:"司机；驾驶员" },
  tog:{ zh:"火车；列车；（固定表达中）游行队伍/队列", note:"交通语境是火车/列车，如 toget går（火车发车）；gå i tog 是“参加游行”，不是乘坐火车。" },
  reise:{ zh:"旅行；出行；乘坐交通工具出行", note:"reise med buss/tog/båt=乘公交/火车/船出行；表示出发或去某地也常用 dra。" },
  du:{ forms:["du","deg","din / ditt / dine"], labels:["主格","宾格/介词后","所有格（依名词性数）"], note:"主格 du 作主语；宾格/介词后用 deg；所属关系用 din（阳/阴性单数）、ditt（中性单数）、dine（复数/定指复数），如 bilen din、huset ditt、bøkene dine。" },
  den:{ note:"den 可作阳性/阴性单数名词前的指示限定词（den røde bilen），也可作“它/那一个”的代词。与名词搭配时，形容词用定指形式（røde），不能把 den 当作独立冠词使用。" },
  det:{ note:"det 可作中性名词的“它/那个”，也可作形式主语/形式宾语：Det er kaldt（天气很冷）、Det regner（下雨）、Det er viktig å øve（练习很重要）。注意形式主语 det 不对应具体的‘它’。" },
  fram:{ note:"副词表示向前、到前面或进展；Bokmål 中 frem 也是常见拼法变体。常见搭配 gå fram（向前走/进行）、komme fram（到达/显现）；和介词 fra（从）不要混淆。" },
  gjerne:{ forms:["gjerne","heller","helst"], labels:["原级","比较级","最高级"], note:"可表示乐意/愿意（Ja, gjerne!）、想要（Jeg vil gjerne ha kaffe）或频率较高（ofte gjerne 依语境）。比较级 heller 常表‘宁愿’，最高级 helst 表‘最愿意/最好’；不是简单的形容词比较。" },
  halv:{ note:"形容词按名词性数变化：en halv time、et halvt eple、halve kaka；常用时间搭配 om en halv time（半小时后）。不要和 halvtimes（复合词前缀）混为同一结构。" },
  klokke:{ note:"名词可指钟、手表，也可在 klokka er … 中表示报时；口语常用阴性定指 klokka，Bokmål 也有 klokke/klokken。Klokka er kvart over sju = 七点一刻。" },
  på:{ note:"på 的意义高度依赖搭配，可表示在表面（på bordet）、在/去某些地点（på skolen）、乘坐/从事（på bussen / på jobb）。不要把它机械地一律译成‘在……上’，应记固定介词搭配。" },
  takk:{ note:"takk 常作为感叹/礼貌表达（Takk!、Tusen takk for hjelpen!）；也可作名词 en takk（感谢/谢意），但日常使用时通常不说 takk 的普通复数。" },
  til:{ note:"til 常标示方向/终点（reise til Bergen）、收受者（gi boka til meg）、截止时间或用途。固定搭配必须随动词学习；别把所有 til 一律只译成‘到’。" },
  time:{ note:"en time 有几种常见义：60 分钟、一节课（常为 40/45 分钟），以及预约/就诊时间（time hos legen）。用上下文判断，不要把所有场景都译成‘小时’；常见复数为 timer，定指复数 timene。" },
  unnskyld:{ note:"作道歉（Unnskyld, jeg kom for sent）或礼貌地引起注意/请求让路（Unnskyld, hvor er stasjonen?）。与 beklager 相比，unnskyld 常见于日常口语。" },
  vi:{ forms:["vi","oss","vår / vårt / våre"], labels:["主格","宾格/介词后","所有格（依名词性数）"], note:"主格 vi 作主语，宾格/介词后用 oss；所属关系用 vår（阳/阴性单数）、vårt（中性单数）、våre（复数/定指复数），如 bilen vår、huset vårt、barna våre。" },
  musikk:{ forms:["musikk","musikken"], labels:["无冠词/不定形式（通常不可数）","定指单数"], note:"musikk 通常作不可数名词：lytte til musikk（听音乐）、spille musikk（演奏音乐）；特定音乐可说 musikken。一般不加不定冠词 en，也不需要常规复数。" },
  ordne:{ forms:["ordne","ordner","ordnet / ordna","ordnet / ordna"], labels:["原形","现在时","过去时（两种常见形式）","完成分词（两种常见形式）"], note:"可表示整理（ordne rommet）、安排（ordne et møte）或处理/解决（ordne problemet）。常用 ordne opp i noe（处理某事）；过去时和完成分词可用 ordnet 或 ordna。" },
  plass:{ note:"可指座位/位置（en plass）、空间容量（Er det plass til …?）或地点。常用 ha plass til + 名词表示‘有空间容纳……’；说具体地点也常用 sted。" },
  møbel:{ note:"et møbel 指一件家具；泛指家具体系时常用复数 møbler（家具），不要把中文‘家具’总当成不可数单数。复数不定 møbler，定指 møblene。" },
  morfar:{ note:"专指母亲的父亲（外祖父）；父亲的父亲是 farfar。复数 morfedre / morfedrene，指多位外祖父或相关亲属时才使用。" },
  mormor:{ note:"专指母亲的母亲（外祖母）；父亲的母亲是 farmor。常见形式有 ei/en mormor，定指 mormora/mormoren；复数 mormødre。" },
  skjørt:{ forms:["et skjørt","skjørtet","skjørt / skjørter","skjørtene"], labels:["不定单数","定指单数","不定复数（两种形式）","定指复数"], note:"指裙子/半身裙。中性名词；复数可见 skjørt 或 skjørter，定指复数 skjørtene。常见搭配 ha på seg et skjørt（穿裙子）。" },
  bolle:{ note:"可指甜面包/小圆面包，也可指碗（依语境）；作面包时常在 kanelbolle 等复合词中明确种类。此卡例句讲‘肉桂面包’，不可误解成一碗东西；阴性/阳性用法皆见。" },
  dyne:{ note:"盖在身上的被芯/被子，不是被套；被套是 dynetrekk。常见阴性形式 ei dyne–dyna–dyner–dynene，也可用 en dyne–dynen。" },
  fødselsdag:{ note:"生日；与更口语、常见的 bursdag 基本同义。说某人何时过生日可用 ha fødselsdag i mai；不等同于 fødsel（分娩/出生这件事）。" },
  koselig:{ forms:["koselig","koselig","koselige","koseligere","koseligst / koseligste"], labels:["阳性/阴性","中性","复数/定指","比较级","最高级（表语/定指）"], note:"描述温馨、舒适、惬意或令人愉快的氛围：en koselig kveld、et koselig hjem。比较级 koseligere；最高级 koseligst（表语）/koseligste（定指）。" },
  kryss:{ note:"可指道路交叉处/十字路口，也可指叉号、勾号；本卡句子 Ta til høyre i neste kryss 中指‘下一个路口’。若特指有红绿灯的路口，用 lyskryss。" },
  lomme:{ note:"指缝在衣物上的口袋，也可指小型凹处/空间；Bokmål 接受阴性与阳性形式，常见 ei lomme–lomma 或 en lomme–lommen。i lomma mi = 在我的口袋里。" },
  banan:{ note:"水果名词，阴性或阳性形式都可见；常用 en banan–bananen–bananer–bananene。例句中的 en banan 表示一根香蕉，训练中应连冠词一起记名词性。" },
  bestemme:{ note:"bestemme noe = 决定/确定某事；bestemme seg for å gjøre noe = 决定做某事。后一个结构必须带反身代词 seg（依主语变成 meg/deg/oss 等），如 Vi bestemmer oss for å ta toget。" },
  meter:{ note:"长度单位米；常见结构 to meter lang（两米长）。数字后单位名词通常用不定复数 meter，不加冠词；定指复数 meterne，如 de siste meterne。" },
  minutt:{ note:"et minutt 是一分钟；数字大于一通常用复数 minutter：om fem minutter（五分钟后）。注意 minutt 是中性名词，定指单数 minuttet、定指复数 minuttene。" },
  ansikt:{ note:"面部/脸；中性名词 et ansikt，复数 ansikter，定指复数 ansiktene。洗脸常说 vaske ansiktet；身体部位常用定指形式，而非 et ansikt。" },
  brødhylle:{ note:"透明复合词 brød + hylle（面包 + 架子），不作为独立词头假称已收录；形态按 Bokmålsordboka 中 hylle 的性、变格及复合词规则构成，词义按超市语境解释为面包货架。" },
  "ei-article":{ forms:["ei"], labels:["阴性单数不定冠词"], note:"放在阴性名词前，如 ei bok、ei jente；Bokmål 中阴性名词也常可用通性 en（en bok）。ei 本身不变形，注意它是冠词用法，不是数字 én（一个/仅一个）。" },
  "en-determiner":{ forms:["en / ei / et"], labels:["阳性/通性","阴性","中性"], note:"无重音时是不定冠词，随名词性别变化：en bil、ei bok / en bok、et hus。它表示普通的‘一个/一位’，强调数量时用带重音的 én/éi/ett；不要与代词 en（泛指‘人们’）混为一类。" },
  "en-pronoun":{ note:"泛指代词 en 可表示‘一个人/人们/你（泛指）’，如 En lærer mye av å snakke med folk（人们能从交谈中学到很多）。它不是名词前的不定冠词 en；也常见更明确的泛指代词 man。" },
  "dette-det":{ note:"dette 是指示词 denne 的中性形式：dette barnet（这个孩子）、dette huset（这栋房子）；名词采用定指形式。单独使用也表示‘这个/这件事’，句首大写 Dette。" },
  "disse-det":{ note:"disse 是 denne/dette 的复数指示形式，可单独作代词，也可放在定指复数名词前：disse skoene（这些鞋）、disse bøkene（这些书）。" },
  "øye":{ note:"中性名词 et øye；复数不规则为 øyne，定指复数 øynene。常见搭配 få noe i øyet（有东西进眼睛）、lukke øynene（闭上眼睛）。" },
  "øre":{ note:"耳朵用法为 et øre–øret–ører–ørene；也可表示听觉或货币单位 øre。谈货币时常见 50 øre（50 分），不要误认为耳朵的复数词形。" },
  "kne":{ note:"中性名词，复数是不规则的 knær，定指复数 knærne；表示疼痛常用 ha vondt i kneet，受伤可说 slå kneet。" },
  "nakke":{ note:"指颈部后侧/后颈，不是整个脖子前部；前颈/喉部通常说 hals。常用 være stiv i nakken（后颈僵硬）。" },
  "tunge-noun":{ note:"指口腔中的舌头，也可表示语言/舌头状物；此卡例句 stikke ut tunga 指伸出舌头。名词可用 ei/en tunge，定指阴性 tunga 或阳性 tungen。" },
  "gress":{ word:"et gress", zh:"草；草类植物；覆盖地面的草（依语境）", forms:["et gress","gresset","gress","gressene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"常作集合/物质名词：gresset er grønt（草是绿的）、klippe gresset（修剪草坪上的草）。若强调一片修整好的草坪，常用 plen；一根草可说 et gresstrå。词典另有马铃薯等根茎植物的茎叶义及俚语 cannabis 义，初级日常先掌握植物/地表覆盖义。https://ordbokene.no/bm/gress" },
  "elv":{ forms:["ei/en elv","elva / elven","elver","elvene"], labels:["不定单数（阴/阳性）","定指单数（阴/阳性）","不定复数","定指复数"], note:"河流；Bokmål 可用阴性 elva 或通性 elven，例句沿用阴性 elva。与 innsjø（湖）区分：河水有流向，湖通常为内陆静水体。" },
  "telle":{ note:"表示数数、清点，也可表示某物算作/有意义：telle til ti、telle hvor mange kopper（数有多少个杯子）。过去时 telte，完成分词 telt。" },
  "falle":{ note:"表示跌倒、落下或数值下降；常见搭配 falle ned（掉下来）、falle på gulvet（摔在地上）。过去时和完成分词都为 falt。" },
  "slå":{ note:"动词有多义。本卡 slå på lyset 是固定口语搭配‘开灯’，不表示击打灯；对应 slå av lyset（关灯）。其他语境可表示击打、敲门或打败，需结合宾语和介词判断。" },
  "leve":{ note:"可表示活着/生存，也可表示过某种生活或以某事为生；leve et rolig liv = 过平静的生活。过去时 levde，完成分词 levd。" },
  "selge":{ note:"表示出售/销售，通常直接接售卖物：selge brød（卖面包）；卖给某人用 selge noe til noen。过去时 solgte，完成分词 solgt。" },
  "lukke":{ note:"表示把门、窗、盒子或眼睛合上/关上；关商店/机构或停止营业也常用 stenge。过去时 lukket，完成分词 lukket。" },
  "kø":{ note:"en kø 指等候服务的人或车辆排成的队伍；常说 stå i kø（排队）、lang kø foran kassa（收银台前排长队）。" },
  "lommebok":{ forms:["ei/en lommebok","lommeboka / lommeboken","lommebøker","lommebøkene"], labels:["不定单数（阴/阳性）","定指单数（阴/阳性）","不定复数","定指复数"], note:"钱包/钱夹；词典接受阴性或阳性变格，如 ei lommebok–lommeboka 或 en lommebok–lommeboken。也可转喻个人经济状况（påvirke lommeboka）。" },
  temperatur:{ note:"温度；说天气温度常用 temperaturen er … grader（气温是……度）。temperatur 也用于 temperaturforskjell（温差）等复合词，不要把它和 vær（天气状况）混为一谈。" },
  søsken:{ forms:["et søsken","søskenet","søsken","søskena / søsknene"], labels:["不定单数","定指单数","不定复数","定指复数（两种形式）"], note:"表示同父母的兄弟姐妹。单数 et søsken 指其中一位，通常更常用复数 søsken 泛指兄弟姐妹；定指复数有 søskena、søsknene。询问‘你有兄弟姐妹吗’说 Har du søsken?" },
  forkjølelse:{ note:"名词 en forkjølelse 是一次感冒；形容词 forkjølet 表示‘感冒了’，如 Jeg er forkjølet。不要把名词词头和形容词混作同一词形。" },
  smerte:{ note:"smerte 表示疼痛；谈身体痛楚时常用复数 smerter 或 ha vondt i + 身体部位：Hun har smerter i ryggen / Hun har vondt i ryggen。" },
  resept:{ note:"处方；常见搭配 få/skrive ut en resept（开处方/拿到处方）、med resept（凭处方）。区分 resept（处方）与 kvittering（收据）。" },
  sammenlignet:{ pos:"分词短语", note:"sammenlignet med 是 sammenligne（比较）的过去分词短语，整体相当于‘与……相比’，后接比较对象；并非独立词根或真正的介词词形：Sammenlignet med i fjor …。词典也收录 han er liten sammenlignet med broren sin。" },
  hode:{ forms:["et hode","hodet","hoder","hodene / hoda"], labels:["不定单数","定指单数","不定复数","定指复数（变体）"], note:"中性名词，常用定指单数 hodet：vondt i hodet（头痛）、vaske håret/ hodet（依语义使用）。身体疼痛更自然说 Jeg har vondt i hodet，而不是直译‘头有痛’。" },
  lege:{ note:"医生；常说 bestille/få time hos legen（预约/看医生）、gå til lege（去看医生）。hos legen 中名词为定指形式。" },
  apotek:{ note:"药店/药房；常说 gå på apoteket（去药店），在挪威通常在药店买非处方药。买处方药需要 resept。" },
  trenge:{ forms:["å trenge","trenger","trengte","trengt"], labels:["原形","现在时","过去时","完成分词"], note:"trenge – trenger – trengte – har trengt，表示需要：Jeg trenger hjelp（我需要帮助）。另有‘挤过/穿过’等较少见义项，本级先学‘需要’。" },
  medisin:{ note:"药；医学（依语境）。‘服药’常说 ta medisiner/ta medisin；medisin 也指医学学科，避免仅记成一种具体药片。" },
  barnebarn:{ forms:["et barnebarn","barnebarnet","barnebarn","barnebarna / barnebarnene"], labels:["不定单数","定指单数","不定复数","定指复数（两种形式）"], note:"性别中立，可指孙子女或外孙子女。单数与不定复数同形 barnebarn；定指复数可用 barnebarna 或 barnebarnene，结合上下文判断人数及亲属关系。" },
  ønske:{ forms:["å ønske","ønsker","ønsket / ønska","ønsket / ønska"], labels:["原形","现在时","过去时","完成分词"], note:"表示希望/祝愿。ønske seg noe 是‘希望得到某物’，如 Barnet ønsker seg en sykkel；ønske noen god helg 是‘祝某人周末愉快’。反身代词 seg 是结构的一部分，不可省略后仍期待同一意思。" },
  papir:{ note:"纸；纸张，也可指文件/证件。材料义常作不可数：skrive på papir（在纸上写）；可数的 papirer 常指文件、证件或多张纸。" },
  våt:{ forms:["våt","vått","våte","våtere","våtest / våteste"], labels:["阳/阴性","中性","复数/定指","比较级","最高级"], note:"表示湿的、被水浸湿的：en våt jakke、et vått gulv、våte klær。中性加双 t；比较级 våtere、最高级 våtest/ våteste。天气‘雨天’一般说 regnvær，不用 våt 代替。" },
  alder:{ note:"表示年龄/年纪，常说 Hvor gammel er du?（你多大？）、i ung alder（在年轻时）以及 folk i alle aldre（各年龄段的人）。这里的‘年龄’不是时间长度的计量词 år；词典列有复数搭配 aldre/aldrer。" },
  bryllup:{ note:"婚礼/婚宴。自然说法包括 Vi skal i bryllup i juni（我们六月要去参加婚礼）或 Vi skal i bryllupet til søsteren hennes（我们要参加她姐姐/妹妹的婚礼）。不说不自然的 i bryllup til …。" },
  fjell:{ note:"山；复数 fjell 可指山脉/山区。på fjellet 常表示在山里/山区，不必理解成站在某一座山顶；til fjells 表示去山区。" },
  folk:{ forms:["et folk","folket","folk","folkene"], labels:["不定单数（民族/群体）","定指单数","不定复数/泛指人们","定指复数（具体群体）"], note:"泛指‘人们’时通常直接用 folk，不加 et，也常见 Det bor folk her（这里有人住）。et folk 可指一个民族/群体；特定国家的人民可用 folket。两种用法不要混淆。" },
  enig:{ forms:["enig","enig","enige","mer enig / mer enige","mest enig / mest enige"], labels:["阳/阴性","中性","复数/定指","比较级（分析式）","最高级（分析式）"], note:"表示意见一致。结构：enig med noen（同意某人），enig i noe/at …（赞同某事/认为……）。注意不能机械地把 med 和 i 互换。" },
  besteforelder:{ forms:["en besteforelder","besteforelderen","besteforeldre","besteforeldrene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"一个祖父或祖母的性别中立统称；复数 besteforeldre 是祖父母/祖辈。具体关系可用 bestemor/bestefar。" },
  årstid:{ forms:["ei/en årstid","årstida / årstiden","årstider","årstidene"], labels:["不定单数（阴/阳性）","定指单数（变体）","不定复数","定指复数"], note:"一年中的季节；四季为 vår（春）、sommer（夏）、høst（秋）、vinter（冬）。可说 på denne årstida（在这个季节）。词典接受阴性或阳性变格。" },
  liv:{ forms:["et liv","livet","liv","liva / livene"], labels:["不定单数","定指单数","不定复数","定指复数（变体）"], note:"生命、生活；常说 leve et godt liv（过好生活）、i hele livet（在一生中）。中性名词的不定复数 liv 与单数同形；定指复数有 liva/livene。" },
  melding:{ forms:["ei/en melding","meldinga / meldingen","meldinger","meldingene"], labels:["不定单数","定指单数（变体）","不定复数","定指复数"], note:"消息、通知；手机短信/消息常用 sende/få en melding（发/收到消息）。词典接受阴性或阳性形式；别与 beskjed（口头/书面传话）完全等同。" },
  prate:{ forms:["å prate","prater","pratet / prata","pratet / prata"], labels:["原形","现在时","过去时（变体）","完成分词（变体）"], note:"日常口语‘聊天、交谈’，比 snakke 更偏轻松闲聊；可说 prate med noen（和某人聊天）、prate om noe（聊某事）。" },
  "rød-adj":{ forms:["rød","rødt","røde","rødere","rødest / rødeste"], labels:["阳/阴性","中性","复数/定指","比较级","最高级"], note:"颜色红；形容词随名词变化：en rød bil、et rødt hus、røde biler。人脸红可说 bli rød i ansiktet。" },
  sakte:{ forms:["sakte","saktere","saktest / sakteste"], labels:["原级","比较级","最高级"], note:"副词表示慢慢地，如 Kjør sakte!（慢点开！）；也可作形容词 sakte musikk。表示做事慢可以用 sakte 或 langsomt，具体看搭配。" },
  selvfolgelig:{ pos:"副词/形容词", note:"常用回应副词‘当然、自然’：Ja, selvfølgelig!（当然！）。也可作形容词‘理所当然的’，如 en selvfølgelig konsekvens。多数日常表达里按副词学习，不要错误地给副词添加形容词词尾。" },
  skinke:{ forms:["ei/en skinke","skinka / skinken","skinker","skinkene"], labels:["不定单数（阴/阳性）","定指单数（变体）","不定复数","定指复数"], note:"火腿，尤指猪后腿肉制成的肉类；日常三明治馅料常见 kokt skinke（熟火腿）、spekeskinke（风干火腿）。词典也列有较少见的身体部位义‘臀部’。" },
  skive:{ forms:["ei/en skive","skiva / skiven","skiver","skivene"], labels:["不定单数（阴/阳性）","定指单数（变体）","不定复数","定指复数"], note:"一片/薄片，常用于食物：en skive brød（ 一片面包）、ei skive ost（一片奶酪）。量词结构 skive + 食材通常不加额外冠词。" },
  søt:{ forms:["søt","søtt","søte","søtere","søtest / søteste"], labels:["阳/阴性","中性","复数/定指","比较级","最高级"], note:"可形容味道甜，也可形容人或动物可爱、讨喜；en søt katt、et søtt eple、søte barn。评价成年人时‘可爱/亲切’语气依关系和情境。" },
  spansk:{ forms:["spansk","spansk","spanske","mer spansk","mest spansk"], labels:["阳/阴性","中性","复数/定指","比较级","最高级"], note:"形容词表示西班牙的/西班牙语的：spansk mat、spansk film。语言名词通常小写且不加冠词：Jeg snakker spansk。名词化用法需有上下文，不是‘西班牙人’的默认形式。" },
  spiller:{ note:"spiller 是名词 spiller（选手/演奏者/玩家）的定指形式，也与动词 spille 的现在时同形，需看句法：spilleren scorer（选手得分）/ hun spiller piano（她弹钢琴）。本卡按名词练习。" },
  svensk:{ forms:["svensk","svensk","svenske","mer svensk","mest svensk"], labels:["阳/阴性","中性","复数/定指","比较级","最高级"], note:"形容词表示瑞典的/瑞典语的：svensk kaffe、svensk musikk。语言名词用瑞典语为 svensk；瑞典人一般说 en svenske / ei svensk kvinne，不能把 svensk 直接当所有语境中的‘瑞典人’。" },
  syltetøy:{ forms:["et syltetøy","syltetøyet","syltetøy","syltetøyene"], labels:["不定单数","定指单数","不定复数（少用）","定指复数（少用）"], note:"果酱，通常作不可数食物名词：brød med syltetøy（抹果酱的面包）。具体种类可说 jordbærsyltetøy（草莓酱）；买一罐用 et glass syltetøy。" },
  terrasse:{ note:"露台/室外平台；住宅场景常说 sitte på terrassen（坐在露台上）。也可指坡地梯田式台地或大型建筑的户外平台，依上下文判断。" },
  venninne:{ note:"女性朋友；在亲密关系语境也可能指女友，但不能不看上下文就默认是恋爱关系。男性朋友通常称 venn。" },
  anbefale:{ forms:["å anbefale","anbefaler","anbefalte","anbefalt"], labels:["原形","现在时","过去时","完成分词"], note:"推荐某物/建议某人做某事：anbefale en bok; anbefale noen å prøve noe。完成分词 anbefalt。常比 foreslå 更明确表达‘我认为这个选择不错’。" },
  bygg:{ forms:["et bygg","bygget","bygg","byggene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"指建筑物/楼时，词典给出的主要变格为 et bygg – bygget – bygg – byggene；不要把对应名词 bygning 的复数 bygninger 当成 bygg 的词形。bygg 也有谷物“裸麦/大麦”义，需看语境。" },
  "e-post":{ forms:["en e-post","e-posten","e-poster","e-postene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"既可指电子邮件这一消息，也可指电子邮件系统/地址；写邮件可说 sende en e-post。常见拼写为 e-post，复数连字符保留。" },
  håpe:{ forms:["å håpe","håper","håpet","håpet"], labels:["原形","现在时","过去时","完成分词"], note:"希望、盼望；常接 at 从句：Jeg håper at du kommer（我希望你来）；口语可省略 at。表达‘希望做某事’可用 håpe å + 动词原形。" },
  kino:{ note:"电影院，也可在 dra på kino（去看电影）中指看电影这项活动。谈建筑地点常用 på kino / kinoen；不能简单把 kino 总译为‘电影’（film）。" },
  konsert:{ note:"音乐会/现场演出；常说 gå på konsert（去听音乐会）、holde en konsert（举办音乐会）。不专指古典音乐，需由上下文说明类型。" },
  kurs:{ forms:["et kurs","kurset","kurs / kurser","kursene / kursene"], labels:["不定单数","定指单数","不定复数（两种写法）","定指复数"], note:"课程/培训：gå på kurs（参加培训）、et norskkurs（挪威语课程）。也有航向/路线等专业义项；学习场景中优先记课程义。" },
  akkurat:{ note:"依语境表示‘正好/恰好’、‘准确地’或‘刚刚’：akkurat klokka to（正好两点）、akkurat det（正是那个）、Jeg kom akkurat（我刚到）。不要只固定记一个中文对应。" },
  arrangement:{ note:"活动/安排/活动项目；holde et arrangement（举办活动）、et kulturelt arrangement（文化活动）。表示日常预约安排时 ofte plan/avtale 更自然，arrangement 常指组织起来的活动。" },
  arrangere:{ forms:["å arrangere","arrangerer","arrangerte","arrangert"], labels:["原形","现在时","过去时","完成分词"], note:"组织、安排、举办：arrangere en fest/konsert。也可指音乐编曲；根据宾语区分‘组织活动’和‘编曲’。过去时 arrangerte，完成分词 arrangert。" },
  bank:{ note:"常见义为银行；也可指河岸/岸边（en elvebredd/en bank），或一排/一列等。钱和账户场景是银行，地理句子中的 bank 可能是岸边，需由搭配判断。" },
  bokstav:{ note:"字母、文字字符。一个字母是 en bokstav；整个字母表是 alfabetet。注意字母与 ord（单词）不同。" },
  cola:{ note:"可乐饮料；点单时一杯可说 en cola，泛指饮料时也常说 cola 不定量。品牌名如 Cola-Cola 按品牌拼写大写，普通饮料名 cola 小写。" },
  dagsbillett:{ note:"日票/当天有效的通票，常用于公共交通、博物馆或活动；有效范围由售票规则决定，不能默认在所有地区、所有线路通用。" },
  danse:{ forms:["å danse","danser","danset / dansa","danset / dansa"], labels:["原形","现在时","过去时（变体）","完成分词（变体）"], note:"跳舞：danse med noen（和某人跳舞）、danse til musikk（随着音乐跳舞）。可指社交舞，也可泛指跳舞活动。" },
  arbeide:{ forms:["arbeide","arbeider","arbeidet / arbeida / arbeidde","arbeidet / arbeida / arbeidde"], labels:["原形","现在时","过去时（多种词典认可形式）","完成分词（多种词典认可形式）"], note:"较正式或书面语的‘工作/劳动’，口语中常用 jobbe。Bokmålsordboka 收录过去式/完成分词 arbeidet、arbeida、arbeidde / arbeidd 等形式；此处日常例句采用常见的 arbeidet。" },
  brenne:{ forms:["brenne","brenner","brant / brente","brent"], labels:["原形","现在时","过去时（依及物/不及物用法）","完成分词"], note:"不及物‘燃烧着’常用 brant（Peisen brant）；及物‘把某物烧掉/烧制’常用 brente（Hun brente brevet）。完成分词 brent。具体火焰燃烧与主动点火需按句法区分。" },
  dø:{ note:"表示人或动物死亡/去世；也可比喻火焰熄灭或声音渐弱。常用过去时 døde、完成分词 dødd；谈灯熄灭日常更常用 slokne/slu(k)ke，而非一律用 dø。" },
  bestemor:{ forms:["ei/en bestemor","bestemora / bestemoren","bestemødre","bestemødrene"], labels:["不定单数（阴/阳性）","定指单数（阴/阳性）","不定复数","定指复数"], note:"既可指母亲的母亲，也可指父亲的母亲；想区分可分别用 mormor（外婆）和 farmor（奶奶）。Bokmål 允许 bestemor 使用阴性或阳性变格。" },
  bestefar:{ note:"泛称祖父/外祖父，不区分父系母系；区分时分别用 farfar（爷爷）和 morfar（外公）。不规则复数 bestefedre / bestefedrene。" },
  bestille:{ note:"可表示订购/预订、在餐馆点餐或预约服务：bestille et bord（订桌）、bestille kaffe（点咖啡）、bestille time hos legen（预约看医生）。点餐说 to kaffe 时语境中省略 kopper（两杯）。" },
  bygge:{ forms:["bygge","bygger","bygde / bygget","bygd / bygget"], labels:["原形","现在时","过去时","完成分词"], note:"表示建造或搭建：bygge et hus、bygge en modell。词典列 bygde/bygd，也接受 bygget 作为过去式和完成分词；例句 De bygger … 描述正在施工。" },
  bytur:{ note:"一次去城里购物、办事或逛街的行程；常见结构 dra på bytur（进城逛逛）。不要机械理解为城市观光旅游，需看上下文。" },
  diskutere:{ note:"直接接讨论对象：diskutere planen（讨论计划），一般不在动词后加 om。与某人讨论可用 diskutere noe med noen。" },
  elske:{ note:"强度通常比 like（喜欢）高，可指爱某人，也可口语中表示非常喜欢某事/食物。此卡例句的 barna sine 明确指自己的孩子。" },
  farge:{ note:"最常见义是颜色（Hvilken farge har bilen?）；也可指染料/着色材料或给某物着色。作为颜色名词常用 en farge–fargen–farger–fargene。" },
  fersk:{ forms:["fersk","ferskt","ferske","ferskere","ferskest / ferskeste"], labels:["阳性/阴性","中性","复数/定指","比较级","最高级（表语/定指）"], note:"形容食品时是新鲜的；也可指刚来的/刚发生的（ferske nyheter）。en fersk fisk、ferskt brød、ferske grønnsaker；比较级 ferskere，最高级 ferskest/ferskeste。" },
  fisk:{ note:"可数时指一条鱼（en fisk–fisken–fisker–fiskene）；谈食材时通常无冠词，如 spise fisk til middag（晚饭吃鱼）。例句讲的是鱼肉食材，不是某一条鱼。" },
  fortsette:{ note:"表示继续或持续。常见结构 fortsette å + 动词原形（继续做某事），如 fortsette å øve；也可 fortsette med + 名词/活动。过去时 fortsatte，完成分词 fortsatt。" },
  pålegg:{ forms:["et pålegg","pålegget","pålegg","påleggene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"挪威日常饮食语境中指放在面包上的配料/冷食，如奶酪、火腿、肝酱；常作集合/物质名词，如 velge pålegg。不要误译为‘额外收费/规定’，那是其其他义项。" },
  paprika:{ note:"本卡指甜椒/彩椒这种蔬菜，不是香料粉 paprika（红椒粉）。可说 en rød paprika；按份量或颜色语境判断具体指整只甜椒还是菜料。" },
  potet:{ note:"常见蔬菜名词，阴性/阳性都可使用：en potet–poteten，复数 poteter–potetene；在菜肴语境中常用复数 poteter，如 koke poteter。" },
  "møte-verb":{ note:"作动词时表示遇见/会见、迎接或面对；直接接人或事物：møte en venn、møte et problem。过去时 møtte，完成分词 møtt；不要与名词 et møte（会议/会面）混为一张卡。" },
  endelig:{ pos:"副词/形容词", forms:["endelig","endelig","endelige","endelig"], labels:["阳性/阴性形容词","中性形容词","复数/定指形容词","副词（不变）"], note:"本句 Endelig er ferien her! 中是副词‘终于’，句首引发 V2 倒装：变位动词 er 在主语 ferien 前。作形容词时可表示‘最终的’，如 den endelige planen；不要把此例句标成形容词用法。" },
  humør:{ forms:["et humør","humøret","humør","humørene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"常见搭配 være i godt/dårlig humør（心情好/不好）；在该搭配中用 humør 不定单数，形容词用中性 godt。也可说 humøret skifter（情绪变化）。" },
  denne:{ note:"指近处的单数名词：denne uka（这周，阴性）、dette huset（这栋房子，中性）；复数用 disse。Bokmål 中名词通常随指示词用定指形式：denne uka，而非 denne uke。" },
  faktisk:{ pos:"副词/形容词", forms:["faktisk","faktisk","faktiske","faktisk"], labels:["阳性/阴性形容词","中性形容词","复数/定指形容词","副词（不变）"], note:"副词 faktisk 表‘事实上/确实’，如 Det var faktisk lettere enn jeg trodde；形容词表示实际的/事实上的，按性数变化：faktisk grunn、faktiske forhold。" },
  "høyre-adj":{ note:"本条只教方位形容词‘右边的’，常见定语 høyre hånd/øye/side；形容词通常不按普通阳性/中性范式变化。høyre 也可作名词表示右手/右脚，另有政治义，本卡不练那些用法。" },
  hundre:{ note:"基数词 100；数字后直接修饰单位时通常不加冠词：hundre kroner。作名词时常见 et hundre，但数词用法本身不变格；hundrevis av 表示‘数百’。" },
  ja:{ note:"最常见是肯定答词，也可表示同意、确认或加强语气；语调和位置会改变语用含义。本卡按句首答应参加会议的用法，译作‘好/是的’。" },
  nei:{ note:"用于否定回答，也可组成礼貌拒绝 nei takk（不，谢谢）。本句 Nei takk, jeg vil bare ha vann 表示礼貌拒绝其他饮品，不是生硬的‘不’。" },
  så:{ note:"可表示然后/于是（og så）、程度‘如此/这么’（så stor），也可作‘那么’等语气词。本例与 først 构成先后顺序：Først …, og så …。" },
  samme:{ note:"表示同一个/同样的，通常放在名词前；可说 samme buss，也可用带指示词的 den samme bussen。常与 bestemt form 搭配，形式通常不变。" },
  én:{ forms:["én / éi / ett"], labels:["强调数量‘一个’（依名词性别）"], note:"带重音的 én 用于强调‘一个/仅一个’，名词性别分别写 én（阳性）、éi（阴性）、ett（中性）；与不带重音的冠词 en/ei/et 区分。例句 én person 强调只剩一个人。" }
};
