  bak:"https://ordbokene.no/bm/bak", ballett:"https://ordbokene.no/bm/ballett", ballspill:"https://ordbokene.no/bm/ballspill", begynnelse:"https://ordbokene.no/bm/begynnelse", begynnerkurs:"https://ordbokene.no/bm/begynnerkurs", bestevenn:"https://ordbokene.no/bm/bestevenn", bort:"https://ordbokene.no/bm/bort", bråk:"https://ordbokene.no/bm/br%C3%A5k", byggfirma:"https://ordbokene.no/bm/byggfirma",
