Object.assign(V2_REVIEW_CORRECTIONS, {
  deltaker:{ forms:["en deltaker","deltakeren","deltakere","deltakerne"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"参加者、参与者；比赛语境可译参赛者：Alle deltakerne får et diplom（所有参加者都会得到一张证书）。动词是 delta i（参加），注意搭配介词 i。" },
  disiplin:{ forms:["en disiplin","disiplinen","disipliner","disiplinene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"可指纪律/自律，也可指学科或体育项目：holde disiplin i klassen（维持班级纪律）、en olympisk disiplin（奥运项目）。句子决定是行为规范还是领域分类。" },
  ekstra:{ note:"额外的、附加的；也可作副词表示额外地/特别地：et ekstra teppe（一条额外的毯子）、Det koster ekstra（这要额外收费）。不变形，位置常在名词前或动词后。" },
  enda:{ note:"可表示仍然/还（enda ikke ferdig，仍未完成），也可加强比较级表示‘更加’（enda bedre，更好），或表示‘甚至’。要与 ennå（仍然/尚未）区分，但部分语境用法会重叠。" },
  fag:{ forms:["et fag","faget","fag","fagene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"学科、课程科目，也可指专业领域或职业：favorittfaget mitt（我最喜欢的科目）、være rørlegger av fag（职业是水管工）。学校语境优先理解为科目。" },
  fastlege:{ forms:["en fastlege","fastlegen","fastleger","fastlegene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"家庭医生/固定全科医生；挪威体系中通常指登记在个人名下、负责常规初级医疗的医生。联系医生常说 bestille time hos fastlegen（预约家庭医生）。" },
  flau:{ forms:["flau","flaut","flaue","flauere","flauest / flaueste"], labels:["阳/阴性","中性","复数/定指","比较级","最高级"], note:"尴尬、难为情，也可表示羞愧：Jeg ble flau da jeg sa feil（我说错时感到很尴尬）。与 sjenert（性格腼腆）不同，flau 常是某个情境引发的感受。" },
  følge:{ forms:["å følge","følger","fulgte","fulgt"], labels:["原形","现在时","过去时","完成分词"], note:"可指跟随/陪同（følge barnet til skolen）、遵守（følge reglene）或事情接着发生（Det som følger，接下来发生的事）。不规则过去式 fulgte、分词 fulgt。" },
  før:{ note:"作副词表示以前/之前：Jeg har sett filmen før（我以前看过这部电影）。也常作介词或连词表示‘在……之前’：før møtet / før vi spiser。句法决定它是时间副词还是连接词。" },
  fri:{ forms:["fri","fritt","frie","friere","friest / frieste"], labels:["阳/阴性","中性","复数/定指","比较级","最高级"], note:"可指休息/不上班（Jeg har fri på fredag，周五我休息）、有空，也可指自由：en fri dag（休息日）、fri adgang（自由进入）。不能简单只译成‘自由的’。" },
  friminutt:{ forms:["et friminutt","friminuttet","friminutt","friminuttene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"课间休息时间：Elevene er ute i friminuttet（学生们课间在外面）。是学校课时之间的休息，不是泛指任何工作休息 pause。" },
  fyre:{ forms:["å fyre","fyrer","fyrte","fyrt"], labels:["原形","现在时","过去时","完成分词"], note:"可指生火/点炉取暖：fyre i ovnen（在炉子里生火）；也可见于 fyre av（开火/发射）等搭配。日常家居语境要看介词和宾语。" },
  grille:{ forms:["å grille","griller","grillet","grillet"], labels:["原形","现在时","过去时","完成分词"], note:"用烤架烤制、烧烤：grille fisk（烤鱼）、Vi griller ute（我们在户外烧烤）。过去式和完成分词均为 grillet。" },
  gryterett:{ forms:["en gryterett","gryteretten","gryteretter","gryterettene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"炖菜、锅炖料理，通常把肉/蔬菜等在锅里一起炖：Vi spiste gryterett til middag（晚饭我们吃了炖菜）。gryte 单独也可指锅具。" },
  gubbe:{ forms:["en gubbe","gubben","gubber","gubbene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"口语中的老头/老家伙，可带亲昵、调侃或贬义，语气高度依情境。正式、中性称呼用 eldre mann（年长男性）。" },
  halstablett:{ forms:["en halstablett","halstabletten","halstabletter","halstablettene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"润喉含片、喉片，由 hals（喉咙）+ tablett（药片）构成：Jeg tar en halstablett（我含一片润喉片）。词本身不一定表示处方药。" },
  halvtime:{ forms:["en halvtime","halvtimen","halvtimer","halvtimene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"半小时、三十分钟：Det tar en halvtime（需要半小时）。注意 klokkeslett 中 halv tre 指两点半，不是三点半。" },
  heldig:{ forms:["heldig","heldig","heldige","heldigere","heldigst / heldigste"], labels:["阳/阴性","中性","复数/定指","比较级","最高级"], note:"幸运的、碰巧有利的：Du var heldig med været（你天气真好/你很走运）。常见 heldig med（在……方面幸运）和 være heldig å（幸运地做成某事）。" },
  hit:{ note:"副词表示朝说话者所在处/此处移动：Kom hit!（到这儿来！）。与 her（在这里，静态位置）区分：Kom hit（过来）— vær her（待在这里）。" },
  høres:{ note:"多见于 høres ut som（听起来像）或 det høres … ut（听起来……）：Det høres bra ut（听起来不错）。形式上是 høre 的现在时/被动样式，具体结构和意思由 ut som 等搭配决定。" },
  høstdag:{ forms:["en høstdag","høstdagen","høstdager","høstdagene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"秋日、秋天的一天，由 høst（秋天）+ dag（日）组成：En kald høstdag（一个寒冷的秋日）。复合名词通常连写。" },
  høstsalg:{ forms:["et høstsalg","høstsalg(et)","høstsalg","høstsalgene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"秋季促销/秋季销售活动，由 høst（秋季）+ salg（促销/销售）组成。购物语境常指商店秋季折扣活动；词形复数需以词典校核为准。" },
  hotell:{ forms:["et hotell","hotellet","hoteller","hotellene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"酒店、旅馆：bestille et hotellrom（预订酒店房间）、bo på hotell（住酒店）。常见地点表达用 på hotell，而不是机械直译‘在一个酒店’。" },
  karakter:{ forms:["en karakter","karakteren","karakterer","karakterene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"可指成绩/分数等级（få gode karakterer），也可指人物角色或性格特征（en interessant karakter）。学校语境通常是成绩，影视文学语境常是角色。" },
  kaste:{ forms:["å kaste","kaster","kastet / kasta","kastet / kasta"], labels:["原形","现在时","过去时（变体）","完成分词（变体）"], note:"扔、投、抛，也可表示丢弃：kaste ball（投球）、kaste søppel（扔垃圾）。过去式/分词有 kastet 与 kasta 两种形式。" },
  kikke:{ forms:["å kikke","kikker","kikket / kikka","kikket / kikka"], labels:["原形","现在时","过去时（变体）","完成分词（变体）"], note:"看一看、瞥、探头看，语气通常比 se 更随意：kikke ut av vinduet（向窗外看一眼）。注意与 kikker（望远镜）等名词语境区分。" },
  kjedelig:{ forms:["kjedelig","kjedelig","kjedelige","kjedeligere","kjedeligst / kjedeligste"], labels:["阳/阴性","中性","复数/定指","比较级","最高级"], note:"无聊、乏味，也可表示令人遗憾/不愉快：en kjedelig bok（一本无聊的书）、Det var kjedelig at du ble syk（你生病了真遗憾）。官方词典列出这两类义项。" },
  kjeks:{ forms:["en kjeks","kjeksen","kjeks","kjeksene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"饼干、曲奇或薄脆饼，具体类型依品牌和语境：Vil du ha en kjeks?（你要一块饼干吗？）。不定复数常与单数同形。" },
  klasseliste:{ forms:["en klasseliste","klasselista / klasselisten","klasselister","klasselistene"], labels:["不定单数","定指单数（两种形式）","不定复数","定指复数"], note:"班级名单、班级名册，由 klasse（班级）+ liste（名单）构成：Læreren sjekker klasselista（老师在核对班级名单）。" },
  klasserom:{ forms:["et klasserom","klasserommet","klasserom","klasserommene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"教室、班级上课的房间：Elevene går inn i klasserommet（学生们走进教室）。与 skole（学校）指的范围不同。" },
  kunstutstilling:{ forms:["en kunstutstilling","kunstutstillingen","kunstutstillinger","kunstutstillingene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"艺术展览/美术展，由 kunst（艺术）+ utstilling（展览）组成：Vi besøkte en kunstutstilling（我们参观了一场艺术展）。" },
  land:{ forms:["et land","landet","land","landene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"可表示国家、土地/陆地或乡村地区：Norge er et land（挪威是一个国家）、komme til land（上岸）。复数 land；定指复数 landene。" },
  låne:{ forms:["å låne","låner","lånte","lånt"], labels:["原形","现在时","过去时","完成分词"], note:"可表示借入或借出，需看借贷方向及与谁搭配：Jeg låner en bok av henne（我向她借一本书）；Jeg låner henne en bok（我借给她一本书）。过去式 lånte，分词 lånt。" },
  lillebror:{ forms:["en lillebror","lillebroren","lillebrødre","lillebrødrene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"弟弟、年纪较小的兄弟。复数是不规则的 lillebrødre；女性对应 lille­søster（妹妹）。" },
  male:{ forms:["å male","maler","malte","malt"], labels:["原形","现在时","过去时","完成分词"], note:"可表示绘画，也可表示给墙面/物体刷漆：male et bilde（画一幅画）、male huset（给房子刷漆）。动词对象帮助区分‘画’与‘涂漆’。" },
  keeper:{ forms:["en keeper","keeperen","keepere","keeperne"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"守门员、门将，主要用于足球等运动：Keeperen reddet straffesparket（守门员扑出了点球）。其他运动项目可根据项目使用 keeper 或 målvakt。" },
  måned:{ forms:["en måned","måneden","måneder","månedene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"一个月、月份：Jeg har bodd her i tre måneder（我在这里住了三个月）。不规则复数 måneder；表示时长常用 i + 数量 + 复数。" },
  matematikk:{ note:"数学/数学学科，通常作不可数学科名词：Jeg liker matematikk（我喜欢数学）。讲具体课程可说 matematikkfaget；不能简单按可数名词加复数。" }
});
