Object.assign(V2_REVIEW_CORRECTIONS, {
  telefonnummer:{ forms:["et telefonnummer","telefonnummeret","telefonnumre / telefonnummer","telefonnumrene / telefonnumrene"], labels:["不定单数","定指单数","不定复数（形式变体）","定指复数（形式变体）"], note:"电话号码：Hva er telefonnummeret ditt?（你的电话号码是多少？）。复数可见 telefonnumre，也有保持复合词形式的 telefonnummer；实际使用通常需要的就是单复数区分。" },
  termos:{ forms:["en termos","termosen","termoser","termosene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"保温瓶/暖水壶：Jeg tok med kaffe på termosen（我用保温瓶带了咖啡）。在挪威语中 termos 通常指真空保温瓶，不特指装热水。" },
  tidsfrist:{ forms:["en tidsfrist","tidsfristen","tidsfrister","tidsfristene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"截止日期/最后期限：Fristen for å søke er fredag（申请截止日是星期五）。常见 overholde/holde fristen（遵守期限）与 innen fristen（在期限内）。" },
  undersøkelse:{ forms:["en undersøkelse","undersøkelsen","undersøkelser","undersøkelsene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"可指体检/检查、调查或研究：gå til undersøkelse hos legen（去医生处检查）、en spørreundersøkelse（问卷调查）。对象决定译法。" },
  utdanning:{ forms:["en utdanning","utdanningen / utdanninga","utdanninger","utdanningene"], labels:["不定单数","定指单数（两种形式）","不定复数","定指复数"], note:"教育、学历或所受培训：ha høyere utdanning（接受过高等教育）、ta en utdanning som lærer（接受教师职业教育）。不等同于一门具体课程 fag。" },
  utfordring:{ forms:["en utfordring","utfordringen","utfordringer","utfordringene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"挑战，也可指棘手的难题：Dette er en spennende utfordring（这是一个令人兴奋的挑战）。常用 ta imot en utfordring（接受挑战）。" },
  veileder:{ forms:["en veileder","veilederen","veiledere","veilederne"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"指导老师、导师、顾问；也可指指南/说明手册：snakke med veilederen（和导师谈）、en veileder for nye ansatte（新员工指南）。语境决定是人还是文件。" },
  velge:{ forms:["å velge","velger","valgte","valgt"], labels:["原形","现在时","过去时","完成分词"], note:"选择、挑选：Du kan velge mellom tre alternativer（你可以从三个选项中选择）。不规则变化 velge–velger–valgte–valgt；常用 velge mellom。" },
  vikar:{ forms:["en vikar","vikaren","vikarer","vikarene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"代班人员、临时替班者，可指代课老师或临时员工：Vi har en vikar i dag（我们今天有一位代课老师）。具体工作由上下文说明。" },
  vikarbyrå:{ forms:["et vikarbyrå","vikarbyrået","vikarbyråer","vikarbyråene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"临时用工/派遣机构，由 vikar（临时替班人员）+ byrå（机构）构成：Hun fikk jobb gjennom et vikarbyrå（她通过一家派遣机构找到了工作）。" },
  vondt:{ word:"et vondt", pos:"名词", zh:"疼痛；痛楚（常见于 ha/gjøre vondt 等表达）", forms:["et vondt","vondtet","vondt","vondta / vondtene"], labels:["不定单数","定指单数","不定复数","定指复数（两种形式）"], note:"Bokmålsordboka 将疼痛义的 vondt 列为中性名词，词形是 et vondt – vondtet – vondt – vondta/vondtene。最常用的表达是 ha vondt i halsen/ryggen（喉咙/背疼）；注意这不是形容词 vond 的整套变格，形容词另有 vond–vondt–vonde。" },
  yrke:{ forms:["et yrke","yrket","yrker","yrkene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"职业、专业工作：Hva jobber du med?（你做什么工作？）更侧重问工作内容；Hva er yrket ditt?（你的职业是什么？）询问职业类别。可说 velge et yrke（选择职业）。" },
  dessert:{ forms:["en dessert","desserten","desserter","dessertene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"甜点、餐后甜食：Vil du ha dessert?（你想吃甜点吗？）。注意甜点不一定是蛋糕，也可为水果、冰淇淋等。" },
  feire:{ forms:["å feire","feirer","feiret / feira","feiret / feira"], labels:["原形","现在时","过去时（变体）","完成分词（变体）"], note:"庆祝、纪念：Vi feirer bursdag på lørdag（我们周六庆祝生日）；feire jul（过圣诞节）。直接接庆祝的节日/事件。" },
  flagg:{ forms:["et flagg","flagget","flagg","flaggene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"旗、旗帜或国旗：heise flagget（升旗）、det norske flagget（挪威国旗）。中性名词，复数不定形式与单数同形。" },
  fredag:{ forms:["en fredag","fredagen","fredager","fredagene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"星期五；på fredag 通常指本周五（依语境），hver fredag 是每周五。约定安排时常用 på fredag，而日期日名一般不加冠词。" },
  hovedstad:{ forms:["en hovedstad","hovedstaden","hovedsteder","hovedstedene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"首都：Oslo er hovedstaden i Norge（奥斯陆是挪威的首都）。由 hoved（主要）+ stad（城市/地方）构成。" },
  jul:{ forms:["en jul","jula / julen","juler","julene"], labels:["不定单数","定指单数（两种形式）","不定复数","定指复数"], note:"圣诞节，也可指圣诞节前后的一段节庆期间：feire jul（过圣诞节）、i jula（圣诞节期间）。常用固定祝福 God jul!（圣诞快乐！）。" },
  julaften:{ forms:["en julaften","julaftenen","julaftener","julaftenene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"圣诞前夜/平安夜，在挪威指12月24日，是圣诞庆祝的重要日子。官方词典明确标注为24 December；挪威家庭常在当天吃节日晚餐并交换礼物。" },
  julegave:{ forms:["en julegave","julegaven","julegaver","julegavene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"圣诞礼物：Barna åpner julegavene på julaften（孩子们在平安夜打开圣诞礼物）。常见 få/gi julegaver（收到/送圣诞礼物）。" },
  julekule:{ forms:["en julekule","julekula","julekuler","julekulene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"圣诞树装饰球：Vi henger julekuler på juletreet（我们把圣诞球挂在圣诞树上）。不是一般的球 ball，而是节日装饰物。" },
  julemiddag:{ forms:["en julemiddag","julemiddagen","julemiddager","julemiddagene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"圣诞晚餐/圣诞节的正式餐食：Vi spiser julemiddag med familien（我们和家人吃圣诞晚餐）。具体菜式因地区和家庭传统而异。" },
  juletre:{ forms:["et juletre","juletreet","juletrær","juletrærne"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"圣诞树，通常指圣诞期间带进屋并装饰灯饰的针叶树：pynte juletreet（装饰圣诞树）。官方词典也以此定义。" },
  aktiv:{ forms:["aktiv","aktivt","aktive","mer aktiv","mest aktiv"], labels:["阳/阴性","中性","复数/定指","比较级（常用分析式）","最高级（常用分析式）"], note:"积极、活跃、主动参与的：være aktiv i lokalmiljøet（积极参与本地社区）。也可描述状态/运作中的事物；比较级常用 mer aktiv。" },
  altså:{ note:"可表示所以/因此（Jeg var syk, altså ble jeg hjemme）、也就是说/换言之，或作口语语气词。重述结论时相当于‘换句话说’，因果句中相当于‘所以’。" },
  avansert:{ forms:["avansert","avansert","avanserte","mer avansert","mest avansert"], labels:["阳/阴性","中性","复数/定指","比较级（常用分析式）","最高级（常用分析式）"], note:"高级的、先进的、复杂的：avansert teknologi（先进技术）、en avansert oppgave（复杂任务）。语境可指发展水平高，也可指难度大。" },
  bærbar:{ forms:["bærbar","bærbart","bærbare","mer bærbar","mest bærbar"], labels:["阳/阴性","中性","复数/定指","比较级（少用）","最高级（少用）"], note:"便携的、可携带的；常见 bærbar datamaskin（笔记本电脑）。名词 datamaskin 常省略，因此 en bærbar 也可指笔记本电脑。" },
  bake:{ forms:["å bake","baker","bakte","bakt"], labels:["原形","现在时","过去时","完成分词"], note:"烘焙、烤制面包/蛋糕等：Jeg baker brød hver søndag（我每周日烤面包）。也可说 sola baker（太阳晒得很热），依主语判断义项。" },
  ball:{ note:"同形词有不同词性/性别：en ball 是球（球体/运动用球），et ball 是舞会；ballen 可分别对应不同性别词形。上下文如 spille ball（玩球）与 gå på ball（参加舞会）可区分。" },
  bedre:{ note:"通常是 god/bra 的比较级‘更好’，也可作副词‘更充分地/更好地’：Det går bedre nå（现在情况好些了）、snakke bedre norsk（挪威语说得更好）。最高级 best。" },
  bein:{ forms:["et bein","beinet","bein","beina / beinene"], labels:["不定单数","定指单数","不定复数","定指复数（两种形式）"], note:"腿或骨头/腿骨：vondt i beinet（腿疼）、et brukket bein（一根骨折的骨头）。挪威语同一词可指腿或骨，靠身体/骨骼语境区分。" },
  drøm:{ forms:["en drøm","drømmen","drømmer","drømmene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"梦，也可指梦想/理想愿望：Jeg hadde en rar drøm（我做了一个奇怪的梦）、drømmen om å bli lege（成为医生的梦想）。常用 ha en drøm om。" },
  drømme:{ forms:["å drømme","drømmer","drømte","drømt"], labels:["原形","现在时","过去时","完成分词"], note:"做梦，也可表示梦想/幻想：Jeg drømte om familien min（我梦见了家人）、drømme om å reise（梦想旅行）。注意 drømme om + 名词/动词。" },
  dronning:{ forms:["en dronning","dronningen","dronninger","dronningene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"女王/王后，也可比喻某一圈子中最有影响力的女性；此外还是国际象棋的皇后棋子。词典列有这些不同义项。" },
  egenmelding:{ forms:["en egenmelding","egenmeldingen","egenmeldinger","egenmeldingene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"挪威职场制度中的自行申报病假，即员工按规定自行说明患病缺勤，不必每次先提供医生证明；制度资格和天数受雇佣规则约束。" },
  ekspert:{ forms:["en ekspert","eksperten","eksperter","ekspertene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"专家、行家：en ekspert på norsk grammatikk（挪威语语法专家）。常见 ekspert på + 专业领域；不必然表示正式职业头衔。" },
  ende:{ forms:["en ende","enden","ender","endene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"一端、末端或结尾：i enden av gata（在街道尽头）。固定短语 ende opp 表示最终落得/结果变成某种情况：Vi endte opp hjemme（结果我们回家了）。" },
  fall:{ forms:["et fall","fallet","fall","fallene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"本条是中性名词 et fall，可指跌倒、价格/温度下降、高低落差，也可指政府/政权倒台或城市陷落。瀑布通常说 fossefall（复合词），不能把 fall 单独当作普通‘瀑布’；‘秋天’是 høst。另有头发卷曲/垂落的同形名词义。" },
  feile:{ forms:["å feile","feiler","feilet / feila","feilet / feila"], labels:["原形","现在时","过去时（变体）","完成分词（变体）"], note:"犯错、做错或失败：Jeg feilet på prøven（我考试没考好）；也可用于‘某人有病/身体出问题’的固定结构，如 det feiler ham noe（他身体有点问题）。" },
  festning:{ forms:["en festning","festningen","festninger","festningene"], labels:["不定单数","定指单数","不定复数","定指复数"], note:"堡垒、要塞或设防城堡：Akershus festning ligger i Oslo（阿克斯胡斯要塞位于奥斯陆）。区别于一般的 slott（宫殿/城堡住宅）。" }
});
Object.assign(V2_MANUAL_REVIEW, {
  finger:"https://ordbokene.no/bm/finger", form:"https://ordbokene.no/bm/form", fredspris:"https://ordbokene.no/bm/fredspris", frisk:"https://ordbokene.no/bm/frisk", grad:"https://ordbokene.no/bm/grad", gråte:"https://ordbokene.no/bm/gråte", grøt:"https://ordbokene.no/bm/grøt", gudstjeneste:"https://ordbokene.no/bm/gudstjeneste", håndball:"https://ordbokene.no/bm/håndball", håndballspiller:"https://ordbokene.no/bm/håndballspiller", helse:"https://ordbokene.no/bm/helse", hevelse:"https://ordbokene.no/bm/hevelse", hjemmefra:"https://ordbokene.no/bm/hjemmefra", hoste:"https://ordbokene.no/bm/hoste", høstferie:"https://ordbokene.no/bm/høstferie", hovedgate:"https://ordbokene.no/bm/hovedgate", idrett:"https://ordbokene.no/bm/idrett", innom:"https://ordbokene.no/bm/innom", insistere:"https://ordbokene.no/bm/insistere", jentelag:"https://ordbokene.no/bm/jentelag", julebord:"https://ordbokene.no/bm/julebord", julekveld:"https://ordbokene.no/bm/julekveld", julestemning:"https://ordbokene.no/bm/julestemning", juletradisjon:"https://ordbokene.no/bm/juletradisjon", kamp:"https://ordbokene.no/bm/kamp", klemme:"https://ordbokene.no/bm/klemme", kondisjon:"https://ordbokene.no/bm/kondisjon", kul:"https://ordbokene.no/bm/kul", kvalm:"https://ordbokene.no/bm/kvalm", landslag:"https://ordbokene.no/bm/landslag", legeattest:"https://ordbokene.no/bm/legeattest", legeerklæring:"https://ordbokene.no/bm/legeerklæring", leppe:"https://ordbokene.no/bm/leppe", lett:"https://ordbokene.no/bm/lett", levere:"https://ordbokene.no/bm/levere", lunge:"https://ordbokene.no/bm/lunge", mage:"https://ordbokene.no/bm/mage", medisinskap:"https://ordbokene.no/bm/medisinskap", mester:"https://ordbokene.no/bm/mester", munn:"https://ordbokene.no/bm/munn"
});
Object.assign(V2_REVIEW_CORRECTIONS, {
  finger:{forms:["en finger","fingeren","fingre","fingrene"],labels:["不定单数","定指单数","不定复数","定指复数"],note:"手指；复数常用 fingre，而不是简单加 -er。tommelfinger 是拇指。例：Jeg har vondt i fingeren（我手指疼）。"},
  form:{forms:["en form","formen","former","formene"],labels:["不定单数","定指单数","不定复数","定指复数"],note:"形式、形状或状态，也可指烤模/模具。句子里的搭配决定意思：i god form（状态好）、en rund form（圆形）、en kakeform（蛋糕模）。"},
  fredspris:{note:"和平奖；常指诺贝尔和平奖时会说 Nobels fredspris。复合词由 fred（和平）+ pris（奖）组成。例：Hun fikk Nobels fredspris（她获得了诺贝尔和平奖）。"},
  frisk:{forms:["frisk","friskt","friske","friskere","friskest"],labels:["阳/阴性","中性","复数/定指","比较级","最高级"],note:"可表示健康的（bli frisk）、新鲜清新的（frisk luft）或活泼有力的；不是只指“病好了”。例：Jeg føler meg frisk i dag（我今天感觉健康）。官方词典列出这些不同义项。"},
  grad:{note:"度、程度、等级；天气温度常用 grad：Det er fem grader ute（外面五度）。也用于程度，如 i høy grad（在很大程度上）。注意单数 en grad，复数 grader。"},
  gråte:{forms:["å gråte","gråter","gråt","har grått"],labels:["原形","现在时","过去时","完成时"],note:"哭、流泪；过去时不规则：gråt，完成分词 grått。例：Barnet gråter fordi det er trøtt（孩子因为累了在哭）。"},
  grøt:{forms:["en grøt","grøten","grøter","grøtene"],labels:["不定单数","定指单数","不定复数","定指复数"],note:"粥，通常指用谷物/面粉和水或牛奶煮成的食物；也可比喻稠糊状物。日常常说 spise grøt，不一定带冠词。例：Vi spiser havregrøt til frokost（我们早餐吃燕麦粥）。"},
  gudstjeneste:{note:"教会礼拜/宗教礼拜仪式，通常在教堂举行；不等于一般的聚会。例：Familien går i kirken på gudstjeneste（全家去教堂参加礼拜）。"},
  håndball:{note:"手球（运动或球）。说“打手球”用 spille håndball，运动名通常不加冠词；指具体球时可说 en håndball。例：Datteren min spiller håndball på skolen（我女儿在学校打手球）。"},
  håndballspiller:{note:"手球运动员/手球队员，由 håndball（手球）+ spiller（运动员/选手）构成。例：Han er håndballspiller i en lokal klubb（他是当地俱乐部的手球运动员）。"},
  helse:{note:"健康、身体状况；常见搭配 god/dårlig helse（健康状况好/差）、helse og livsstil（健康与生活方式）。例：Søvn er viktig for helsa（睡眠对健康很重要）。"},
  hevelse:{note:"肿胀、浮肿或肿起的部位，常见于受伤或身体症状语境；不是普通的疼痛（smerte）。例：Jeg har fått en hevelse rundt ankelen（我脚踝周围肿起来了）。"},
  hjemmefra:{note:"从家里/离家；描述工作地点时 jobbe hjemmefra = 在家工作。辨析：hjemme 是“在家”，hjem 是“回家/到家”，hjemmefra 是“从家里”。例：Jeg jobber hjemmefra på fredager（我周五在家办公）。"},
  hoste:{forms:["å hoste","hoster","hostet / hosta","har hostet / hosta"],labels:["原形","现在时","过去时（两种形式）","完成时（两种形式）"],note:"动词“咳嗽”；词形 hoster、hostet/hosta。名词 hoste 也表示咳嗽，需看句法：Jeg hoster（我在咳嗽）/ Jeg har hoste（我咳嗽）。"},
  høstferie:{note:"秋假、秋季学校假期；复合词由 høst（秋天）+ ferie（假期）构成。具体周次因地区和年份而异。例：Barna har høstferie i oktober（孩子们十月放秋假）。"},
  hovedgate:{note:"主街、主要街道；由 hoved（主要）+ gate（街道）构成。例：Butikken ligger i hovedgata（商店在主街上）。与 hovedvei（主要公路）区分。"},
  idrett:{note:"体育运动或竞技运动的总称，通常比具体运动项目更正式；常见 drive med idrett（从事体育运动）、idrettslag（体育俱乐部）。例：Idrett er bra for både kropp og helse（运动对身体和健康都有好处）。"},
  innom:{note:"表示顺路到某处、短暂拜访/经过并进入：stikke innom butikken（顺便去一下商店）。与 bare forbi（只从旁经过）不同，innom 通常暗示进去或短暂停留。例：Jeg kommer innom etter jobb（我下班后顺道过来）。"},
  insistere:{forms:["å insistere","insisterer","insisterte","har insistert"],labels:["原形","现在时","过去时","完成时"],note:"坚持、坚决要求；常用 insistere på + 名词/动词。例：Hun insisterer på å betale（她坚持要付款）。Bokmålsordboka释义为坚持立场、不肯让步。"},
  jentelag:{note:"女子队/由女孩组成的队伍，常见于体育语境；复合词由 jente（女孩）+ lag（队）组成。例：Datteren min spiller på et jentelag（我女儿在一支女子队里踢/打球）。"},
  julebord:{note:"圣诞节前后的传统聚餐/公司圣诞派对；也可指摆放圣诞食物的餐桌。看语境区分：holde julebord 是办圣诞聚会，dekke julebordet 是布置圣诞餐桌。官方词典列出这两义。"},
  julekveld:{note:"圣诞夜晚；常指 12 月 24 日晚上的节庆时段，和 julaften（平安夜/12月24日）密切相关。例：Vi åpner gavene på julekvelden（我们在平安夜晚上拆礼物）。"},
  julestemning:{note:"圣诞气氛/节日氛围；由 jul（圣诞节）+ stemning（气氛）构成。常搭配 få/skape julestemning。例：Lysene gir stua ekte julestemning（这些灯让客厅充满真正的圣诞气氛）。"},
  juletradisjon:{note:"圣诞传统、节日习俗；可指家庭每年重复的活动。例：Å bake pepperkaker er en juletradisjon hos oss（烤姜饼是我们家的圣诞传统）。"},
  kamp:{note:"比赛/赛事，也可指斗争、战斗；依上下文判断。体育搭配 spille en kamp（打一场比赛）、vinne kampen（赢得比赛）；社会议题可说 kampen mot fattigdom（对抗贫困的斗争）。"},
  klemme:{forms:["å klemme","klemmer","klemte","har klemt"],labels:["原形","现在时","过去时","完成时"],note:"拥抱某人，也可表示挤压/夹住东西。klemme noen 是拥抱某人，klemme på noe 是挤压某物。例：Hun klemte sønnen sin før han dro（儿子出发前她拥抱了他）。"},
  kondisjon:{note:"体能、耐力，尤其指心肺耐力；常见 god kondisjon（体能好）、trene kondisjonen（锻炼耐力）。例：Jeg går tur for å få bedre kondisjon（我通过散步来提高体能）。"},
  kul:{forms:["kul","kult","kule","kulere","kulest"],labels:["阳/阴性","中性","复数/定指","比较级","最高级"],note:"口语形容词“酷、很棒、有趣”：Det var skikkelig kult（那真是太酷了）。注意同形名词 en kul 可指肿块/鼓包，词性和语境不同。"},
  kvalm:{forms:["kvalm","kvalmt","kvalme","kvalmere","kvalmest"],labels:["阳/阴性","中性","复数/定指","比较级","最高级"],note:"恶心的、反胃的、想吐的；常说 være kvalm / føle seg kvalm。例：Jeg blir kvalm av å lese i bilen（我在车里看书会恶心）。不是泛指“生病”。"},
  landslag:{note:"国家队，代表一个国家参加国际比赛的队伍；常见 Norges landslag（挪威国家队）、landslagsspiller（国家队队员）。例：Hun ble tatt ut på landslaget（她入选了国家队）。"},
  legeattest:{note:"医生开具的证明/医疗证明，常用于说明健康或缺勤情况；attest 强调正式证明文件。具体用途和要求要看机构规定。例：Skolen ba om en legeattest（学校要求提供医生证明）。"},
  legeerklæring:{note:"医生出具的医疗说明/医师声明，通常描述医疗情况或专业评估；与 legeattest 都可译作医疗证明，但 erklæring 更强调医生的书面说明内容。例：Hun fikk en legeerklæring etter undersøkelsen（检查后她拿到了医生的书面说明）。"},
  leppe:{forms:["ei leppe","leppa","lepper","leppene"],labels:["不定单数","定指单数","不定复数","定指复数"],note:"嘴唇；Bokmål 也可用阳性 en leppe / leppen。例：Hun har tørre lepper om vinteren（她冬天嘴唇会干）。"},
  lett:{forms:["lett","lett","lette","lettere","lettest"],labels:["阳/阴性","中性","复数/定指","比较级","最高级"],note:"可表示重量轻、容易或程度轻微：en lett bag（轻便的包）、en lett oppgave（简单的任务）、lett regn（小雨）。比较级 lettere。句子情境决定中文义。"},
  levere:{forms:["å levere","leverer","leverte","har levert"],labels:["原形","现在时","过去时","完成时"],note:"交付、送达、提交；lever inn 作业/文件表示提交，levere en pakke 表示递送包裹。例：Jeg leverte oppgaven før fristen（我在截止时间前交了作业）。"},
  lunge:{forms:["ei/en lunge","lunga/lungen","lunger","lungene"],labels:["不定单数","定指单数","不定复数","定指复数"],note:"肺；指身体器官时常说 lungene（双肺）。Bokmål 可用阴性或阳性变化。例：Røyking skader lungene（吸烟会损害肺部）。"},
  mage:{forms:["en mage","magen","mager","magene"],labels:["不定单数","定指单数","不定复数","定指复数"],note:"日常常指肚子/腹部，也可按语境指胃；常见 vondt i magen（肚子疼）、mageproblemer（胃肠问题）。例：Barnet har vondt i magen（孩子肚子疼）。"},
  medisinskap:{forms:["et medisinskap","medisinskapet","medisinskap","medisinskapene"],labels:["不定单数","定指单数","不定复数","定指复数"],note:"药柜、存放药品的柜子；由 medisin（药）+ skap（柜子）组成，性别由中性名词 skap 决定。例：Medisinene ligger i medisinskapet（药放在药柜里）。"},
  mester:{forms:["en mester","mesteren","mestere / mestre","mesterne / mestrene"],labels:["不定单数","定指单数","不定复数（两种形式）","定指复数（两种形式）"],note:"Bokmålsordboka 收录 mestere/mestre 和 mesterne/mestrene 两组复数形式。体育语境常指冠军（verdensmester 世界冠军），也可指高手、大师或师傅。例：Han ble norsk mester i svømming（他获得了挪威游泳冠军）。"},
  munn:{forms:["en munn","munnen","munner","munnene"],labels:["不定单数","定指单数","不定复数","定指复数"],note:"嘴、口；常用 åpne munnen（张嘴）、munn til munn（口对口）。注意嘴唇是 leppe，口腔/嘴是 munn。例：Babyen åpnet munnen（婴儿张开了嘴）。"}
});
