  muskel:"https://ordbokene.no/bm/muskel", normal:"https://ordbokene.no/bm/normal", oktober:"https://ordbokene.no/bm/oktober", olympisk:"https://ordbokene.no/bm/42044", ordning:"https://ordbokene.no/nno/search?dict=bm%2Cnn&q=ordning&scope=eif", overtid:"https://ordbokene.no/bm%2Cnn/overtid", panne:"https://ordbokene.no/bm/panne", peke:"https://ordbokene.no/bm/peke", periode:"https://ordbokene.no/bm/periode", puste:"https://ordbokene.no/bm/puste", pyjamasjakke:"https://ordbokene.no/search?dict=bm&q=pyjamasjakke&scope=eif", rask:"https://ordbokene.no/bm/rask", regne:"https://ordbokene.no/bm/regne", representere:"https://ordbokene.no/bm/representere", rest:"https://ordbokene.no/bm/rest", risikere:"https://ordbokene.no/bm/risikere", rygg:"https://ordbokene.no/nob/bm/rygg", sesong:"https://ordbokene.no/bm/sesong", side:"https://ordbokene.no/bm/side", skadet:"https://ordbokene.no/bm/skadet", skjønne:"https://ordbokene.no/bm/skjønne", skogstur:"https://ordbokene.no/search?dict=bm&q=skogstur&scope=eif", skranke:"https://ordbokene.no/search?dict=bm&q=skranke&scope=eif", skummel:"https://ordbokene.no/nob/search?dict=bm&q=skummel&scope=eif", slapp:"https://ordbokene.no/bm/slapp", smake:"https://ordbokene.no/bm/smake", smertestillende:"https://ordbokene.no/search?dict=bm&q=smertestillende&scope=eif", smitte:"https://ordbokene.no/bm/smitte", sovne:"https://ordbokene.no/nob/search?dict=bm%2Cnn&q=sovne&scope=eif", sport:"https://ordbokene.no/bm/sport", stakkars:"https://ordbokene.no/bm/stakkars", stanse:"https://ordbokene.no/search?dict=bm%2Cnn&q=stanse&scope=eif", sterk:"https://ordbokene.no/bm/sterk", størst:"https://ordbokene.no/bm/stor", stryke:"https://ordbokene.no/bm/stryke", super:"https://ordbokene.no/bm/super", svare:"https://ordbokene.no/bm/svare", svikte:"https://ordbokene.no/bm/svikte", tablett:"https://ordbokene.no/bm/tablett", tåke:"https://ordbokene.no/bm/tåke"
