Object.assign(V2_REVIEW_CORRECTIONS, {
  storby:{zh:"大城市；人口较多的城市",note:"词典核心定义以居民数量多为准；它并不自动表示首都或行政特区。"},
  stikke:{zh:"刺；戳；伸入/放入；（stikke innom/bort）顺道去一下",note:"含义高度依赖结构：stikke seg på en nål=被针扎；stikke papirene i veska=把文件塞进包里；stikke innom=顺道拜访；stikke bort i butikken=去商店一趟。"},
  stanse:{zh:"停下；使……停止；拦下/拦住",note:"不及物时表示自身停止（bussen stanset）；及物时表示使某物/某人停下（stanse bilen/en person）。也可表示停止某项活动/付款。"},
  hjemover:{zh:"朝家/家乡方向；往回家的路上",note:"表示朝家或家乡方向移动，不等同于已到家；på vei hjemover=在回家的路上。与 hjem（回家/到家）比较。"},
  bratt:{zh:"陡的；陡峭的；（曲线或变化）急剧的",note:"描述坡面/道路时指倾斜很大；描述价格、曲线时可指变化幅度大，如 bratt fall（急剧下跌）。bratt 也可作副词，修饰 stige/skråne。"},
  snu:{zh:"转身；转向/掉头；翻转；扭转趋势（依宾语和语境）",note:"snu seg=转过身；snu bilen=把车掉头；snu stolen mot vinduet=把椅子转向窗户；snu utviklingen=扭转发展趋势。"},
  direkte:{zh:"直达的；直接的；直率的；（副词）径直/直接地（依语境）",note:"交通中 uten omveier eller avbrudd：direkte bussforbindelse（直达公交）；直接沟通/没有中间环节；描述说话方式时可指直率。"},
  bort:{zh:"到别处去；离开原处；不见/消失（依搭配）",note:"核心方向是从当前位置移到更远的另一处，与表示向下的 ned 相区别：reise bort=离开去别处；visne bort=逐渐枯萎消失。"},
  hit:{zh:"到这里；朝这里来；（书/分类中）归入这一处/组",note:"表示朝说话者所在处移动，与表示离开说话者位置的 dit 相对：kom hit=到这里来；haren hører hit=兔子归入这一类。注意 hit 还有同形名词义，需按词性区分。"},
  ned:{zh:"向下；下来/下去；降低/减少（依搭配）",note:"表示从较高处到较低处，也可表示程度或数量降低；ned til Frankrike 在部分挪威语地理视角中可表示南下法国。方向相反的是 opp。"},
  tilbake:{zh:"返回原处；回来/回去；向后；（数量/趋势）减少（依语境）",note:"回到出发点可译“回来/回去”：vi er snart tilbake；也可指向后或回落，如 folketallet går tilbake（人口减少）。返回方向需结合说话者位置判断。"}
});
Object.assign(V2_REVIEW_CORRECTIONS, {
  mobilnummer:{zh:"手机号码；手机号",note:"mobilnummer 是 mobil（移动电话）+ nummer（号码）构成的复合词，具体指手机号码；不是手机设备（mobiltelefon）。常问 Hva er mobilnummeret ditt?（你的手机号是多少？）。",contexts:[["Hva er mobilnummeret ditt?","你的手机号是多少？","根据日常问询语境编写的练习句；mobilnummeret 是定指单数。"]]},
  hemmelig:{zh:"秘密的；保密的；未公开的；暗自怀有的（依语境）",note:"可指只让少数人知道的事物，也可指不公开的感情/想法；holde noe hemmelig 是“把某事保密”。",contexts:[["Jeg er hemmelig forelsket i henne.","我暗恋着她。","词典原句；hemmelig 描述没有公开的感情。","https://ordbokene.no/bm/hemmelig"]]},
  kjempebra:{zh:"特别好；棒极了；进展非常顺利（口语强化）",note:"kjempe- 在口语中作强化成分，相当于“特别/非常”；整体是 bra 的强烈肯定，不是字面上的“巨大的好”。",contexts:[["Dette gikk kjempebra!","这件事进展得特别顺利！","词典原句；kjempebra 在此评价事情进展。","https://ordbokene.no/bm/kjempebra"]]},
  kjempefin:{zh:"特别好；非常漂亮/愉快的（口语强化，具体随 fin 的搭配）",note:"kjempe- 强调程度；可形容外观，也可形容体验、天气或其他令人满意的事物。不要一律只译成“特别漂亮”。",contexts:[["En kjempefin opplevelse.","一次特别棒的体验。","词典原例为名词短语，不是完整句；此处描述体验很棒。","https://ordbokene.no/bm/kjempefin"]]},
  kjempeflink:{zh:"特别能干的；非常擅长的；表现特别出色的（口语强化）",note:"kjempe- 是口语强化成分；flink til å + 动词表示擅长做某事，flink med + 名词表示善于处理/使用某物。这里表达技能或表现出色，不等同于聪明。",contexts:[["Hun er kjempeflink til å snakke for seg.","她特别善于表达自己。","根据词典 flink til å snakke for seg 的搭配加 kjempe- 扩写；kjempe- 表示非常。","https://ordbokene.no/bm/flink"]]},
  kjenne:{zh:"认识；熟悉；感受到；察觉到；触摸/检查（依宾语和搭配）",note:"kjenne noen 表示认识某人；kjenne til noe 是知道/了解某事；kjenne smerte/lukt 是感受到疼痛/气味；kjenne på 可表示触摸检查，也可表示感受。注意 å kjenne 同形名词义（标记/特征）是另一个词条。",contexts:[["Politiet kjenner til saken.","警方了解这件事。","词典原句；kjenne til + 事件表示知道、了解。","https://ordbokene.no/bm/kjenne"]]},
  koselig:{zh:"温馨舒适的；令人愉快的；讨人喜欢、亲切的（依语境）",note:"描述家或聚会时指温馨、令人舒服愉快；描述人时指讨人喜欢、亲切。它着重温暖舒适的氛围，不只是外表“漂亮”。",contexts:[["Et koselig hjem.","一个温馨舒适的家。","词典原例为名词短语，不是完整句；描述家的氛围舒适温暖。","https://ordbokene.no/nob/bm/koselig"]]},
  lang:{zh:"长的；（人）个子高的；持续时间长的；（裤子/裙子）长款的（依语境）",note:"可描述物体尺寸、人的身高、时间长度或衣物长度；形容头发用 langt hår（长头发），人高可说 hun er lang。勿与 høy 在所有语境下简单等同。",contexts:[["Hun har langt hår.","她留着长头发。","词典原例；hår 为中性名词，形容词用 langt。","https://ordbokene.no/bm/lang"]]},
  le:{zh:"笑；发笑；嘲笑/取笑（依搭配和语气）",note:"通常表示因开心、好笑而笑，也可表示嘲弄。le av noe 可表示觉得某事好笑；le av noen / le noen ut 可能带嘲笑某人的意思。过去式 lo，完成分词 ledd。",contexts:[["Folk smiler og ler til hverandre.","人们相视微笑、大笑。","词典原句；这里是友好互动中的笑，不含嘲讽。","https://ordbokene.no/bm/le"]]},
  liten:{zh:"小的；年幼的；幼小的；（尺寸/份量）少的（依语境）",note:"形式不规则：en liten bil、et lite hus、små barn、mindre、minst。描述年龄时可指年幼；en liten porsjon 是一小份；“个子矮/身材小”也可用 liten av vekst。",contexts:[["Hun har et lite barn.","她有一个年幼的孩子。","词典原句；这里 liten 表年龄小，不是孩子体格小。","https://ordbokene.no/bm/liten"]]}
});
Object.assign(V2_REVIEW_CORRECTIONS, {
  våken:{zh:"醒着的；清醒的；警觉、留心的（依语境）",note:"最常见是“没有睡着”；形容人或注意力时也可指机敏、留神。våken 是形容词；动词“醒来”是 våkne，勿混为同一个词条。",contexts:[["Er du våken?","你醒着吗？","词典原句；询问是否还没睡/已经醒着。","https://ordbokene.no/bm/v%C3%A5ken"]]},
  tenke:{zh:"思考；考虑；想象；打算；认为（依结构）",note:"tenke på = 想到/考虑；tenke over = 仔细考虑；tenke seg = 想象；tenke å/ha tenkt å = 打算；tenke at = 认为。不能把所有结构都译作“想”。",contexts:[["Hva har du tenkt å gjøre?","你打算做什么？","词典原句；tenke å + 动词原形表示打算。","https://ordbokene.no/bm/tenke"]]},
  flink:{zh:"能干的；擅长的；做得好的（依语境）",note:"flink til å + 动词表示擅长做某事；flink med + 名词表示善于使用/处理某物。强调能力或熟练，不等于聪明，也不只是“乖”。",contexts:[["Hun er flink til å snakke for seg.","她很善于表达自己。","词典原句；flink til å + 动词，说明擅长的技能。","https://ordbokene.no/bm/flink"]]},
  glad:{zh:"高兴的；开心的；喜欢、珍惜（glad i）；令人愉快的（颜色等）",note:"glad for noe/at ... 表示因某事高兴；glad i noen/noe 表示喜欢、疼爱；glade farger 指明快鲜亮的颜色。注意 glad i 不是单纯的“对……开心”。",contexts:[["De var glad i hverandre.","他们彼此相爱/很喜欢对方。","词典固定搭配例句；glad i 表示珍爱、喜欢。","https://ordbokene.no/bm/glad"]]},
  god:{zh:"好的；优质的；美味/令人舒服的；善良的；擅长的；充足的（依搭配）",note:"质量评价：en god kniv；味道/舒适感：god mat；能力：god i norsk；品格：et godt menneske；数量充足：god tid/god plass。比较级 bedre，最高级 best。",contexts:[["Hun er god til å danse.","她很擅长跳舞。","词典原句；god til å + 动词表示技能好、擅长。","https://ordbokene.no/bm/god"]]},
  kanskje:{zh:"也许；可能；说不定；（句尾问句）难道不是/是吧（依语气）",note:"常作句子副词，表达不确定的可能性：kommer kanskje i morgen；也可放在句尾，带确认或反问语气，不能总译成“也许”。",contexts:[["De kommer kanskje i morgen.","他们也许明天会来。","词典原句；kanskje 表示说话者认为可能但不确定。","https://ordbokene.no/bm/kanskje"]]},
  mål:{zh:"目标；目的；球门/进球；度量单位；语言/口语（依语境）",note:"sette seg et mål 是设定目标；scora mål 是进球；meter 是长度单位；mål 也可指某地区/群体使用的语言或方言。通过动词搭配判断具体义。",contexts:[["Hun satte seg et mål om å lære norsk.","她给自己定下了学习挪威语的目标。","依据词典“目标/目的”义编写的完整练习句，不是词典原句。","https://ordbokene.no/bm/mål"]]},
  kø:{zh:"排队的人/车辆；等候队伍；（台球）球杆（依语境）",note:"日常最常见指等待服务或通行的人/车辆：stå i kø（排队）；也可指台球杆。kø 不是一群人的泛称，重点是“按顺序等待”。",contexts:[["De står i kø.","他们在排队。","词典原句；这里 kø 指等待轮到自己的队伍。","https://ordbokene.no/bm/k%C3%B8"]]},
  oppskrift:{zh:"食谱；制作/操作说明；惯用方法、套路（依语境）",note:"做菜或编织时是具体步骤说明；etter oppskriften 可比喻按惯常方法/套路进行；药品处方通常是 resept，不宜把 oppskrift 一概理解为处方。",contexts:[["Følg oppskriften nøye.","仔细按照食谱/说明操作。","词典原句；此处是按步骤说明制作。","https://ordbokene.no/bm/oppskrift"]]}
});
Object.assign(V2_REVIEW_CORRECTIONS, {
  flott:{zh:"漂亮的；出色的；很棒的；顺利地（依搭配）",note:"日常描述外观可译漂亮/气派，描述表现、活动可译出色/很棒；det gikk flott 是“进展顺利”。词典另收较少见的“漂浮”义，按上下文区分。",contexts:[["Det gikk flott.","事情进展得很顺利。","词典原句；flott 作副词描述事情进展。","https://ordbokene.no/bm/flott"]]},
  bluse:{zh:"女式衬衫；女式罩衫（通常较轻薄、宽松）",note:"指女装上衣，类似衬衫但常用较轻薄面料、版型较宽松；不要泛化为所有上衣。词典接受阳性或阴性：en bluse / ei bluse。",contexts:[["kle seg i skjørt og bluse","穿上裙子和女式衬衫","词典原例为搭配片段；按名词搭配翻译，不改写成完整句。","https://ordbokene.no/bm/bluse"]]},
  bukse:{zh:"裤子；一条裤子（单数名词；常以复数 bukser 指裤装）",note:"衣物名称。日常说“穿裤子”常用 gå i bukse / ha på seg bukser；数一条时可说 ei/en bukse，也可用 et par bukser。词典接受阳性或阴性。",contexts:[["et par bukser","一条裤子","词典原例为名词短语；挪威语用复数 bukser 表示裤装。","https://ordbokene.no/bm/bukse"]]},
  jakke:{zh:"夹克；外套（穿在衬衫、罩衫或毛衣外面的长袖上衣）",note:"指上身外穿、通常前襟可开合的衣物；可以是夹克、外套，不限于厚冬衣。词典接受阳性或阴性：en jakke / ei jakke。",contexts:[["gå i bukse og jakke","穿着裤子和外套","词典原例为搭配片段；这里表示身上的衣着。","https://ordbokene.no/bm/jakke"]]},
  klær:{zh:"衣服；衣物；一身衣着（集合性复数名词）",note:"klær 通常以复数形式表示衣物整体或多件衣服；定指 klærne 是“这些/那些衣服”。单件衣物要说 en skjorte、ei jakke 等，不能把 klær 当作“衣服”单数。",contexts:[["kjøpe seg nye klær","给自己买新衣服","词典原例为动词短语；klær 是集合性的复数名词。","https://ordbokene.no/bm/kl%C3%A6r"]]},
  nøkkel:{zh:"钥匙；扳手；关键、解决办法（依语境）",note:"开锁用的是钥匙；修理工具语境可指扳手；抽象表达 nøkkelen til ... 是“……的关键/诀窍”。读名词搭配和上下文判断。",contexts:[["Nøkkelen står i døra.","钥匙插在门上。","词典原句；这里是开门用的实体钥匙。","https://ordbokene.no/bm/n%C3%B8kkel"]]},
  sko:{zh:"鞋；鞋子（通常指不高过脚踝的鞋）",note:"常用复数 sko 泛指鞋/鞋子；一双鞋是 et par sko，特指那双鞋可说 skoene。词典还有同形动词 sko“给马钉蹄铁/给车辆装配”，本条是名词。",contexts:[["ta på seg skoene","把鞋穿上","词典原例为动词短语；skoene 指语境中特定的鞋。","https://ordbokene.no/bm/SKO"]]},
  telefon:{zh:"电话机；电话通话；来电/电话联系（依语境）",note:"可指设备（trådløs telefon）、正在通话（være i telefonen）、一通电话/来电（få en telefon）。移动电话口语常简称 mobil；不要把 telefon 只理解为手机设备。",contexts:[["Telefonen ringer.","电话响了。","词典原句；telefonen 指电话设备，ringer 表示响铃。","https://ordbokene.no/bm/telefon"]]},
  vekkerklokke:{zh:"闹钟；可以设定时间响铃的时钟",note:"用于设定时间叫醒或提醒；也可写 vekkeklokke。与 klokke（钟/表）相比，vekkerklokke 明确有定时响铃功能。",contexts:[["stille vekkerklokka på klokka halv sju","把闹钟设在六点半","词典原例为不定式搭配；halv sju 在挪威语时间表达中是六点半。","https://ordbokene.no/bm/vekkerklokke"]]},
  humør:{zh:"心情；情绪状态；性情、脾气（依搭配）",note:"通常指某一时刻的心情：være i godt/dårlig humør；也可指一个人的性情或面对困难时的精神状态。humør 与 humor（幽默感/幽默作品）相关但不是同一个词义。",contexts:[["Humøret var på topp.","心情好极了。","词典原句；固定表达 være på topp 表示处于最佳状态。","https://ordbokene.no/bm/hum%C3%B8r"]]}
});
Object.assign(V2_REVIEW_CORRECTIONS, {
  fattig:{zh:"贫困的；贫乏的；缺少某种资源/内容的（依语境）",note:"描述经济状况时是贫困；fattig på tid 是缺少时间；fattig jord 是贫瘠的土壤；抽象事物也可表示内容贫乏或令人失望。必须看后接名词，不能把所有用法都理解成没钱。",contexts:[["fattige mennesker som tigger på gata","在街头乞讨的贫困人群","词典原例为名词短语片段；这里是经济贫困义。","https://ordbokene.no/bm/fattig"]]},
  bestemme:{zh:"决定；确定/规定；判定、辨认（依宾语）",note:"bestemme et tidspunkt = 确定时间；bestemme regler = 制定/规定规则；bestemme seg for noe/å gjøre noe = 自己决定做某事。表达个人下决定时常用反身结构 bestemme seg for。",contexts:[["Vi har bestemt oss for å reise i morgen.","我们已经决定明天出发。","词典原句；bestemme seg for å + 动词原形表示决定去做某事。","https://ordbokene.no/bm/bestemme"]]},
  bety:{zh:"意思是；表示；意味着、导致；重要、有影响（依语境）",note:"问 Hva betyr ...? 是问“……是什么意思”；主语为事件时 bety at ... 表示“意味着……”；bety mye for noen 表示对某人很重要。不要只记成“翻译成”。",contexts:[["Hva betyr dette skiltet?","这个标志是什么意思？","词典原句；问符号/标志所表达的含义。","https://ordbokene.no/bm/bety"]]},
  brenne:{zh:"燃烧；着火；烧/烤/焚烧；灼痛；热切投入（依主语和宾语）",note:"不及物：låven brenner（谷仓着火）；及物：brenne søppel（焚烧垃圾）；皮肤/伤口可有灼烧感；brenne for en sak 表示热切支持某事业。词典区分“自己着火”和“使某物燃烧”两组用法。",contexts:[["Låven brenner.","谷仓着火了。","词典原句；brenne 不带宾语，表示处于燃烧状态。","https://ordbokene.no/bm/brenne"],["Hun brant for faget sitt.","她对自己的专业充满热情。","词典原句；brenne for + 事业/领域表示热切投入。","https://ordbokene.no/bm/brenne"]]},
  dele:{zh:"分开；切分；分配；分享；共同拥有（依结构）",note:"dele noe i ... = 把某物分成……；dele noe mellom/på = 分配；dele noe med noen = 与某人分享；dele rom/omsorg = 共同使用或承担。宾语和介词决定中文意思。",contexts:[["Hun delte eplet i små biter.","她把苹果切成小块。","词典原句；dele ... i ... 表示把整体分成若干部分。","https://ordbokene.no/bm/dele"]]},
  dusje:{zh:"洗淋浴；给……淋浴；（水等）喷洒/洒落（依主语）",note:"人作主语时通常是淋浴：dusje etter trening；及物用法可给植物喷水；水流作主语时可表示细水喷洒。不要把 dusje 限定为“洗澡”的泛称。",contexts:[["dusje etter treningen","训练后洗淋浴","词典原例为不定式短语；原句省略主语，按短语翻译。","https://ordbokene.no/bm/dusje"]]},
  fortsette:{zh:"继续；接着做；持续、继续存在（依主语）",note:"人作主语时常表示接着进行某活动：fortsette samtalen；事件/天气作主语时表示持续：solskinnet fortsetter；常用 fortsette med noe 或 fortsette å gjøre noe。",contexts:[["Vi kan fortsette samtalen en annen gang.","我们可以改天继续谈话。","词典原句；fortsette samtalen 表示把已开始的谈话接着进行。","https://ordbokene.no/bm/%C3%A5%20fortsette"]]},
  hente:{zh:"去取回；去接（人）；取来；获得/获取（抽象资源）",note:"核心是去某处取得并带回：hente posten（取邮件）、hente noen på stasjonen（去车站接人）；抽象语境可表示获得荣誉、从来源提取信息。搭配宾语决定译法。",contexts:[["Jeg henter deg på stasjonen.","我去车站接你。","词典原句；hente 人表示去接并带回来/接走。","https://ordbokene.no/bm/hente"]]},
  hoppe:{zh:"跳；跳跃；蹦；跳过/略过；突然弹动（依结构）",note:"身体离地或越过障碍是“跳”：hoppe over gjerdet；hoppe over et spørsmål 不是跳过去，而是跳过/略过问题；心脏或物体也可表示突然跳动、弹起。",contexts:[["Du kan hoppe over dette spørsmålet og gå videre til neste.","你可以跳过这道题，继续做下一题。","词典原句；hoppe over + 内容表示略过，不是身体跳跃。","https://ordbokene.no/bm/hoppe%20over"]]},
  klappe:{zh:"鼓掌；轻拍、抚摸；拍合/拍平；（船）靠岸；（心脏）乱跳（依语境）",note:"掌声用 klappe；对人或动物轻拍、爱抚也用 klappe；klappe sammen boka 是把书合上；klappe til kai 是靠岸。若说 klappe til noen 则可能是打某人一巴掌，语气和结构很重要。",contexts:[["Publikum klappet og klappet.","观众不断鼓掌。","词典原句；重复 klappet 表示持续拍手喝彩。","https://ordbokene.no/bm/klappe"]]}
});
Object.assign(V2_REVIEW_CORRECTIONS, {
  begynne:{zh:"开始；着手；开始发生/出现（begynne å / begynne på）（依结构）",note:"begynne å + 动词表示开始做某事；begynne på + 名词表示开始某项活动/课程；事件或季节作主语表示开始。注意开始某事常用 begynne på，而开始做某动作常用 begynne å。",contexts:[["Møtet begynner kl. 13.","会议下午一点开始。","词典原句；begynne 表示事件在某一时间开始。","https://ordbokene.no/bm/begynne"]]},
  glemme:{zh:"忘记；遗忘；忘带/落下；忘了做、疏忽未做；不再计较（依结构）",note:"忘记信息：glemme hva noen heter；忘带物品：glemme boka hjemme；glemme å slokke lyset 是忘了去关灯。glemme + 名词与 glemme å + 动词的意思相关但结构不同。",contexts:[["Jeg har glemt hva han heter.","我忘了他叫什么名字。","词典原句；glemme 引出遗忘的内容，完成时 har glemt。","https://ordbokene.no/nob/bm/glemme"]]},
  huske:{zh:"记得；记住；想起；记着要做（huske å / huske på）（本词条指记忆义）",note:"挪威语 huske 另有‘上下摇晃’的同形动词义，也可作名词表示秋千；此卡只练‘记忆’义。huske noen/noe 是记得某人/某事；huske å gjøre noe 是记得去做；husk å ... 常用于提醒。",contexts:[["Husk å ta med kopp.","记得带上杯子。","词典原例；祈使式 husk å + 动词原形，提醒对方不要忘记去做。","https://ordbokene.no/bm/huske"]]},
  vente:{zh:"等；等待；等候；预期、料想；（事情/机会）等待着（依结构）",note:"vente på noen/noe 是等某人/某事；vente med å gjøre noe 是暂缓做；vente at 表示预料。注意 vente på 与 vente med 结构和意思不同。",contexts:[["Jeg har ventet ganske lenge nå.","我已经等了挺久了。","词典原句；vente 表示等待，完成时强调等到现在已经持续一段时间。","https://ordbokene.no/bm/vente"]]},
  like:{zh:"喜欢；喜爱；觉得……不错/满意（like noe / like å gjøre noe）",note:"like + 名词表示喜欢某物/人：like filmen；like å + 动词表示喜欢做某事：like å gå tur。like seg 表示过得舒适、感觉自在；不要与形容词/adverb like（相同/同样）混淆。",contexts:[["Likte du filmen?","你喜欢那部电影吗？","词典原句；like + 宾语表示喜欢，likte 是过去式。","https://ordbokene.no/bm/like"]]},
  prøve:{zh:"试；试用、测试；试穿；尝试、试着做；考查（依搭配）",note:"试用物品/测试性能：prøve en bil；试穿衣物常用 prøve på；prøve å gjøre noe 是尝试做某事。prøve seg fram 表示反复试验、摸索出合适方法。",contexts:[["Jeg prøvde å komme tidsnok.","我试着准时赶到。","词典原句；prøve å + 动词原形表示尝试做某事，过去式 prøvde。","https://ordbokene.no/nob/bm/pr%C3%B8ve"]]},
  mat:{zh:"食物；饭菜；一顿饭/用餐（依语境）；食物、营养（较少见）",note:"通常是不可数名词：mat og drikke（食物和饮料）；也可指一顿饭，如 før maten（吃饭前）。词典还收录‘一片面包/开放三明治’等语境义，初级先掌握食物和饭菜。名词阳性：en mat – maten。",contexts:[["Han liker å lage mat.","他喜欢做饭。","词典原句；lage mat 是‘做饭’，这里 mat 指食物/饭菜，不用冠词。","https://ordbokene.no/nob/bm/MAT"]]},
  dusj:{zh:"淋浴；一阵细密喷洒；淋浴喷头/设备；淋浴间（依语境）",note:"ta en dusj 是洗一次淋浴；i dusjen 可指在淋浴间/淋浴设备下；rom med dusj 中 dusj 指淋浴间。也可指水或香水的细喷洒。阳性名词：en dusj – dusjen。",contexts:[["Jeg tar en dusj før jobb.","我上班前冲个澡。","依据词典搭配 ta en dusj 补成完整练习句；ta en dusj 是‘洗一次淋浴’，并非词典原句。","https://ordbokene.no/bm/dusj"]]},
  få:{zh:"得到；收到；获得；有机会/获准；使、让（få noen til å gjøre noe）；不得不/可以（依结构）",note:"få brev/svar 是收到；få lov/anledning til 是获准/有机会；få noen til å le 是使某人发笑；få gjort 是设法完成。情态义 få vel + 动词原形可表达‘大概该/只好’。不能一律译成‘得到’。",contexts:[["Han får svar i morgen.","他明天会收到答复。","词典原句；få + 名词表示收到/获得，får 是现在时。","https://ordbokene.no/bm%2Cnn/%C3%A5%20f%C3%A5"]]},
  gå:{zh:"走；步行；去/前往；运转、进行；变得/结果（依主语和搭配）",note:"人作主语时可表示步行或前往；钟表/机器可表示运转；事情作主语时常是进展：det går bra（进展顺利）。gå på kino 是去看电影，不是‘在电影院走’；gå 的过去式 gikk、完成分词 gått。",contexts:[["De gikk seg en tur rundt vannet.","他们绕着湖散了一会儿步。","词典原句；gå seg en tur 是‘出去走走/散步’，过去式 gikk。","https://ordbokene.no/nob/bm/%C3%A5%20g%C3%A5"]]},
  ha:{zh:"有；拥有；带着/具有；经历、患有；安排/进行；作助动词（依搭配）",note:"ha bil 是拥有车；ha vondt i magen 是肚子疼；ha det bra 是过得好；ha møte/eksamen 是有会议/考试。ha 也构成完成时：har lest（已经读了）。不能只按实体‘拥有’理解。",contexts:[["Hvordan har du det?","你最近怎么样？","词典原例；固定问候语询问对方近况，不是字面问‘你拥有什么’。","https://ordbokene.no/bm/ha"]]},
  komme:{zh:"来；到达；出现/传来；进入某种状态；来自；将会（komme til å）（依结构）",note:"朝说话者或参照点移动是‘来’；komme fram 表示到达/显现；komme i gang 是开始；komme fra 表示来自；komme til å + 动词表示将会。与 gå（离开/前往）对照时，要看参照点。",contexts:[["Der kommer bussen.","公交车来了。","词典原句；komme 表示朝说话者所在位置到来，主句动词位于第二位。","https://ordbokene.no/bm/KOMME"]]},
  ta:{zh:"拿；取；带走/乘坐；接受/服用；花费/占用；承担（依搭配）",note:"ta boka 是拿书；ta bussen 是乘公交；ta med seg 是带上；ta medisiner 是服药；ta tid 是花时间；ta ansvar 是承担责任。介词或宾语常决定含义，需按词组学习。",contexts:[["Ta tauet!","把绳子拿住！","词典原例改为标点完整的祈使句；ta + 物品表示拿/握住，此处是抓住绳子。","https://ordbokene.no/bm%2Cnn/%C3%A5%20ta"]]},
  være:{zh:"是；在/处于；存在；举行/发生；作为助动词构成状态或被动（依结构）",note:"身份/性质：Hun er lærer；地点：De er hjemme；状态：Jeg er trøtt；安排发生：Møtet er på fredag；也可组成被动或状态表达。注意 være 的现在时 er、过去时 var、完成分词 vært。",contexts:[["De er i utlandet.","他们在国外。","词典原句；være + 地点介词短语表示所在位置。","https://ordbokene.no/nob/bm/v%C3%A6re"]]},
  bli:{zh:"变成；成为；变得；留下/继续处于；构成被动（依结构）",note:"bli lege/syk 表示成为/变得；bli hjemme/igjen 表示留下；bli + 过去分词构成被动。与 være 区分：være 表示已处于某状态，bli 常强调进入该状态或继续留下。",contexts:[["Hun ble igjen på hytta.","她留在了小木屋里。","词典原句；bli igjen 表示没有离开、继续留在原处，过去式 ble。","https://ordbokene.no/bm/6390"]]},
  gjøre:{zh:"做；进行；完成；使/造成；表现、行事；（代替前文动词）（依结构）",note:"gjøre en jobb 是做工作；gjøre noen glad 是使某人高兴；hvordan går det?—Det gjør det 是用 gjøre 代替前文动词。gjøre 和 gjøre seg til、gjøre om 等固定结构含义各异。",contexts:[["Hun vil gjøre det selv.","她想自己做这件事。","词典原句；gjøre det 表示做这件事，selv 强调由她本人完成。","https://ordbokene.no/bm/gj%C3%B8re"]]},
  måtte:{zh:"必须；不得不；可以/获准（较少见）；推测上必定（依语境）",note:"最常见的是义务或必要性：måtte gå（必须走）；过去式 måtte 表示当时不得不。måtte 也可表达推测：Det må være sant（那一定是真的）。情态动词后接不带 å 的动词原形。",contexts:[["Jeg må gå nå.","我现在必须走了。","词典原句；måtte 的现在时 må 表示必要性，后接动词原形 gå。","https://ordbokene.no/nno/bm/m%C3%A5ttet%7Cm%C3%A5tte"]]},
  hjelpe:{zh:"帮助；帮忙；（措施、药物等）起作用、有效（依语境）",note:"帮助某人可直接接宾语：hjelpe en venn；帮忙做某事常用 hjelpe til med；药物或办法作主语时 hjelpe mot 表示对……有效。不要把所有用法都缩成泛泛的‘帮助’。",contexts:[["De hjelper hverandre.","他们互相帮助。","词典原句；hjelpe hverandre 是‘彼此帮助’的常见反身互指结构。","https://ordbokene.no/bm/23710"]]},
  se:{zh:"看见；看、观看；理解/看出；经历、发现；认为（依结构）",note:"眼睛感知是‘看见’，有意观看常用 se på TV/en film；se at 表示看出/意识到；Jeg ser det annerledes 是‘我对此看法不同’。注意 se 的过去式 så、完成分词 sett。",contexts:[["Han så en film.","他看了一部电影。","词典原句；se + 电影表示观看，过去式 så。","https://ordbokene.no/bm/50315"]]},
  ligge:{zh:"躺；平放、静置；位于；处于某种状态/水平（依主语）",note:"人/动物身体呈水平状态用 ligge；物品平放或地点所在也用 ligge：boka ligger på bordet。对比：sette 是把东西放到某处的动作，ligge 是已处于平放/所在状态；站立摆放常用 stå。",contexts:[["Boka ligger på bordet.","书在桌子上。","词典原句；ligge 表示物品已处于某处，描述位置/状态而非放置动作。","https://ordbokene.no/nob/bm/ligger%7Cligge"]]},
  sette:{zh:"放置；摆放；使进入某种位置/状态；设置、安排；投入/种植（依宾语）",note:"sette 是让某人/物到某处的动作：sette maten på bordet；反身 sette seg 是坐下。对比 sitte（坐着的状态）和 ligge（平放/位于的状态）。固定搭配意义可能变化，如 sette i gang（启动）。",contexts:[["De setter skoene i gangen.","他们把鞋放在走廊里。","词典原句；sette + 物品 + 地点表示把物品放到某处。","https://ordbokene.no/bm%2Cnn/sette"]]},
  sitte:{zh:"坐；坐着；就座；停留/位于；牢固嵌在某处；任职（依主语和搭配）",note:"人坐着是核心义；钥匙插在锁里也可用 sitte：nøkkelen sitter i låsen。对比 sette seg（坐下这个动作）与 sitte（坐着的状态），以及物品平放的 ligge。",contexts:[["Gjestene satt i sofaen.","客人们坐在沙发上。","词典原句；sitte 表示坐着的状态，过去式 satt。","https://ordbokene.no/nno/bm/sitte"]]},
  stå:{zh:"站；竖立；放置/位于；处于某种状态；保持不动（依主语）",note:"人站着可用 stå；书本等竖放或按惯常方式摆放也常用 stå：bøkene står i hylla。对比 sette（放置的动作）与 stå（已经在某处/保持竖立的状态）；不是所有中文‘在’都译成 stå。",contexts:[["Bøkene står i hylla.","书在书架上。","词典原句；此处 stå 描述书本已放在书架上的位置状态。","https://ordbokene.no/bm/%C3%A5%20st%C3%A5"]]},
  finne:{zh:"找到；发现；想出/得出；认为、觉得（finne noen/noe + 形容词）（依结构）",note:"寻找后找到：finne en nøkkel；思考后得出：finne en løsning；表达评价时可用 finne noe vanskelig/mistenkelig（觉得某事困难/可疑）。finne at 可引出判断；不要把它和 se（看见）混为一谈。",contexts:[["Jeg fant hammeren i boden.","我在储物间找到了锤子。","词典原句；finne 表示发现/找到，过去式为 fant。","https://ordbokene.no/nno/bm/finne"]]},
  gi:{zh:"给；递给；提供；给予（依宾语和结构）",note:"gi noen noe 是‘给某人某物’：gi meg boka（把书给我）；也可表示提供机会、帮助、答案等。注意 gi opp 是放弃/报出，gi seg 是停止或让步，需连固定搭配一起记。",contexts:[["Gi meg avisen.","把报纸递给我。","词典原例；祈使句中省略 du，gi + 人 + 物表示把物品递给某人。","https://ordbokene.no/bm/%C3%A5%20gi"]]},
  holde:{zh:"拿着；握住；保持；遵守；举行/举办；容纳、支撑（依结构）",note:"holde noe i hånden 是手里拿着；holde seg hjemme 是待在家；holde ord 是守信用；holde konsert 是举办音乐会。holde på med 表示正在做某事，不要只按‘拿住’理解。",contexts:[["Han holdt barnet i armene.","他把孩子抱在怀里。","词典原句；holde + 人 + i armene 表示把人抱持在臂弯中。","https://ordbokene.no/bm/holde"]]},
  kunne:{zh:"会；能；可以；可能（依语境）",note:"表示学会的技能：kunne sykle（会骑车）；表示能力或条件：kunne gjøre noe（能够做某事）；也可表示可能性：det kan skje（这可能发生）。情态动词后接动词原形，通常不加 å。",contexts:[["Hun kan sykle.","她会骑自行车。","词典原句；kunne 表示掌握一项技能，后接动词原形 sykle。","https://ordbokene.no/bm/%C3%A5%20kunne"]]},
  løpe:{zh:"跑；奔跑；快速移动；（时间、期限等）流逝/到期（依主语）",note:"人或动物用脚快速移动是‘跑’；河流、道路、地球等作主语时可表示延伸/流动；løpe fra ansvaret 是逃避责任，løpe ut 可表示期限到期。",contexts:[["De løper om kapp.","他们在赛跑。","词典原句；løpe om kapp 表示比赛谁跑得快。","https://ordbokene.no/nob/bm/l%C3%B8pe"]]},
  løfte:{zh:"抬起；举起；提起；提高/提升；举杯祝酒（依宾语）",note:"具体物体向上移动是抬/举：løfte en stein；抽象事物可译提升：løfte nivået；løfte glasset 是举杯。搭配反身代词的 løfte seg selv etter håret 是“不可能自举”的固定表达。",contexts:[["Heisekrana løfter flere tonn.","起重机能吊起好几吨。","词典原句；løfte + 重物表示把它抬升。","https://ordbokene.no/bm/34404"]]},
  rope:{zh:"喊；大声呼喊；呼唤；要求/索要（rope på noe）（依结构）",note:"大声发声可为呼喊、求助：rope om hjelp；rope på noen 是呼唤某人；rope på høyere lønn 则是要求更高工资，不是“对工资喊叫”。",contexts:[["De ropte raskt om hjelp.","他们赶紧大声呼救。","词典原句；rope om hjelp 表示喊着求助。","https://ordbokene.no/bm/rope"]]},
  stoppe:{zh:"停下；停止；使……停下；塞住/填塞；织补（依搭配）",note:"交通工具或人 stoppe 是停下来；stoppe motoren 是让发动机停止；stoppe pipa 是把管道/烟囱塞住；stoppe strømper 是织补袜子。具体义由宾语判断。",contexts:[["Bussen stoppet med et rykk.","公交车猛地停了下来。","词典原句；不及物 stoppe 表示车辆停止移动。","https://ordbokene.no/bm/stoppe"],["Kan du stoppe motoren?","你能把发动机停下来吗？","词典原句；及物 stoppe + 机器表示使其停止。","https://ordbokene.no/bm/stoppe"]]},
  synge:{zh:"唱；唱歌；（鸟、流水等）发出悦耳声；叮当作响（依主语）",note:"人用声音唱旋律是最常见义；动物、流水或金属也可用 synge 描写类似歌声的声音。synge en sang（唱一首歌）；synge på en sang 是嘴里哼/唱着某首歌。",contexts:[["De synger i et kor.","他们在合唱团里唱歌。","词典原句；synge i et kor 表示参加合唱。","https://ordbokene.no/bm/synge"]]},
  våkne:{zh:"醒来；醒过来；（兴趣、自然等）开始活跃/苏醒（依主语）",note:"人从睡眠或麻醉中醒来时是不及物动词，主语就是醒来的人；学习兴趣、自然等作主语时可表示开始显现活力。不要与形容词 våken（醒着的）混淆。",contexts:[["våkne ved den minste lyd","一有一点声音就醒来","词典原例为不定式短语；表示睡眠中的人容易被声音叫醒。","https://ordbokene.no/bm/v%C3%A5kne"]]},
  åpne:{zh:"打开；开启；开放/开始营业；发起、开场；使……成为可能（依搭配）",note:"打开门窗、信件是具体动作；咖啡馆作主语 åpner klokka ni 表示九点开门营业；åpne et møte 是开会；åpne for 表示为某事创造可能或接受某方案。",contexts:[["Han åpnet døra forsiktig.","他小心地打开了门。","词典原句；åpne døra 是把门从关闭状态打开。","https://ordbokene.no/bm/%C3%A5pne"]]},
  bruke:{zh:"使用；利用；消耗/花费；习惯于、通常（依结构）",note:"bruke briller 是使用眼镜；bruke tid/penger 是花时间/钱；bruke å + 动词（常见于口语）可表示习惯做某事。bruke opp 强调用完。",contexts:[["Hun brukte lang tid på leksene.","她做作业花了很长时间。","词典原句；bruke tid på noe 表示在某事上花时间。","https://ordbokene.no/bm/%C3%A5%20bruke"]]},
  bære:{zh:"拿/提/搬；背负、承受；穿戴；支撑、承载（依宾语）",note:"移动物品是拿/提/搬；穿民族服装、帽子可用 bære；承受重量或压力也可用 bære。过去式 bar，完成分词 båret/båret（词形按项目现有范式核验）。",contexts:[["Han bar en koffert.","他提着一只行李箱。","词典原句；bære + 物品表示拿着并搬运。","https://ordbokene.no/bm/b%C3%A6re"]]}
});
