const V2_REVIEW_BATCH_37 = {
  "名词|termometer": { zh:"温度计；体温计（依测量对象）", note:"et termometer 测量温度。用于人体时是体温计，用于室内或户外时是温度计；仪器本身并不限定用途。复数不规则：termometre–termometrene。https://ordbokene.no/bm/termometer", contexts:[["Termometeret viser fem grader.","温度计显示五度。","词典例句；五度是环境温度读数，不能据此译成体温。","https://ordbokene.no/bm/termometer"],["Vi målte barnets temperatur med et termometer.","我们用体温计给孩子量了体温。","测量人体温度的语境明确，因此译作体温计。"]] },
  "名词|panne": { zh:"额头；平底锅/煎锅（依语境）", note:"ei/en panne 有两个常见义。身体动作、头部位置常指额头；steke i ei panne（在锅里煎）指平底锅。搭配动作能帮助判断，不能只看单词就固定成一个中文义。https://ordbokene.no/bm/panne", contexts:[["Hun slo panna i skapdøra.","她的额头撞到了柜门。","身体撞到柜门，panna 是额头。","https://ordbokene.no/bm/panne"],["Jeg steker egg i ei panne.","我用平底锅煎鸡蛋。","steke egg i ei panne 是烹饪场景，panne 指煎锅。"]] },
  "名词|bein": { zh:"腿；骨头（依语境）", note:"et bein 可指从髋部到脚的腿，也可指身体里的骨头。动作/身体部位语境如 stå på ett bein 是“单腿站立”；可咀嚼的物件语境如 et bein til hunden 是“给狗的一根骨头”。复数可用 beina 或 beinene；ben 也是规范拼法。https://ordbokene.no/bm/bein", contexts:[["Jeg har vondt i beinet etter fotballtreningen.","足球训练后我腿疼。","vondt i beinet 通常指腿疼，不足以说明骨头受伤。","https://ordbokene.no/bm/bein"],["Hunden fikk et bein å tygge på.","狗得到一根骨头啃。","tygge på（啃）提供了线索，此处 bein 指骨头。"]] },
  "名词|blodåre": { zh:"血管", note:"透明复合词 blod（血）+ åre（管状通道）构成；日常及健康语境译“血管”。不要把“血脉”当作默认义，它在中文里容易带文学或亲缘比喻色彩。医学分类要看具体词：arterie 是动脉，vene 是静脉。https://ordbokene.no/bm/blod%C3%A5re", contexts:[["Sykepleieren fant en blodåre på armen.","护士在手臂上找到了一条血管。","医疗场景中是在手臂上寻找血管。","https://ordbokene.no/bm/blod%C3%A5re"],["Blodårene fører blod rundt i kroppen.","血管把血液输送到全身。","说明句中复数 blodårene 指遍布身体的血管。"]] },
  "名词|finger": { zh:"手指", note:"en finger 指手上的一根手指，拇指也包括在内；不包括手掌（håndflate）。注意不规则复数 finger–fingre–fingrene。https://ordbokene.no/bm/finger", contexts:[["Hun skar seg i fingeren da hun laget middag.","她做晚饭时把手指划伤了。","i fingeren 指受伤部位是手指。","https://ordbokene.no/bm/finger"],["Barnet teller på fingrene.","孩子掰着手指计数。","på fingrene 表示用手指计数。"]] },
  "名词|hud": { zh:"皮肤；（动物）皮；（比喻）船体外壳", note:"ei/en hud 首先指覆盖人或动物身体的皮肤；动物毛皮/皮革语境可指皮；船舶语境可指船体外壳。日常身体主题先掌握“皮肤”。https://ordbokene.no/bm/hud", contexts:[["Huden blir tørr om vinteren.","冬天皮肤会变干。","描述人体皮肤状态。","https://ordbokene.no/bm/hud"],["Barnet fikk utslett på huden.","孩子皮肤上起了疹子。","på huden 说明疹子出现在皮肤上。"]] },
  "名词|kinn": { zh:"脸颊；面颊", note:"et kinn 是脸的左右两侧、眼睛下方至下颌附近的面颊，不是整个脸（ansikt）。词典另有地形义“陡峭山坡”，初级身体词汇中通常先学面颊义。https://ordbokene.no/bm/kinn", contexts:[["Hun kysset barnet på kinnet.","她亲了亲孩子的脸颊。","på kinnet 指亲吻的位置是脸颊。","https://ordbokene.no/bm/kinn"],["Gutten hadde røde kinn etter skituren.","男孩滑雪回来后脸颊红扑扑的。","kinn 指脸颊；røde 描写脸颊发红。","https://ordbokene.no/bm/kinn"]] },
  "名词|leppe": { zh:"嘴唇；（依语境）边缘状垂片/唇状部分", note:"ei/en leppe 最常见指嘴周围上下两片柔软的嘴唇；植物或物体结构中也可指类似唇片、边缘的部分。身体部位义和形状引申义看所指对象判断。https://ordbokene.no/bm/leppe", contexts:[["Hun har tørre lepper.","她嘴唇干燥。","复数 lepper 指嘴唇。","https://ordbokene.no/bm/leppe"],["Han bet seg i leppa.","他咬了咬嘴唇。","leppa 是 leppe 的阴性定指单数。","https://ordbokene.no/bm/leppe"]] },
  "名词|lunge": { zh:"肺；一侧肺（成对呼吸器官之一）", note:"ei/en lunge 指左右两侧肺中的一侧；lungene 常指双肺。引申短语 grønn lunge 指城市里的大片绿地/公园，不是字面上的肺。https://ordbokene.no/bm/lunge", contexts:[["Lungene er organer for åndedrettet.","肺是呼吸器官。","词典例句；复数 lungene 指成对的肺。","https://ordbokene.no/bm/lunge"],["Hun fikk en infeksjon i den ene lungen.","她的一侧肺部感染了。","den ene lungen 明确指两侧肺中的一侧。"]] },
  "名词|hode": { zh:"头；头部；（依搭配）头脑、每人/每个", note:"et hode 的具体身体义是头部；bruke hodet 可引申为动脑筋；per hode 表示按人数计算。中文依句子选义，不要把所有语境都翻成“头脑”。日常先记复数定指 hodene。https://ordbokene.no/bm/hode", contexts:[["Jeg har vondt i hodet og trenger å hvile.","我头疼，需要休息。","ha vondt i hodet 是“头疼”的常见表达。","https://ordbokene.no/bm/hode"],["Vi betaler hundre kroner per hode.","我们每人付一百克朗。","per hode 表示按人数计算。"]] },
  "名词|muskel": { zh:"肌肉；（引申）力量、实力/资源", note:"en muskel 指能收缩并带动身体运动的肌肉组织；抽象语境里可比喻力量或资源，如 økonomiske muskler（经济实力）。https://ordbokene.no/bm/muskel", contexts:[["Jeg har vondt i musklene etter treningen.","锻炼后我肌肉酸痛。","运动后身体不适，musklene 指肌肉。","https://ordbokene.no/bm/muskel"],["Store selskaper har økonomiske muskler.","大公司拥有雄厚的经济实力。","比喻用法；muskler 指可动用的资源和实力。","https://ordbokene.no/bm/muskel"]] },
  "名词|forkjølelse": { zh:"感冒；普通感冒（上呼吸道病毒感染）", note:"ei/en forkjølelse 指常见的上呼吸道病毒感染，可引起鼻塞、流鼻涕、咽喉不适；不同于流感 influensa。名词是 forkjølelse，形容词“感冒的”是 forkjølet。https://ordbokene.no/bm/forkj%C3%B8lelse%7Cforkj%C3%B8le", contexts:[["Barnet har fått en forkjølelse.","孩子感冒了。","få en forkjølelse 表示患上一次普通感冒。","https://ordbokene.no/bm/forkj%C3%B8lelse%7Cforkj%C3%B8le"],["Jeg er forkjølet og har rennende nese.","我感冒了，还流鼻涕。","forkjølet 是形容词形式，与本卡名词 forkjølelse 区分。"]] },
  "名词|hals": { zh:"脖子、颈部；喉咙/咽喉（依语境）", note:"en hals 有两个常见身体义：外侧连接头和躯干的是脖子/颈部；吞咽、咳嗽、发炎等语境常译喉咙。ha vondt i halsen 通常是喉咙痛；围巾绕在 halsen 上则是脖子。https://ordbokene.no/bm/hals", contexts:[["Jeg har vondt i halsen og hoster.","我喉咙痛，还咳嗽。","症状语境提示 halsen 指喉咙。","https://ordbokene.no/bm/hals"],["Han tok på seg et skjerf rundt halsen.","他把围巾围在脖子上。","围巾绕在身体外侧部位，halsen 指脖子。","https://ordbokene.no/bm/hals"]] },
  "名词|hevelse": { zh:"肿胀；肿起来的部位", note:"ei/en hevelse 描述身体某处肿起来的状态或肿胀区域；不一定是独立的“肿块”，也不说明病因。https://ordbokene.no/bm/hevelse", contexts:[["Legen så en hevelse over øyet.","医生看到眼睛上方有一处肿胀。","说明肿胀的位置，不据此推断病因。","https://ordbokene.no/bm/hevelse"],["Hevelsen gikk ned etter noen dager.","几天后肿胀消退了。","hevelsen 是定指单数，回指已提到的肿胀。"]] },
  "名词|influensa": { zh:"流感；流行性感冒", note:"ei/en influensa 是由流感病毒引起的传染性疾病，常伴高热、头痛、肌肉疼痛；不同于普通感冒 forkjølelse。口语有时把严重感冒叫 influensa，但学习时先按“流感”记。https://ordbokene.no/bm%2Cnn/INFLUENSA", contexts:[["Hun fikk influensa og måtte holde seg hjemme.","她得了流感，只好待在家里。","场景中的 influensa 指流感，不是普通伤风。","https://ordbokene.no/bm%2Cnn/INFLUENSA"],["Influensa kan gi feber og muskelsmerter.","流感可能引起发烧和肌肉疼痛。","说明常见症状，不表示每位患者都一定出现这些症状。"]] },
  "形容词|kvalm": { zh:"恶心的；令人作呕/不舒服的；（空气）闷得令人难受", note:"形容人时是感到恶心；形容气味、饮料或行为时可指令人反胃/不快；形容空气时是闷、憋闷。另有同形阳性名词 en kvalm，表示喧闹、骚动，是不同词条。https://ordbokene.no/bm/kvalm", contexts:[["Jeg blir kvalm av lukta.","这股气味让我觉得恶心。","形容词 kvalm 描述人的感受；av lukta 指引发不适的原因。","https://ordbokene.no/bm/kvalm"],["Det er kvalm og innestengt luft her.","这里的空气又闷又不流通。","形容空气时不是“恶心”，而是闷得令人难受。","https://ordbokene.no/bm/kvalm"]] },
  "名词|resept": { zh:"处方；药方；（引申）做法、诀窍/实现方案", note:"en resept 在医疗语境中是医生开具的用药处方：få medisinen på resept（凭处方拿药）；不等同于烹饪食谱。引申义可指实现某种结果的方法或诀窍。https://ordbokene.no/bm/resept", contexts:[["Legen skrev ut en resept på medisinen.","医生开了一张药物处方。","skrive ut en resept 是“开具处方”。","https://ordbokene.no/bm/resept"],["Det finnes ingen enkel resept på suksess.","成功没有简单的诀窍。","比喻义；resept 指通往成功的一套办法。","https://ordbokene.no/bm/resept"]] },
  "名词|smerte": { zh:"疼痛；痛苦；令人痛苦的事（依语境）", note:"ei/en smerte 可指身体疼痛，也可指心理痛苦、折磨；ha smerter 常用复数表达身体疼痛。另有同形动词 smerte（使疼痛/令人痛苦），不要混成本名词卡的词性。https://ordbokene.no/bm/smerte", contexts:[["Hun kjente en stikkende smerte i hodet.","她感到头部一阵刺痛。","词典例句；en smerte 是一种具体疼痛。","https://ordbokene.no/bm/smerte"],["Han kjente smerte da han falt.","他摔倒时感到疼痛。","名词 smerte 指身体疼痛。"]] },
  "形容词|svimmel": { zh:"头晕的；眩晕的；（高度/旋转等引起）发晕的", note:"形容人感觉头晕、天旋地转或站不稳；可由生病、突然站起或高处等引起。它描述一种感觉，不单独等于某个医学诊断。https://ordbokene.no/nno/bm/svimmel", contexts:[["Jeg ble svimmel da jeg reiste meg fort.","我突然站起来时感到一阵头晕。","描述一时的头晕感觉，不是医学诊断。","https://ordbokene.no/nno/bm/svimmel"],["Hun blir svimmel av å se ned fra høyden.","她从高处往下看会头晕。","高度引发的发晕感。"]] },
  "形容词|syk": { zh:"生病的；患病的；（引申）极度渴望/沉迷、荒唐；（口语加强）非常", note:"描述人、动物或植物时是生病/不健康；syk av hjemlengsel 是极度思念家乡；sykt bra 中 sykt 是口语程度副词“非常”；形容行为时也可指荒唐、疯狂。依上下文选义。https://ordbokene.no/bm/syk", contexts:[["Hunden er syk og vil ikke spise.","狗病了，不想吃东西。","动物作主语时仍可用 syk 表示患病。","https://ordbokene.no/bm/syk"],["Det er sykt bra!","这简直太棒了！","口语加强用法 sykt 相当于“特别/非常”，不是“病态地好”。","https://ordbokene.no/bm/syk"]] },
  "名词|utslett": { zh:"皮疹；皮肤上出现的疹子/炎症", note:"et utslett 是皮肤上出现的疹子或炎症表现，可能有不同外观；不一定发红，也不能仅凭这个词判断原因或疾病。常见 få utslett（起疹子）、utslett på huden（皮肤上的皮疹）。https://ordbokene.no/bm/utslett", contexts:[["Barnet fikk utslett på armene.","孩子手臂上起了疹子。","få utslett 表示出现皮疹；词本身不说明疹子的颜色或病因。","https://ordbokene.no/bm/utslett"],["Utslettet klør, men er ikke rødt.","这片皮疹发痒，但没有发红。","utslett 不必然是红疹。"]] },
  "名词|vondt": { zh:"疼痛；痛楚（名词）", note:"Bokmålsordboka 将疼痛义的 et vondt 列作中性名词：et vondt–vondtet–vondt–vondta/vondtene。ha vondt i halsen 中 vondt 是名词性表达“疼”；det gjør vondt 中则是形容词中性形式。按本卡词性和词形学习，不能把名词与形容词词条混在一起。https://ordbokene.no/bm/vondt", contexts:[["Ha vondt i halsen.","喉咙疼。","词典固定搭配；此处按名词 vondt 记忆，是身体某处疼痛的表达。","https://ordbokene.no/bm/vondt"],["Vondtet i ryggen kom tilbake.","背部的疼痛又出现了。","词典例句；vondtet 是 et vondt 的定指单数。","https://ordbokene.no/bm/vondt"]] },
  "名词|liv": { zh:"生命；生活；活力/生气；寿命或人生阶段（依语境）", note:"et liv 可指生命/存在，也可指生活状态和人生经历；liv i rommet 表示房间里有活力或热闹；et langt liv 指长寿。根据句子选“生命”还是“生活”。https://ordbokene.no/nob/bm/liv", contexts:[["Hun har hatt et langt og godt liv.","她度过了漫长而幸福的一生。","liv 指一个人的人生经历。","https://ordbokene.no/nob/bm/liv"],["Det var liv i gatene hele kvelden.","整晚街上都很热闹。","liv 在这里表示活力、人群和活动，不是生命本身。","https://ordbokene.no/nob/bm/liv"]] },
  "名词|bråk": { zh:"吵闹；喧哗；争吵、麻烦（依语境）", note:"日常用法是 et bråk，指很大的噪声/喧闹，也可指由此引发的争执或风波。lage bråk 可指制造噪声或惹麻烦。词典另有罕见旧义，初级日常主题不采用。https://ordbokene.no/bm/br%C3%A5k", contexts:[["Barna laget mye bråk i gangen.","孩子们在走廊里吵得很厉害。","bråk 指吵闹声；mye 修饰喧闹。","https://ordbokene.no/bm/br%C3%A5k"],["Det ble bråk etter kampen.","比赛结束后起了争执。","bråk 在此指争吵或风波。","https://ordbokene.no/bm/br%C3%A5k"]] },
  "动词|hyle": { zh:"尖叫；嚎叫；发出尖锐长声", note:"å hyle 指人或动物发出高而尖的叫声，也可形容警报、风等发出尖锐长声。与 gråte（哭）不同：hyle 强调叫声，不一定是在哭。https://ordbokene.no/bm/hyle", contexts:[["Barnet begynte å hyle da det slo seg.","孩子摔疼后开始大声哭喊。","hyle 描写尖叫/哭喊声，句子本身不单说流泪。","https://ordbokene.no/bm/hyle"],["Ulven hylte om natta.","狼在夜里嚎叫。","动物作主语时 hyle 可译“嚎叫”。","https://ordbokene.no/bm/hyle"]] }
};
for (const entry of window.VOCAB_V2.additions) {
  const lemmaKey = entry.word.replace(/^(?:å|en|ei|et)\s+/u, "").trim();
  const correction = V2_REVIEW_BATCH_37[`${entry.pos}|${lemmaKey}`];
  if (correction) Object.assign(entry, correction);
}
const V2_REVIEW_BATCH_38 = {
  "名词|hyling":{word:"en hyling",zh:"尖叫声；嚎叫声；呼啸声（依发声者）",forms:["en/ei hyling","hylingen/hylinga","hylinger","hylingene"],labels:["不定单数（阳/阴性）","定指单数（两种形式）","不定复数","定指复数"],note:"由 hyle（尖叫、嚎叫）派生，指高声叫喊/嚎叫这一声音或行为；可以是人群的尖叫，也可以是动物或风的呼啸。可用阳性 en 或阴性 ei。中文要看来源：孩子们的 hyling 是尖叫声，风的 hyling 是呼啸声。",contexts:[["Det ble hyling og applaus fra publikum.","观众席上响起一阵尖叫和掌声。","词典例句；hyling 描写观众发出的高声反应，并非特指孩子。","https://ordbokene.no/bm/hyling"],["Hylingen fra vinden vekket barna.","风的呼啸声把孩子们吵醒了。","hylingen 是定指形式；由 fra vinden 可知发声者是风，因此译“呼啸声”。"]]},
  "动词|høres":{zh:"听起来；听得见；据说/传闻（依结构）",note:"本卡对应动词 å høres。Det høres bra ut 表示“听起来不错”；Stemmen høres tydelig 表示声音能被听清；det høres at ... 可表示“听说……”。høres ut som + 名词/从句常用于表达听者的判断，不等同于 høre（主动听）。",contexts:[["Det høres ut som en god plan.","听起来是个不错的计划。","høres ut som + 名词短语：根据听到的信息作判断。","https://ordbokene.no/bm/h%C3%B8res"],["Stemmen hennes høres tydelig gjennom veggen.","隔着墙也能清楚听见她的声音。","这里是声音能被听见，不是“听起来像”。","https://ordbokene.no/bm/h%C3%B8res"]]},
  "名词|nisse":{zh:"圣诞老人；北欧民间传说中的小精灵/守护灵（依传统语境）",note:"en nisse 在圣诞语境里常指 julenissen（给孩子送礼物的圣诞老人）；民间传说中的 nisse 则是与农庄、家庭或牲畜相关的小型超自然精灵，传统形象常戴红帽。口语中还可贬称“傻瓜”，此义语气不友好。",contexts:[["Barna gleder seg til at nissen kommer med gaver.","孩子们盼着圣诞老人来送礼物。","圣诞习俗语境；nisse 是 julenisse 的简称用法。","https://ordbokene.no/bm%2Cnn/nisse"],["I folketroen bor nissen ofte på gården.","在民间传说中，nisse 常住在农庄里。","此处是传统民间精灵义，不是现代圣诞老人。","https://ordbokene.no/bm%2Cnn/nisse"]]},
  "名词|julepynt":{word:"julepynt",zh:"圣诞装饰；圣诞节装饰品（作为一批装饰统称）",forms:["julepynt","julepynten"],labels:["不定形式/集合用法","定指单数/整批装饰"],note:"julepynt 通常作中性集合名词，日常说 julepynt（圣诞装饰）或 julepynten（那批圣诞装饰），不应把 en julepynt 当作通常词形。指一件具体装饰物时，更自然说 en juledekorasjon 或具体物名，如 en julekule（一颗圣诞树球）。",contexts:[["Vi tar fram julepynten i desember.","我们十二月会把圣诞装饰拿出来。","julepynten 是定指形式，指家里那批装饰物。","https://ordbokene.no/bm%2Cnn/julepynt"],["Barna laget julepynt av papir.","孩子们用纸做了圣诞装饰。","julepynt 是集合用法；av papir 说明材料是纸。","https://ordbokene.no/bm%2Cnn/julepynt"]]},
  "副词|før":{zh:"以前；此前；从前",note:"作为副词，før 说的是某个时间点之前或过去的经历：Jeg har vært her før（我以前来过这里）。在 fra før 中表示“原本就/早已”。本卡不把同形的介词/从属连词 før（在……之前）混作副词。",contexts:[["Jeg har vært her før.","我以前来过这里。","før 作副词，指过去某个时间来过。","https://ordbokene.no/bm/f%C3%B8r"],["Kjenner du henne fra før?","你以前就认识她吗？","固定搭配 fra før 表示“之前就、原本就”。","https://ordbokene.no/bm/f%C3%B8r"]]},
  "形容词|fri":{zh:"自由的；不受……限制/影响的；空闲的；免费的（依搭配）",note:"描述人时 fri 可指有空或休假（Jeg er fri i morgen）；描述事物可指不含某物/不受某因素影响（sukkerfri=无糖）；描述制度或行动可指自由、不受限制；fri inngang 是免费入场。具体意义看名词与介词搭配。",contexts:[["Jeg er fri på fredag.","我星期五有空/休息。","描述人的时间安排；这里不是“自由身”。","https://ordbokene.no/bm/17947"],["Billettene gir fri inngang til museet.","这些票可以免费进入博物馆。","fri 修饰 inngang，表达无需另付入场费。","https://ordbokene.no/bm/17947"]]},
  "名词|halvtime":{zh:"半小时；三十分钟",note:"en halvtime 等于三十分钟，词形 en halvtime–halvtimen–halvtimer–halvtimene。常说 om en halvtime（半小时后）、i en halvtime（持续半小时）、hver halvtime（每半小时）；介词改变时间关系。",contexts:[["Bussen går hver halvtime.","公交车每半小时一班。","hver halvtime 表示发车间隔为三十分钟。","https://ordbokene.no/bm/halvtime"],["Det tar en halvtime å gå til stasjonen.","走到车站要半小时。","en halvtime 表示所需时长，不是“半点钟”。","https://ordbokene.no/bm/halvtime"]]},
  "名词|periode":{zh:"一段时期；阶段；周期（依领域）",note:"en periode 指有起止范围的一段时间或过程阶段；在重复现象中也可指周期。政治语境的 en periode 可指一届任期，学校/工作语境可指一阶段。结合修饰语判断，不要一律译作“周期”。",contexts:[["Hun var syk i en kort periode.","她有一小段时间生病了。","i en kort periode 表示持续的一段时期。","https://ordbokene.no/nob/bm/44674"],["En periode i livet kan være krevende.","人生中的某个阶段可能会很不容易。","这里指人生阶段，并非重复周期。","https://ordbokene.no/nob/bm/44674"]]},
  "名词|slutt":{zh:"结束；末尾；最后一部分",note:"en slutt 可指事情结束这一结果、某个过程的末尾，也可指剩下的最后一部分。til slutt 是“最后/终于”；mot slutten av uka 是“接近周末时”；ta slutt 是“结束/停止”。",contexts:[["Til slutt fant vi nøklene.","最后我们找到了钥匙。","til slutt 标示事件顺序，中文译“最后”。","https://ordbokene.no/bm/slutt"],["Filmen hadde en overraskende slutt.","这部电影的结尾出人意料。","en slutt 指故事的结尾部分。","https://ordbokene.no/bm/slutt"]]},
  "副词|lenge":{zh:"很久；长时间",note:"lenge 作副词表示持续时间长：vente lenge（等很久）、lenge siden（很久以前）。问时长常用 Hvor lenge?（多久？）。比较级 lenger 可表示“更久/不再”，要由句子判断。",contexts:[["Vi ventet lenge på bussen.","我们等公交等了很久。","lenge 描述等待持续时间。","https://ordbokene.no/bm/lenge"],["Det er lenge siden jeg så henne.","我已经很久没见她了。","lenge siden 是“很久以前/已经有很长时间”。","https://ordbokene.no/bm/lenge"]]},
  "从属连词|når":{zh:"当……时；每当……；（引出未来事件）等……时",note:"本条讲从属连词 når：它引导时间从句，意思是“当/等……时”。描述将来时，挪威语时间从句通常用现在时：Når jeg kommer hjem, ringer jeg deg（我到家后给你打电话）。间接问句“你知道火车几点开吗？”中的 når 是疑问副词，虽拼写相同但句法功能不同，不放进本条的从属连词释义。",contexts:[["Når jeg kommer hjem, ringer jeg deg.","我到家后给你打电话。","从句 Når jeg kommer hjem 表示将来的时间条件；从句动词用现在时 kommer。","https://ordbokene.no/bm/114627"],["Ring meg når du er framme.","你到了以后给我打电话。","når 引导时间从句；这里接近“等……之后”。","https://ordbokene.no/bm/114627"]]},
  "介词|innen":{zh:"在……期限内；不迟于……（截止时间）",note:"innen + 时间点/期限常表示“在……之前完成、最晚不超过……”：innen fredag（最迟星期五）、innen en uke（一周内）。与 innenfor（在边界/范围以内）区分。若截止日是否包含当天非常重要，挪威语里也可能有歧义，应改用具体时刻/日期。",contexts:[["Du får svar innen en uke.","你会在一周内收到答复。","innen en uke 给出最迟答复期限，不是说整个一周都持续收到答复。","https://ordbokene.no/bm/innen"],["Søknaden må sendes innen fredag.","申请必须最迟在星期五前寄出。","innen 标示截止时间；若精确到当天某时，应补充明确时刻。","https://ordbokene.no/bm/innen"]]},
  "名词|tidsfrist":{zh:"截止期限；最后期限；截止日期/时间",note:"en tidsfrist 是必须在某个时间点前完成或提交的期限；可指期限这一要求，也可指具体截止时间。holde/friste en tidsfrist 是遵守期限，oversitte tidsfristen 是超过期限。和 tidsrom（时间段）不同，tidsfrist 带有最晚完成的要求。",contexts:[["Vi må overholde tidsfristen.","我们必须遵守截止期限。","tidsfristen 是定指形式，指双方已知的那个最后期限。","https://ordbokene.no/bm/tidsfrist"],["Fristen for å søke er 1. juni.","申请截止日期是6月1日。","fristen 是 tidsfrist 的常见简写，后面给出具体日期。","https://ordbokene.no/bm/tidsfrist"]]},
  "名词|begynnelse":{zh:"开始；开头；起初阶段",note:"en begynnelse 指某事开始的时间或最初部分。i begynnelsen av uka 是“周初”；til å begynne med 是“起初/一开始”；从整件事的起点说，也常用 start。",contexts:[["I begynnelsen av boka møter vi hovedpersonen.","在书的开头，我们认识了主人公。","begynnelsen 指文本最前面的部分。","https://ordbokene.no/bm/begynnelse"],["Til å begynne med var det vanskelig.","一开始这件事很难。","固定表达 til å begynne med 表示“起初”。","https://ordbokene.no/bm/begynnelse"]]},
  "副词|lenger":{zh:"更远；更久；不再（常见于 ikke lenger）",note:"lenger 是 langt（远）或 lenge（久）的比较级形式。带地点参照时译“更远”：gå lenger；带时间参照时译“更久”；ikke lenger 是“不再”。要靠句子里的地点、时长或否定判断。",contexts:[["Vi kan ikke vente lenger.","我们不能再等下去了。","否定词 ikke + lenger 表示“不能继续/不再”。","https://ordbokene.no/bm/lenger"],["Gå litt lenger fram.","再往前走一点。","有方向/位置参照时，lenger 表示距离更远。","https://ordbokene.no/bm/lenger"]]},
  "副词|imens":{zh:"与此同时；在这段时间里",note:"imens 通常作副词，指另一件事发生的同一段时间，常见句首/句中承接前后动作。不要把它机械当作 mens（当……时）从属连词来造句；初学者表达“当……时”优先学 mens。",contexts:[["Hun laget middag. Imens dekket barna bordet.","她做晚饭。与此同时，孩子们摆好了餐桌。","imens 在第二句作承接副词，意思是“与此同时”；这里用句号分隔避免把连词句型误当副词。","https://ordbokene.no/bm/imens"],["Jeg ryddet kjøkkenet, og imens hørte jeg på radio.","我收拾厨房时，同时听着收音机。","这里 imens 承接同一时段的另一动作。","https://ordbokene.no/bm/imens"]]},
  "副词|nettopp":{zh:"刚刚；正好/恰恰；（口语）正是如此；马上（依语境）",note:"nettopp 的译法看位置与上下文：har nettopp gjort 表示“刚刚做了”；nettopp klokka tre 表示“正好三点”；nettopp derfor 表示“正因为如此”；在 det skjer nettopp nå 中表示“此刻/正是现在”。它不是可随意插入句子的填充词。",contexts:[["Hun har nettopp kommet hjem.","她刚到家。","完成时 har + nettopp + 分词，表示动作刚刚发生；删掉 nettopp 句子仍成立，但“刚刚”这一时间信息消失。","https://ordbokene.no/nob/bm%2Cnn/nettopp"],["Det var nettopp det jeg mente.","我说的正是这件事。","nettopp 强调“正是”，不是时间上的“刚刚”。","https://ordbokene.no/nob/bm%2Cnn/nettopp"]]},
  "名词|stund":{zh:"一会儿；一段时间；片刻",note:"en stund 是不精确的一段时间，可长可短，需结合语境：vente en stund（等一会儿）、om en stund（过一会儿）、for en stund siden（不久前/一段时间前）。中文不宜把它固定对应成某个分钟数。",contexts:[["Vent her en liten stund.","在这里稍等一会儿。","en liten stund 指较短的一段时间。","https://ordbokene.no/bm/stund"],["Vi har ikke sett hverandre på en stund.","我们有一阵子没见面了。","på en stund 表示一段时间，具体多久不明确。","https://ordbokene.no/bm/stund"]]},
  "名词|øyeblikk":{zh:"瞬间；片刻；某个具体时刻",note:"et øyeblikk 指非常短的一刻，也可指某件事发生的具体时点。常见 for øyeblikket（目前/此刻）、om et øyeblikk（马上/一会儿）、i samme øyeblikk（就在同一瞬间）；冠词和介词会影响整组意思。",contexts:[["Vent et øyeblikk!","等一下！","et øyeblikk 在祈使句中表示短暂等待。","https://ordbokene.no/nob/bm/%C3%B8yeblikk"],["For øyeblikket bor hun i Trondheim.","她目前住在特隆赫姆。","for øyeblikket 是固定时间表达，意为“目前/此刻”。","https://ordbokene.no/nob/bm/%C3%B8yeblikk"]]},
  "副词|deretter":{zh:"随后；接着；之后",note:"deretter 用来连接有先后顺序的动作或步骤，相当于“接下来/此后”；常放句首或动词后。它表达顺序，不表示原因，也不一定意味着间隔很久。",contexts:[["Først må du vaske hendene. Deretter kan du lage mat.","先洗手，然后就可以做饭了。","deretter 引出紧接着的下一步；主句倒装，所以动词 kan 在主语 du 前。","https://ordbokene.no/bm/deretter"],["Hun tok toget til Oslo og reiste deretter videre.","她先坐火车到奥斯陆，随后继续上路。","deretter 表示后一动作发生在到奥斯陆之后。","https://ordbokene.no/bm/deretter"]]},
  "形容词|neste":{zh:"下一个；接下来的；下一次/下一段时间的（按顺序或时间）",note:"neste 修饰紧接当前之后的对象：neste stasjon（下一站）、neste uke（下周）、neste gang（下次）。时间搭配具体指哪一周或哪一次由语境决定；不要与表示距离最近的 nærmeste 混淆。",contexts:[["Vi sees neste uke.","我们下周见。","neste uke 是固定时间表达，不加 en。","https://ordbokene.no/bm/neste"],["Gå av på neste holdeplass.","在下一站下车。","neste 修饰 holdeplass，说明按路线顺序紧接着的那一站。","https://ordbokene.no/bm/neste"]]},
  "形容词|øyeblikkelig":{zh:"立即的；紧急的；立刻（作副词用法）",note:"形容词用法表示需要立即处理或马上发生：øyeblikkelig hjelp（紧急救助）；作副词时表示“立刻、马上”：Hun svarte øyeblikkelig（她立刻回答）。修饰名词时按性数变化：øyeblikkelig–øyeblikkelig–øyeblikkelig–øyeblikkelige。",contexts:[["Pasienten trenger øyeblikkelig hjelp.","这名患者需要紧急救助。","øyeblikkelig 修饰 hjelp，表示事情紧急、不能拖延。","https://ordbokene.no/nno/bm/%C3%B8yeblikkelig%7Cstraks"],["Hun svarte øyeblikkelig.","她立刻回答了。","句末副词说明回答发生得很快。","https://ordbokene.no/nno/bm/%C3%B8yeblikkelig%7Cstraks"]]},
  "副词|plutselig":{zh:"突然；忽然；出乎意料地",note:"plutselig 描述某事在没有预料、几乎没有过渡的情况下发生，可置于动词前后或句首。中文依动作翻成“突然/忽然”，无需逐词对译。",contexts:[["Plutselig begynte det å regne.","突然下起雨来。","句首 plutselig 突出天气变化出乎意料；主句动词 begynte 位于第二位。","https://ordbokene.no/bm/plutselig"],["Han sto plutselig foran døra.","他忽然出现在门前。","plutselig 修饰出现的时点，不是说他“站得突然”。","https://ordbokene.no/bm/plutselig"]]},
  "名词|smør":{zh:"黄油（通常作不可数食材）",note:"et smør 是词典所列中性名词词形，但日常泛指/作食材时通常直接用 smør，不加 et：smør på brødet（一片面包上的黄油）、bruke smør（用黄油）。smøret 指语境里那份具体黄油；计量说 en pakke smør（一包黄油）。不定复数很少用于初级日常表达。",contexts:[["Jeg bruker smør i sausen.","我在酱汁里加黄油。","smør 是物质名词，泛指食材时不加冠词。","https://ordbokene.no/bm/sm%C3%B8r"],["Smøret står i kjøleskapet.","黄油放在冰箱里。","smøret 是定指单数，指家里那份具体的黄油。","https://ordbokene.no/bm/sm%C3%B8r"]]},
  "名词|kjeks":{zh:"脆饼；饼干（通常是干、脆、无酵的烘焙食品）",note:"en kjeks 通常指干脆、无酵的烘焙点心，可配奶酪，也可作冰淇淋蛋筒/脆筒；甜味夹心曲奇只是其中一种，不能把所有 kjeks 都译成曲奇。",contexts:[["Server kjeks og ost etter middagen.","晚饭后端上脆饼和奶酪。","搭配中 kjeks 是配奶酪吃的咸/淡味脆饼，不特指甜曲奇。","https://ordbokene.no/nno/search?dict=bm%2Cnn&q=kjeks&scope=eif"],["Barna fikk en kjeks til kaffen.","孩子们喝咖啡时吃了一块饼干。","泛指一块饼干；具体甜咸种类由实际食品决定。","https://ordbokene.no/nno/search?dict=bm%2Cnn&q=kjeks&scope=eif"]]}
};
for (const entry of window.VOCAB_V2.additions) {
  const lemmaKey = entry.word.replace(/^(?:å|en|ei|et)\s+/u, "").trim();
  const correction = V2_REVIEW_BATCH_38[`${entry.pos}|${lemmaKey}`];
  if (correction) Object.assign(entry, correction);
}

// Audited batch 43: conditional language, direction, place, and culture.
const V2_REVIEW_BATCH_43 = {
  "从属连词|hvis": { zh:"如果；假如（引导条件从句）", note:"hvis 引导条件从句，相当于“如果/假如”。从句放句首时，后面的主句仍遵守 V2：Hvis jeg får tid, ringer jeg deg（如果我有时间，我就给你打电话）。句末如果引出愿望，有时相当于“要是……就好了”。不要与文学用法的 hvis（“谁的”）混为一谈。", contexts:[["Hvis de ikke kommer, går jeg.","如果他们不来，我就走。","Bokmålsordboka 例句；hvis 从句在前，主句动词 går 位于第二位。","https://ordbokene.no/bm/hvis"],["Ta med en jakke hvis det blir kaldt.","如果天气变冷，就带件外套。","教学自拟例句；hvis 从句说明带外套的条件，词典用于核对词义。","https://ordbokene.no/bm/hvis"]] },
  "形容词|selvfølgelig": { zh:"理所当然的；当然、自然（副词用法）", note:"作形容词时表示某事理所当然，如 en selvfølgelig plikt（理所当然的义务）；作副词时表示“当然/自然”，如 Selvfølgelig kan jeg hjelpe deg（当然我可以帮你）。先看它修饰名词还是整句话，不要把两个词性混成一个固定中文义。", contexts:[["Selvfølgelig vil jeg gjøre det.","我当然愿意这么做。","词典例句；句首作副词表达肯定回应。","https://ordbokene.no/bm/selvf%C3%B8lgelig"],["Det er en selvfølgelig del av jobben.","这是工作中理所当然的一部分。","教学自拟例句；形容词修饰 del，词典用于核释义。","https://ordbokene.no/bm/selvf%C3%B8lgelig"]] },
  "名词|gruppe": { zh:"组；群体；小组；类别；（音乐）乐队", note:"指因共同特点而构成的一组人、事物或现象；具体可译“小组/类别/群体”。讨论音乐人时也能指乐队。可用 en gruppe 或 ei gruppe；分组常说 dele klassen inn i grupper。", contexts:[["Klassen ble delt inn i grupper.","全班被分成了几个小组。","词典例句；grupper 是不定复数。","https://ordbokene.no/bm/gruppe"],["Vi arbeider i ei gruppe på fire personer.","我们四个人组成一组一起做。","教学自拟例句；ei 与 en 两种阴性/阳性形式均可。","https://ordbokene.no/bm/gruppe"]] },
  "形容词|pen": { zh:"好看的；整洁得体的；（天气）晴好的；礼貌的/令人满意的（依搭配）", note:"pen 不只表示外貌漂亮：pen håndskrift 是字迹工整，pent vær 是晴好天气，oppføre seg pent 是举止得体；修饰人、物或行为时中文要随对象调整。Bokmålsordboka 还列有“可观、相当不错”等用法。", contexts:[["Det blir pent vær i morgen.","明天天气会很好。","词典义项：少云、风小且无降水的好天气；译成“漂亮的天气”不自然。","https://ordbokene.no/bm/pen"],["Hun har veldig pen håndskrift.","她的字写得很工整。","教学自拟例句；pen 描写书写整洁，词典用于核释义。","https://ordbokene.no/bm/pen"]] },
  "形容词|høy": { zh:"高的；数值/程度高的；（声音）高调或音量大的", note:"依所修饰对象判断：高山/高个子用“高”；温度、价格、水平用“高”；høy tone 指音调高，høy musikk 通常是音量大。另有同形中性名词 et høy“干草”，属于独立词条；形容词本身还有“吸毒后兴奋”的口语义，不作为初级主义。", contexts:[["Han er høyere enn henne.","他比她高。","词典例句；描述人的身高。","https://ordbokene.no/bm/h%C3%B8y"],["Kan du skru ned den høye musikken?","你能把音乐声调低一点吗？","教学自拟例句；此处 høy 指声音响，不是音调高。","https://ordbokene.no/bm/h%C3%B8y"]] },
  "名词|byggesett": { zh:"组装套件；拼装套件（按说明把零件组装成成品）", note:"指由零件组成、供人组装的套件；可以是模型，也可以是家具或其他物品，不必然是玩具/飞机模型。说拼装好的成品时，需结合具体物件。中性名词 et byggesett。例句为教学自拟，词典来源仅用于核定构词和意义。", contexts:[["Barnet bygde et byggesett sammen med faren sin.","孩子和爸爸一起把一套拼装模型组装了起来。","教学自拟例句；这里是组装材料套件，具体模型由语境补充。","https://ordbokene.no/nob/search?dict=bm%2Cnn&q=byggesett&scope=eif"]] },
  "名词|internettilgang": { zh:"互联网接入；上网条件/权限", note:"表示能够连接或使用互联网的条件/权限，常作为不可数概念：ha internettilgang（能上网/有网络接入）。复数 internettilganger 只在特指不同接入方式或服务时才可能需要，日常先记单数。教学例句自拟；链接用于核对复合词构成。", contexts:[["Hotellet tilbyr gratis internettilgang.","这家酒店提供免费网络接入。","教学自拟例句；描述是否具备上网条件，不是某个具体网站的访问权限。","https://ordbokene.no/nob/search?dict=bm%2Cnn&q=internettilgang&scope=eif"]] },
  "名词|nett": { zh:"网；网络；互联网（依语境）", note:"et nett 可指绳线编成的网，也可指互相连接的系统/网络；på nettet 通常指“网上/互联网”。别因当前常见网络义就忘记物理网具义；同拼写的形容词 nett 是“整洁/漂亮”等另一词条。", contexts:[["Søke informasjon på nettet.","在网上搜索信息。","词典例句；på nettet 指在互联网上。","https://ordbokene.no/bm/nett"],["Det trådløse nettet virker ikke.","无线网络不能用了。","教学自拟例句；nett 指网络系统，词典用于核释义。","https://ordbokene.no/bm/nett"]] },
  "名词|ende": { zh:"末端；一端；尽头；结束/结尾（依结构）", note:"作名词时，en ende 指物体或空间的端点（tauets ende“绳子的一端”），也可指事件的结束（enden på historien“故事结尾”）。常用 den andre enden（另一端）、ved enden av …（在……尽头）。不要与动词 ende（结束/以……告终）混为一谈。", contexts:[["Hold i enden av tauet.","抓住绳子的一端。","词典例句；enden 指绳子的端点。","https://ordbokene.no/bm/ende"],["Apoteket ligger i den andre enden av gata.","药房在街道的另一头。","教学自拟例句；den andre enden 指另一端，词典用于核释义。","https://ordbokene.no/bm/ende"]] },
  "名词|side": { zh:"侧面；一边；页；方面/立场（依搭配）", note:"side 的具体义看名词搭配：på den andre siden av gata 是“在街对面”，side to 是“第二页”，den økonomiske siden av saken 是“事情的经济方面”。可用 ei side（sida）或 en side（siden）。不要把“边”和“页”当作互不相关的死记义。", contexts:[["Kafeen ligger på den andre siden av gata.","咖啡馆在街对面。","教学自拟例句；på den andre siden av 是表示另一侧的地点短语。","https://ordbokene.no/bm/side"],["Les side to før timen.","上课前读第二页。","Bokmålsordboka 的 sidene i en bok 例句所示用法；side 指书页。","https://ordbokene.no/bm/side"]] },
  "介词|innom": { zh:"顺路短暂停留/拜访；经过并到……里面（依搭配）", note:"常见的 stikke/komme innom + 人/地点表示“顺路进去一下、短暂拜访”，如 stikke innom oss på vei til hytta；也可表示交通工具经停某处，或 innom døra（进到门内/门口一带）。比 inn i 更强调短暂经过/顺访。", contexts:[["De stakk innom oss på vei til hytta.","他们去小木屋的路上顺道来看了我们。","词典例句；stikke innom + 人表示短暂拜访。","https://ordbokene.no/bm/innom"],["Jeg stikker innom apoteket på vei hjem.","我回家路上顺道去一下药房。","教学自拟例句；innom 标出短暂停留，不表示长期进入。","https://ordbokene.no/bm/innom"]] },
  "介词|inni": { zh:"在……里面；进入里面/在内部（依句法）", note:"作介词时 inni + 名词表示“在……里面”，如 inni bilen；作副词时可独立表示“里面/在里面”，如 sette seg inni（坐进去）。和 inn（朝里/进入）相比，inni 常强调处于内部或进入内部；方向需由动词和语境判断。", contexts:[["Sitte inni bilen.","坐在车里。","词典例句片段；inni + bilen 表示处于车内。","https://ordbokene.no/bm/inni"],["Nøklene ligger inni veska.","钥匙在包里面。","教学自拟例句；inni 标明包的内部位置。","https://ordbokene.no/bm/inni"]] },
  "介词|innover": { zh:"向里面/更深处；朝内陆方向（表示朝内的延伸方向）", note:"表示朝某物内部或更远处移动，不是单纯静态的“在里面”：gå innover fjellet 是往山里走；kysten → innover landet 是从海岸朝内陆。它也可作方向副词。", contexts:[["Vi gikk lange turer innover fjellet.","我们常沿着山路往里面走很远。","词典例句；innover 表方向和向内延伸。","https://ordbokene.no/bm/innover"],["Vannet flommet innover markene.","水流漫进了田地深处。","词典例句；表示水朝田地内部涌去。","https://ordbokene.no/bm/innover"]] },
  "副词|nede": { zh:"在低处/下面；楼下；（挪威语境）南边/更靠南；停摆/不运行（依语境）", note:"nede 可指垂直位置低（badet er nede i første etasje“浴室在一楼”）、更靠南的地区（nede i Italia），也可说系统/电脑 ute av drift：datamaskinen er nede（电脑宕机）。一定要看主语与空间参照，不能统一译成“楼下”。", contexts:[["Datamaskinen er nede.","电脑现在无法运行。","词典例句；nede 描述设备暂时停止工作。","https://ordbokene.no/bm/nede"],["Barna venter nede ved inngangen.","孩子们在下面的入口处等着。","教学自拟例句；此处是空间位置，不是设备故障。","https://ordbokene.no/bm/nede"]] },
  "形容词|nærmere": { zh:"更近的；更靠近地；进一步/更深入地；将近、差不多（依结构）", note:"nærmere 是 nær 的比较形式，可作形容词、程度/地点副词，也能作介词用法。nærmere beskjed 是“进一步通知”，undersøke saken nærmere 是“进一步调查”，kom nærmere 是“再靠近些”；nærmere sju meter 是“将近七米”。别笼统译成“更详细”，要看它修饰谁。", contexts:[["Kom nærmere.","再靠近一点。","词典例句；副词表示空间距离更近。","https://ordbokene.no/bm/n%C3%A6rmere"],["Vi skal se nærmere på saken i morgen.","我们明天会进一步查看这件事。","教学自拟例句；se nærmere på 是进一步了解/查看。","https://ordbokene.no/bm/n%C3%A6rmere"]] },
  "介词|oppå": { zh:"在……上面；到……上面/叠放在……上（依静态或移动）", note:"描述静止位置时 oppå =“在……上面”，如 hatten lå oppå hylla；表示把东西放/移动到上面时译“放到……上”。与 på 相比，oppå 特别强调上表面或叠在上面。", contexts:[["Hatten lå oppå hylla.","帽子放在架子上面。","词典例句；静态位置。","https://ordbokene.no/bm/opp%C3%A5"],["Legg nøklene oppå bordet.","把钥匙放到桌面上。","教学自拟例句；legg 表示放置动作，中文用“到”体现方向。","https://ordbokene.no/bm/opp%C3%A5"]] },
  "副词|oppe": { zh:"在高处/上面；楼上；已经起床/还没睡；处于运行状态（依语境）", note:"oppe 不只“在上面”：孩子 klokka ti fortsatt oppe 可指十点还醒着；sola er oppe 是太阳已经升起；mobilnettet er oppe 是网络恢复运行。位置义通常与 nede 对照，先根据主语判断。", contexts:[["Være tidlig oppe om morgenen.","早上很早就起床。","词典例句片段；oppe 表示已离床、起床。","https://ordbokene.no/bm/oppe"],["Katten sitter oppe på taket.","猫坐在屋顶上。","教学自拟例句；这里是高处位置义。","https://ordbokene.no/bm/oppe"]] },
  "形容词|søt": { zh:"甜的；可爱的/讨人喜欢的；亲切温柔的（依对象与语境）", note:"描述味道或气味时是“甜的”（søt kaffe）；描述孩子、动物或故事时是“可爱的/讨人喜欢的”；søt mot alle 表示待人亲切。词典还列出温暖亲昵、舒适愉悦等扩展义。搭配决定中文，不要每次都译成“甜”。", contexts:[["Vinen var litt for søt.","这酒对我来说有点太甜了。","词典例句；味觉义。","https://ordbokene.no/bm/s%C3%B8t"],["For en søt hund!","这只狗真可爱！","词典例句；评价动物讨人喜欢，不涉及味道。","https://ordbokene.no/bm/s%C3%B8t"]] },
  "名词|minusgrad": { zh:"零下摄氏度；低于冰点的温度单位（数值随数量词）", note:"en minusgrad 表示低于零摄氏度一度（−1°C）；fem minusgrader 是零下五度。不要把词头译成固定的“零下的一度”，具体温度看前面的数字。日常天气报告常用复数 minusgrader。教学例句自拟；查询链接用于核对复合词。", contexts:[["Det blir fem minusgrader i natt.","今晚气温会降到零下五度。","教学自拟例句；minusgrader 与数字 five 一起表达温度数值。","https://ordbokene.no/nob/search?dict=bm%2Cnn&q=minusgrad&scope=eif"]] },
  "名词|galleri": { zh:"画廊/艺术展览空间；（剧院、教堂等的）楼座；（小说、电影中的）人物群像", note:"et galleri 的义项不止画廊：可指建筑外的有顶长廊、剧院或教堂的楼座，也可指展出艺术品的场所（中文常译画廊/美术馆），还可比喻作品中的人物群像。此处形态为中性名词 et galleri。", contexts:[["Sitte på galleriet.","坐在楼座上。","词典例句；剧院/教堂的高处座位，不是画廊。","https://ordbokene.no/bm/galleri"],["Vi besøkte et lite galleri i sentrum.","我们参观了市中心的一家小画廊。","教学自拟例句；当地展出艺术作品的场所。","https://ordbokene.no/bm/galleri"]] },
  "名词|nasjonalgalleri": { zh:"国家美术馆；一国主要的公共美术博物馆", note:"透明复合词 nasjonal（国家的）+ galleri（美术馆/展览场所）；可指一个国家重要的公共美术博物馆。不要把普通的 kunstgalleri（画廊）都称为 nasjonalgalleri；具体专名要按国家和历史语境判断。中性名词 et nasjonalgalleri。", contexts:[["Et nasjonalgalleri viser kunst med nasjonal betydning.","国家美术馆展出具有国家重要性的艺术作品。","教学自拟例句；泛指一国重要的公共美术馆，不影射某个当前机构。","https://naob.no/ordbok/nasjonalgalleri"],["Norge har et nasjonalgalleri i Oslo.","挪威在奥斯陆有国家美术馆。","教学自拟例句；专指挪威机构时需结合当代机构名称和历史背景。","https://ordbokene.no/nn/51964"]] },
  "名词|dokketeater": { zh:"木偶戏；木偶剧场/木偶戏演出（依语境）", note:"指用木偶表演故事的戏剧形式，也可指演出或表演场所；句中 se dokketeater 通常是“看木偶戏”，et dokketeater 可指一种剧场/剧种。dokketeater 与 dukketeater 两种拼法都能见到。例句为教学自拟；链接为词典词头检索。", contexts:[["Barna så dokketeater på biblioteket.","孩子们在图书馆看了木偶戏。","教学自拟例句；så dokketeater 指观看演出，不是参观剧场建筑。","https://ordbokene.no/nob/search?dict=bm%2Cnn&q=dokketeater&scope=eif"]] },
  "名词|festival": { zh:"节庆；围绕某一主题定期举办的文化活动/艺术节", note:"词典核心义是通常定期（常为每年）举办、围绕一个主题的大型文化活动。可按主题译音乐节、电影节等，但不能把 festival 简化成任何派对或单次聚会。en festival 是阳性名词。", contexts:[["Mange kjente artister opptrer på årets festival.","许多知名艺人会在今年的艺术节上演出。","词典例句；活动内容按上下文可能是音乐、电影等主题。","https://ordbokene.no/bm/festival"],["Festivalen varer i tre dager.","这个节庆活动持续三天。","教学自拟例句；festivalen 是定指单数，指前文已提到的活动。","https://ordbokene.no/bm/festival"]] },
  "名词|kultur": { zh:"文化；群体的生活方式、价值观与规范；（农业/生物）栽培、培养物", note:"日常多指某一群体的生活方式、观念、习俗和价值观；也可指人的教养/行为规范。农业中是栽培，生物学中是培养出的微生物/培养物。例句要注明是哪一义，不能把抽象文化译成“培养物”。", contexts:[["Jeg møtte en helt annen kultur i den nye bedriften.","我在新公司遇到了一种截然不同的企业文化。","词典例句；指一群体/组织的行为习惯与规范。","https://ordbokene.no/bm/kultur"],["Museet viser fram norsk kultur og historie.","博物馆展示挪威的文化与历史。","教学自拟例句；国家/社会生活方式义。","https://ordbokene.no/bm/kultur"]] },
  "名词|kunst": { zh:"艺术；艺术作品；技艺/本领；（复数 kunster）花招/伎俩（依语境）", note:"kunst 可指艺术创作及其作品，也可指通过练习掌握的技艺/本领：kunsten å gå på ski（滑雪的技巧）。复数 kunster 在某些语境可指花招/伎俩。它不是只等于视觉艺术；需看搭配。", contexts:[["Det er ingen kunst å koke kaffe.","煮咖啡不是什么难事。","词典固定表达 det er ingen kunst，意为“不难/不成问题”，不是“没有艺术”。","https://ordbokene.no/bm/kunst"],["Vi så moderne kunst på museet.","我们在博物馆看了现代艺术作品。","教学自拟例句；此处是艺术创作/作品义。","https://ordbokene.no/bm/kunst"]] }
};
for (const entry of window.VOCAB_V2.additions) {
  const lemmaKey = entry.word.replace(/^(?:å|en|ei|et|ei\/en|en\/ei)\s+/u, "").trim();
  const correction = V2_REVIEW_BATCH_43[`${entry.pos}|${lemmaKey}`];
  if (correction) {
    Object.assign(entry, correction);
    entry.review = {
      fields: ["词性/词形", "中文释义", "例句语境", "例句译文"],
      source: "Bokmålsordboka / 逐条语义复核",
      sourceUrl: `https://ordbokene.no/search?dict=bm&q=${encodeURIComponent(lemmaKey)}&scope=eif`,
      checkedOn: "2026-09-26"
    };
  }
}
// Manually audited batch 42: common place, kitchen and food vocabulary.
const V2_REVIEW_BATCH_42 = {
  "名词|kjøledisk": {zh:"冷藏展示柜；商店陈列冷藏食品的冷柜",note:"由 kjøle-（冷藏）+ disk（柜台/展示台）组成，通常指超市陈列乳制品、肉类等的冷藏柜；不是家用冰箱 kjøleskap。",contexts:[["Melka står i kjøledisken ved inngangen.","牛奶放在入口旁的冷藏展示柜里。","i kjøledisken 指商店里的冷藏展示柜；句子没有说牛奶在家用冰箱里。","https://ordbokene.no/nob/search?dict=bm%2Cnn&q=kj%C3%B8ledisk&scope=eif"],["Butikken har en ny kjøledisk.","商店新添了一台冷藏展示柜。","en kjøledisk 是不定单数；具体设备由 køledisk 表示，不译作家用冰箱。","https://ordbokene.no/nob/search?dict=bm%2Cnn&q=kj%C3%B8ledisk&scope=eif"]]},
  "名词|kirke": {zh:"教堂；基督教教会/团体（依语境）",note:"kirke 可指举行基督教礼拜的建筑，也可指基督教团体：ei kirke / en kirke 都可用；本批保留常见阴性词形 ei kirke、kirka。不要泛化为所有宗教的寺庙。",contexts:[["Det står ei gammel kirke ved torget.","广场旁有一座古老的教堂。","kirke 在此指建筑；ei 是阴性不定冠词。","https://ordbokene.no/bm/kirke"],["Kirken ligger nær sentrum.","教堂位于市中心附近。","kirken 是阳性定指单数形式；Bokmål 也允许 kirka。","https://ordbokene.no/bm/kirke"],["Prestene i Den norske kirke.","挪威教会的牧师们。","词典例句片段；Den norske kirke 指教会组织，不是某一栋建筑。","https://ordbokene.no/bm/kirke"]]},
  "名词|park": {zh:"公园；（复合词中）特定活动或设施所在区域",note:"日常义是有绿化、供人休憩的公园；park 也常出现在复合词中表示某类区域，如 dyrepark（动物园/野生动物园）、nasjonalpark（国家公园）。本卡先学日常公园义。",contexts:[["Vi spiste lunsj i parken.","我们在公园里吃了午饭。","i parken 是地点短语，说明吃午饭的地点。","https://ordbokene.no/bm/park"],["Det finnes flere parker i sentrum.","市中心有好几个公园。","parker 是不定复数；词典还列出 park 在复合词里的其他区域义。","https://ordbokene.no/bm/park"],["Byen har mange fine parker.","城里有很多漂亮的公园。","词典例句；parker 是不定复数。","https://ordbokene.no/bm/park"]]},
  "名词|gate": {zh:"街；街道（城镇中通常两侧有房屋的道路）",note:"常见义是城镇中的街道；走过、横穿街道时也可按中文习惯说“过马路”。不等于高速公路；词典另列同形英语借词 gate（机场登机口），本卡不是那个词。可用 ei gate/gata，也可用 en gate/gaten。",contexts:[["Skolen ligger i en rolig gate.","学校位于一条安静的街道上。","gate 指城镇街道；en rolig 是阳性不定单数修饰形式。","https://ordbokene.no/bm/gate"],["Barna går over gata sammen.","孩子们一起过马路。","over gata 字面是“穿过这条街”，中文自然说“过马路”；gata 是阴性定指单数。","https://ordbokene.no/bm/gate"],["Butikken ligger rett over gata.","商店就在街对面。","词典例句；rett over gata 是“就在街对面”。","https://ordbokene.no/bm/gate"]]},
  "名词|gågate": {zh:"步行街；禁止或限制机动车通行、以行人为主的街道",note:"由 gå（步行）+ gate（街道）组成；词典定义允许车辆通行“完全或部分受限”，因此不宜绝对说所有车辆都禁止进入。阴性和阳性形式都可用。",contexts:[["Butikkene i gågata stenger klokka seks.","步行街上的商店六点关门。","gågata 是阴性定指单数，介词 i 表示地点。","https://ordbokene.no/bm/g%C3%A5gate"],["Vi møtes ved inngangen til gågata.","我们在步行街入口处碰面。","til gågata 标出入口所在的方向/位置。","https://ordbokene.no/bm/g%C3%A5gate"]]},
  "名词|katedral": {zh:"主教座堂；与主教相联系的主要教堂",note:"比一般 kirke（教堂）具体：katedral 是与主教相联系的主要教堂，也可用于形容宏伟得像教堂的自然或人工空间。不要把所有教堂都叫 katedral。",contexts:[["Turistene besøkte katedralen i sentrum.","游客参观了市中心的主教座堂。","katedralen 是定指单数，指语境中特定的主教座堂。","https://ordbokene.no/bm/katedral"],["Nidarosdomen er en kjent katedral i Trondheim.","尼达罗斯大教堂是特隆赫姆一座著名的主教座堂。","katedral 比一般 kirke 含义更具体。","https://ordbokene.no/bm/katedral"],["Nidarosdomen er en katedral.","尼达罗斯大教堂是一座主教座堂。","词典例句；en katedral 为阳性不定单数。","https://ordbokene.no/bm/katedral"]]},
  "名词|katt": {zh:"猫；家猫（也可泛指猫科动物）",note:"日常最常指家猫；上下文也可泛指猫科动物。定指单数 katten 可指前文提到的那只猫；不能只凭词形判断它是公猫还是母猫。",contexts:[["Naboen har en svart katt.","邻居养了一只黑猫。","en svart katt 是阳性不定单数。","https://ordbokene.no/bm/katt"],["Katten sover på sofaen.","那只猫在沙发上睡觉。","katten 是定指单数；中文是否加“那只”取决于上下文。","https://ordbokene.no/bm/katt"],["Katten lå under ovnen og malte.","猫躺在炉子下面，发出呼噜声。","词典例句；male 在猫的语境里是发出呼噜声，不是“涂颜色”。","https://ordbokene.no/bm/katt"]]},
  "名词|bytur": {zh:"进城/到城里一趟；在城里的出行或游逛",note:"指到城里去一趟或在城里出行；可以是办事、游逛或探访，不必然是购物，也不一定是观光旅游。由 by（城）+ tur（出行）组成。",contexts:[["Vi drar på bytur på lørdag.","我们周六进城一趟。","på bytur 表示到城里去一趟；句子没有说明是购物还是办事。","https://ordbokene.no/bm/bytur"],["Byturen tok hele ettermiddagen.","这趟进城花了整个下午。","bytur 指到城里去一趟；原句没有购物信息，所以不译成“逛街”。","https://ordbokene.no/bm/bytur"],["Hun var med mormor på bytur.","她跟外婆进城了一趟。","词典例句；mormor 特指外婆，句子只说明同行进城，并没有限定活动内容。","https://ordbokene.no/bm/bytur"]]},
  "名词|tur": {zh:"出行、散步或短途旅行；轮到的次序；一趟/一轮（依搭配）",note:"搭配决定常见意思：gå en tur（散步）、ta en tur til byen（进城一趟）、på tur med skolen（随学校外出）；det er min tur（轮到我）。另有同形名词 tur 表示“运气”，不属于本卡主要出行义。",contexts:[["Vi går en tur langs elva etter middag.","晚饭后我们沿着河边散步。","gå en tur 是“散步”；此处不是旅行。","https://ordbokene.no/bm/tur"],["Barna skal på tur med skolen.","孩子们要和学校一起外出活动。","på tur 可指郊游或外出活动。","https://ordbokene.no/bm/tur"],["Det er min tur nå!","现在轮到我了！","词典例句；tur 在此指顺序中的轮次，而不是出行。","https://ordbokene.no/bm/tur"]]},
  "名词|ovn": {zh:"炉具；烤箱/烤炉；取暖炉（依复合词和用途）",note:"泛指加热、烹煮或烘烤用的炉具：stekeovn 是烤箱，vedovn 是柴炉，panelovn 是电暖炉。komfyr 通常指厨房炉灶，常兼有炉面和烤箱；两词相关但不能任意互换。",contexts:[["Sett pizzaen i ovnen på 220 grader.","把披萨放进烤箱，温度设为220度。","在烘烤食物的语境中，ovnen 指烤箱。","https://ordbokene.no/bm/ovn"],["Det står en gammel vedovn i stua.","客厅里有一台老式柴炉。","vedovn 是取暖/烧柴的炉子；oven 本身不只指烤箱。","https://ordbokene.no/bm/ovn"]]},
  "名词|bagett": {zh:"法棍；法式长棍面包",note:"日常义是细长的面包；Bokmålsordboka 也列有宝石的长方形切割义，但初级日常语境通常指面包。bagett 是 Bokmål 规范拼法之一。",contexts:[["Jeg kjøper en bagett til lunsj.","我买一条法棍当午餐。","bagett 是阳性名词；语境是食物。","https://ordbokene.no/bm/bagett"],["Bagettene ligger ved siden av brødet.","法棍放在面包旁边。","bagettene 是定指复数；本句指面包，不是宝石切工。","https://ordbokene.no/bm/bagett"]]},
  "名词|bolle": {word:"en bolle",zh:"碗；小圆面包/圆形烘焙食品（依搭配）",forms:["en bolle","bollen","boller","bollene"],labels:["不定单数","定指单数","不定复数","定指复数"],note:"Bokmålsordboka 将本词列为阳性：en bolle、bollen；不定形式应写 en，不写 ei。词义由搭配区分：圆而较深的容器是“碗”，小圆烘焙食品是“小圆面包”；kanelbolle 特指肉桂小圆面包。",contexts:[["Jeg kjøper en kanelbolle til kaffen.","我买一个肉桂小圆面包配咖啡。","kanelbolle 是一种小圆烘焙食品；本词 bolle 用阳性冠词 en。","https://ordbokene.no/bm/bolle"],["Hun spiser suppe fra en bolle.","她用碗喝汤。","en bolle 在此指圆而较深的容器；Bokmålsordboka 将此名词列为阳性。","https://ordbokene.no/bm/bolle"]]},
  "名词|gaffel": {zh:"叉子；餐叉；（器具中）叉状分叉部分",note:"餐桌语境是叉子/餐叉；也可指具有叉状分叉的器具部分，如自行车前叉。初学时先掌握餐具义。",contexts:[["Vi trenger en gaffel til.","我们还需要一把叉子。","en gaffel 是阳性不定单数。","https://ordbokene.no/bm/gaffel"],["Gaflene ligger i skuffen.","叉子在抽屉里。","gaflene 是定指复数。","https://ordbokene.no/bm/gaffel"]]},
  "名词|glass": {zh:"玻璃（材料）；玻璃杯；一杯饮品（依搭配）",note:"et glass 可指玻璃材料或玻璃杯；用作量词时表示一杯/一份饮品，如 et glass vann。常见短语 ta seg et glass 可指喝一杯（常为酒精饮品），不是玻璃材料。复数不定式 glass 与单数同形。",contexts:[["Kan jeg få et glass vann?","能给我一杯水吗？","et glass vann 中 glass 指容器/一杯的量，不是玻璃材料。","https://ordbokene.no/bm/glass"],["Glasset falt på gulvet, men det knuste ikke.","玻璃杯掉到地上了，但没有摔碎。","glasset 是定指单数，knuste 与后面的玻璃杯呼应。","https://ordbokene.no/bm/glass"]]},
  "名词|is": {zh:"冰；冰块/冰层；冰淇淋或冰棒（依语境）",note:"is 是阳性名词，可指冻结的水、冰块、湖河冰层，也可指冰淇淋/冰棒：spise en is 是“吃一个冰淇淋/冰棒”；天气或道路语境则常是冰。",contexts:[["Barna kjøper en is etter skolen.","孩子们放学后买一个冰淇淋。","食物语境中的 en is 指一份冰淇淋或冰棒。","https://ordbokene.no/bm/is"],["Det er glatt fordi det ligger is på veien.","路面有冰，所以很滑。","is 在道路和天气语境中指冻结的水/冰层。","https://ordbokene.no/bm/is"],["Vannet frøs til is.","水结成了冰。","词典例句；frøs til is 表示冻结成冰。","https://ordbokene.no/bm/is"]]},
  "名词|kake": {zh:"蛋糕；糕点；一份/一只蛋糕（依搭配）",note:"可指一只蛋糕或各类烘焙糕点；表达一块时常说 et kakestykke。常用 ei/en kake、kaka/kaken；本条采用阴性词形。",contexts:[["Jeg baker en kake til fødselsdagen.","我为生日烤一只蛋糕。","一只完整蛋糕用 en kake；Bokmål 也可用 ei kake。","https://ordbokene.no/bm/kake"],["Kaka står på bordet.","蛋糕放在桌子上。","kaka 是阴性定指单数形式；若采用阳性形式可说 kaken。","https://ordbokene.no/bm/kake"]]},
  "名词|kjøkkenbenk": {zh:"厨房操作台；厨房台面",note:"固定安装在厨房里供备菜、放置物品等使用的工作台面；不等于可移动的凳子/长凳（benk 的其他义）。",contexts:[["Brødet ligger på kjøkkenbenken.","面包放在厨房台面上。","på kjøkkenbenken 表示在固定厨房工作台面上。","https://ordbokene.no/bm/kj%C3%B8kkenbenk"],["Jeg tørker av kjøkkenbenken etter matlaging.","做完饭后我擦拭厨房台面。","tørke av 表示擦拭表面；此处不是擦厨房长凳。","https://ordbokene.no/bm/kj%C3%B8kkenbenk"]]},
  "名词|kniv": {zh:"刀；餐刀；机器中的刀刃（依用途）",note:"核心义是带柄和刀刃、用于切割的工具；餐桌上可指餐刀，机器中也可指切割部件。日常问 en kniv 时，具体是餐刀还是厨房刀由场景判断。",contexts:[["Kan jeg få en kniv?","可以给我一把刀吗？","请求不特定的一把刀；若在餐桌上通常理解为餐刀。","https://ordbokene.no/bm/kniv"],["Kniven ligger ved siden av tallerkenen.","餐刀放在盘子旁边。","餐桌语境使 kniven 具体指餐刀。","https://ordbokene.no/bm/kniv"]]},
  "动词|koke": {zh:"煮；烧开；（水或其他液体）沸腾",note:"可作不及物动词表示液体达到沸点（vannet koker），也可带宾语表示把食物煮熟（koke poteter）或使液体沸腾（koke vann）。对象和句法决定中文是“沸腾”还是“煮”。",contexts:[["Jeg koker egg til frokost.","我煮鸡蛋当早餐。","koke + 食物表示通过煮制来准备食物。","https://ordbokene.no/bm/koke"],["Vannet kokte etter noen minutter.","几分钟后水烧开了。","水作主语且没有宾语，kokte 表示水沸腾/烧开。","https://ordbokene.no/bm/koke"],["Potetene kokte for lenge.","土豆煮得太久了。","词典例句；kokte 描写土豆在沸水中煮，for lenge 表示时间过长。","https://ordbokene.no/bm/koke"]]},
  "名词|komfyr": {zh:"炉灶；厨房烹饪用的灶具（常含炉面和烤箱）",note:"厨房里用于加热和烹饪的炉具，常同时有炉面（koketopp）和烤箱（stekeovn）；不同型号配置不完全相同。和泛指取暖、烘烤设备的 ovn 区分。",contexts:[["Suppa står på komfyren.","汤锅放在炉灶上。","på komfyren 表示锅放在炉灶上加热；中文补出“锅”使表达自然。","https://ordbokene.no/bm/komfyr"],["Vi har en ny komfyr på kjøkkenet.","我们厨房里有一台新炉灶。","en komfyr 是阳性不定单数，指厨房烹饪设备。","https://ordbokene.no/bm/komfyr"]]},
  "名词|kopp": {zh:"杯子；一杯的量（常用于饮品或计量）",note:"核心义是带把手的小型深口饮用容器；也可指杯中所盛的量：en kopp kaffe（一杯咖啡）、to kopper sukker（两杯糖）。注意 kopp（杯子）与 bolle（碗）的形状和用途差异。",contexts:[["Vil du ha en kopp te?","你想来一杯茶吗？","en kopp + 饮品表示一杯……；kopp 也指杯子本身。","https://ordbokene.no/bm/kopp"],["Koppene står i skapet.","杯子放在橱柜里。","koppene 是定指复数，指语境中那些杯子。","https://ordbokene.no/bm/kopp"]]},
  "名词|lunsj": {zh:"午餐；早餐与晚餐之间的一餐",note:"指早餐和晚餐之间的一餐；通常译午餐/午饭，但定义不要求一定在正午吃。spise lunsj 泛指吃午餐，lunsjen 可指某一顿具体的午餐。",contexts:[["Vi spiser lunsj klokka tolv.","我们十二点吃午饭。","lunsj 是早餐与晚餐之间的一餐；此例说明具体时间为十二点。","https://ordbokene.no/bm/lunsj"],["Lunsjen i dag var god.","今天这顿午餐很好吃。","lunsjen 是定指单数，指今天这顿具体的午餐。","https://ordbokene.no/bm/lunsj"]]},
  "名词|spisebord": {zh:"餐桌；吃饭用的桌子",note:"由 spise（吃）+ bord（桌子）构成，指用餐时坐在旁边吃饭的桌子。词形中性：et spisebord；不定复数与单数同形 spisebord，定指复数 spisebordene。",contexts:[["Vi dekker spisebordet før middagen.","晚饭前我们摆好餐桌。","dekke bordet 表示摆餐具、准备好餐桌。","https://ordbokene.no/nob/search?dict=bm%2Cnn&q=spisebord&scope=eif"],["Hele familien sitter rundt spisebordet.","全家人围坐在餐桌旁。","rundt spisebordet 描写围桌就坐。","https://ordbokene.no/nob/search?dict=bm%2Cnn&q=spisebord&scope=eif"]]},
  "名词|tallerken": {zh:"盘子；一盘的量/份（依搭配）",note:"通常指盛一人份食物的较平餐盘；也可借指一盘所盛的食物：en tallerken suppe（一盘/一份汤）。本条词形是阳性 en tallerken。",contexts:[["Jeg setter tallerkenen på bordet.","我把盘子放在桌上。","tallerkenen 是定指单数，指具体那只盘子。","https://ordbokene.no/bm/59713"],["Vi trenger flere tallerkener.","我们还需要几个盘子。","flere 后接不定复数 tallerkener。","https://ordbokene.no/bm/59713"],["En tallerken suppe.","一盘（或一份）汤。","词典搭配片段，不是完整句子；tallerken 在此指盘中食物的份量。","https://ordbokene.no/bm/59713"]]},
  "代词|en": {zh:"泛指一个人；人们；（面向一般人的）你",note:"泛指代词 en 指不特定的一般人，不表示某个男性：En lærer mye av å øve（人们能从练习中学到很多）。也可用作泛指的“你”；正式书面语常用 man。注意它不同于名词前的阳性不定冠词 en。",contexts:[["En lærer mye av å snakke med folk.","人们能从与他人交谈中学到很多。","句首 en 是泛指代词，意思接近“人们/一个人”，不是“一名男性”。","https://ordbokene.no/nob/search?dict=bm%2Cnn&q=en&scope=eif"],["Når en bor i Norge, bruker en ofte buss.","住在挪威时，人们常常坐公交。","从属句中的 en 泛指一般人；主句也用 en 回指同一泛指主体。","https://ordbokene.no/nob/search?dict=bm%2Cnn&q=en&scope=eif"]]}
};
for (const entry of window.VOCAB_V2.additions) {
  const lemmaKey = entry.word.replace(/^(?:å|en|ei|et)\s+/u, "").trim().toLocaleLowerCase("nb-NO");
  const correction = V2_REVIEW_BATCH_42[`${entry.pos}|${lemmaKey}`];
  if (correction) Object.assign(entry, correction);
}
const V2_REVIEW_BATCH_39 = {
  "名词|skive":{zh:"一片；薄片；切片（依切下的东西）",note:"skive 指从较大整体切下的一片/薄片，常见 en skive brød（一片面包）、ei skive ost（一片奶酪）；名词可用阳性 en 或阴性 ei。不要仅背“一片”，要看后接材料。",contexts:[["Kan jeg få en skive ost til?","我能再要一片奶酪吗？","skive ost 是“一片奶酪”；ost 不加冠词，说明切片的材料。","https://ordbokene.no/bm/skive"],["Hun la to skiver brød i brødristeren.","她把两片面包放进了烤面包机。","skiver 是不定复数；这里是两片面包，而不是两条面包。","https://ordbokene.no/bm/skive"]]},
  "动词|forsyne":{zh:"供应；为……提供；（反身）自取食物/饮料",note:"forsyne noen med noe 表示“给某人供应某物”；forsyne seg med mat/drikke 或直接说 forsyn deg 是自己取食物/饮料。反身结构中的 seg 指自己动手取用，不是“供给自己”。",contexts:[["Kommunen forsyner byen med rent vann.","市政部门为这座城市供应干净的水。","forsyne byen med + 物品：byen 是接收对象，rent vann 是供应内容。","https://ordbokene.no/bm/forsyne"],["Det står suppe på bordet, så forsyn deg.","桌上有汤，请自便盛用。","forsyn deg 是礼貌邀请对方自己取用食物。","https://ordbokene.no/bm/forsyne"]]},
  "名词|grøt":{zh:"粥；谷物/面粉煮成的稠食；糊状物（依语境）",note:"en grøt 通常是用谷物、面粉或水果加水/牛奶煮成的稠食，如 havregrøt（燕麦粥）；也可泛指稠软的糊状物。日常泛指食物时常直接说 grøt，不必加冠词。固定表达 gå rundt grøten 是“绕弯子、不直奔主题”，不要照字面译。",contexts:[["Jeg spiser havregrøt til frokost.","我早餐吃燕麦粥。","havregrøt 是燕麦煮成的粥；grøt 是菜名，不是泛指任何糊状物。","https://ordbokene.no/bm/gr%C3%B8t"],["Vi går rundt grøten og får aldri sagt hva vi mener.","我们总是绕弯子，始终没把想说的话说出来。","词典固定表达 gå rundt grøten 比喻不直截了当地说重点。","https://ordbokene.no/bm/g%C3%A5%20rundt%20gr%C3%B8ten"]]},
  "名词|matrett":{zh:"一道菜；一种已备好、可以上桌的菜肴",note:"en matrett 是做好并可供上桌的一道菜/一种菜式；不等于整顿饭（et måltid），也不必然代表某个国家的传统菜。典型搭配 prøve nye matretter（尝试新菜）。",contexts:[["Prøve nye matretter.","尝尝新的菜式。","Bokmålsordboka 例句片段；matretter 是 matrett 的不定复数。","https://ordbokene.no/nob/search?dict=bm&q=matrett&scope=eif"],["Fiskesuppe er en populær norsk matrett.","鱼汤是一道受欢迎的挪威菜。","matrett 指一类具体菜肴；整餐仍叫 måltid。"]]},
  "动词|servere":{zh:"上（食物/饮料）；供应；招待；讲述/抛出（故事等，依宾语）",note:"餐饮语境中 servere 是把食物或饮料端给客人，或表示餐馆菜单供应什么；也可引申为讲述/奉上故事。Bokmålsordboka 的常规义不包括网球“发球”，网球动作通常用 serve。",contexts:[["Restauranten serverer indisk mat.","这家餐厅供应印度菜。","词典例句；表示菜单上有/供应某类食物。","https://ordbokene.no/nob/servere"],["Kelneren serverte dem raskt.","服务员很快就给他们上了菜。","词典例句；serverte 是过去时，dem 是接受服务的客人；已替换原来的网球误例。","https://ordbokene.no/nob/servere"]]},
  "名词|torsk":{zh:"鳕鱼；鳕鱼肉（菜肴/食材语境）",note:"en torsk 是鳕鱼这种鱼；谈捕到或看到一条鱼时是可数鱼只，谈晚餐、菜单或配菜时可指鳕鱼肉。鱼类分类上是鳕科鱼类，日常中文通常直接说鳕鱼。",contexts:[["Vi spiser kokt torsk med poteter i dag.","我们今天吃水煮鳕鱼配土豆。","菜单/食物语境，torsk 指鳕鱼肉这道食材。","https://ordbokene.no/bm/torsk"],["Fiskeren fikk tre store torsker.","渔夫捕到了三条大鳕鱼。","有数量词 tre 时，torsker 明确指三条鱼。","https://ordbokene.no/bm/torsk"]]},
  "名词|verden":{zh:"世界；人类共同生活的地球；领域/圈子（依语境）",note:"en verden 可指宇宙、地球及其人类社会、某个专业/文化圈，也能比喻想象中的世界或大量事物。hele verden 通常表示“全世界”；ut i verden 是走向外面的世界；en verden av muligheter 是“无数可能”。",contexts:[["Folk fra hele verden besøker Norge om sommeren.","夏天，来自世界各地的人会来挪威旅游。","hele verden 指世界各地/全世界，不是“整个人类世界”抽象概念。","https://ordbokene.no/bm/VERDEN"],["Hun drømmer om å reise ut i verden.","她梦想着去外面的世界旅行。","ut i verden 是走出熟悉环境、去外面闯荡/旅行。","https://ordbokene.no/bm/VERDEN"]]},
  "动词|skje":{zh:"发生；出现（指事件发生）",note:"å skje 表示某件事发生/出现，过去式不规则：skjer–skjedde–har skjedd。常说 Hva skjer?（发生什么事？/最近怎么样？）、Det skjedde i går（那件事昨天发生了）。它一般不表示一个人主动“进行”某项活动。",contexts:[["Hva skjer?","发生什么事了？/最近怎么样？","词典例句；可问眼下发生什么，也可作口语问候。","https://ordbokene.no/bm/skje"],["I går skjedde det noe rart.","昨天发生了一件奇怪的事。","det 是形式主语，真正发生的事情由 noe rart 表示。","https://ordbokene.no/bm/skje"]]},
  "动词|passe":{word:"å passe",zh:"适合；合身；照看；留意；传球（依句型）",note:"常见义由结构决定：passe til + 人/用途=适合；klær/sko passer=衣服/鞋合身；passe barn/hus=照看孩子/房子；passe på=留意、看护；球类运动中 passe ballen=传球。必须和后接成分一起学。",contexts:[["Skoene passer ypperlig.","这双鞋非常合脚。","主语是 skoene 时，passe 表示尺寸合适/合脚。","https://ordbokene.no/nob/bm/passe"],["Kan du passe barna mens jeg handler?","我去购物时，你能帮忙照看孩子吗？","passe + 人/动物可表示照看；不是“适合孩子”。","https://ordbokene.no/nob/bm/passe"]]},
  "名词|passord":{zh:"密码；口令（用于验证身份或访问账户/系统）",note:"et passord 是访问账户、设备或系统时用于验证身份的秘密词或字符组合；常说 skrive inn passordet（输入密码）、endre/bytte passord（更改密码）。一般不指门上的数字门禁码（kode/dørkode）。",contexts:[["Jeg har glemt passordet til e-posten min.","我忘了邮箱密码。","passordet 是定指单数，指这一个邮箱账户的登录密码。","https://ordbokene.no/bm/passord"],["Du bør velge et sterkt passord.","你应该设置一个强密码。","sterkt passord 指不易被猜到的密码，不是声音/力度上的“强”。","https://ordbokene.no/bm/passord"]]},
  "形容词|skadet":{zh:"受伤的；受损的；损坏的（依对象）",note:"修饰人或动物时通常译“受伤的”；修饰物品/建筑时译“受损、损坏的”。它是 skade 的过去分词作形容词，注意与动词 å skade（伤害、损坏）区分。",contexts:[["En skadet syklist fikk hjelp av ambulansepersonellet.","一名受伤的骑车人得到了救护人员的帮助。","修饰人，表示身体受伤。","https://ordbokene.no/nob/bm/skade"],["De fant et skadet dyr ved veien.","他们在路边发现了一只受伤的动物。","修饰动物，同样是身体受伤；用于物体时才译“损坏”。","https://ordbokene.no/nob/bm/skade"]]},
  "名词|tomat":{zh:"番茄；西红柿（植物学为果实，烹饪中常作蔬菜）",note:"en tomat 指番茄这种可食用的红色果实；日常烹饪、沙拉和购物中通常把它当作蔬菜使用。词典还列有番茄植株以及 tomat 表示番茄酱的特定搭配义。",contexts:[["Lage salat med agurk, paprika og tomat.","用黄瓜、甜椒和番茄做沙拉。","词典搭配片段；这里 tomat 是沙拉配料。","https://ordbokene.no/bm/TOMAT"],["Makrell i tomat.","番茄酱鲭鱼。","固定食品名称中的 i tomat 指番茄酱，不是鲭鱼在番茄里面。","https://ordbokene.no/bm/TOMAT"]]},
  "限定词|flere":{zh:"更多；几个/若干；另外一些（修饰可数名词复数）",note:"flere 是数量限定词，可表示“多于一个/若干”，也可在比较中表示“更多”，或表示“再来一些”。flere ganger 是“好几次”，不是“更快/很快”；flere enn ... 是“比……更多”。修饰可数名词复数，不能代替不可数的 mer。",contexts:[["Det har hendt flere ganger.","这种事已经发生过好几次了。","词典例句；flere 修饰 ganger，表示次数超过一次。","https://ordbokene.no/nno/search?dict=bm%2Cnn&q=flere&scope=eif"],["Jeg trenger flere ark.","我还需要几张纸。","flere 表示额外再要一些可数的纸张。","https://ordbokene.no/nno/search?dict=bm%2Cnn&q=flere&scope=eif"]]},
  "形容词|ekstra":{zh:"额外的；另外的；特别的（依位置和搭配）",note:"修饰名词时表示“额外/另加”：en ekstra dag（一整天额外时间）；作副词时可表示“特别、格外”或“额外地”：jobbe ekstra（额外工作/加班）。本形不随名词性数变化。",contexts:[["Ta en ekstra kopi.","再多复印一份。","ekstra 修饰 kopi，表示额外增加一份。","https://ordbokene.no/bm/ekstra"],["Det krever ekstra påpasselighet.","这需要格外谨慎。","extra作程度副词/修饰语，强调谨慎程度要更高。","https://ordbokene.no/bm/ekstra"]]},
  "名词|del":{zh:"部分；组成部分；份额；参与（依搭配）",note:"en del 可指整体的一部分、某个组成部分、应得份额或参与其中；ta del i 是“参加/参与”。固定数量表达 en del + 复数/不可数名词又表示“相当多/不少”，如 en del arbeid（不少工作）；要和独立名词“一个部分”区分。",contexts:[["En del av familien bor fortsatt i Kina.","家里有一部分人仍然住在中国。","en del av + 整体，指出其中一部分成员。","https://ordbokene.no/nob/bm%2Cnn/del"],["Det kom en del mennesker.","来了不少人。","固定数量表达 en del + 名词复数=不少/相当多，不是“一个部分的人”。","https://ordbokene.no/nob/bm%2Cnn/del"]]},
  "名词|stykke":{zh:"一块；一段；一件/一篇作品；个（依后接词）",note:"et stykke 可指整体切/断下来的一块、一段距离/时间、一件艺术作品或一篇文章。常见量词结构 et stykke kake（一块蛋糕）；gå et stykke（走一段路）；et musikkstykke（一首/一段音乐作品）。",contexts:[["Vil du ha et stykke kake?","你想来一块蛋糕吗？","et stykke + 食物表示一块/一份。","https://ordbokene.no/bm/stykke"],["Hun fulgte meg et stykke før hun snudde.","她陪我走了一段路，然后转身回去了。","这里 et stykke 指一段距离，不是某件物品。","https://ordbokene.no/bm/stykke"]]},
  "名词|masse":{zh:"物质；团块；（物理）质量；群众；大量（依词性/结构）",note:"名词 en masse 的核心义包括无定形物质/团块、物理学的质量，以及定指 massene（广大群众）。口语 masse folk/mye masse 等数量表达常表示“很多”，但句中 masse 作量词性用法时不等于在说一团物质；注意冠词和后接名词。",contexts:[["En glødende masse.","一团炽热的物质。","词典例项；masse 指一团物质。","https://ordbokene.no/bm/37282"],["Lederne har liten kontakt med massene.","领导人与广大群众接触不多。","massene 是定指复数，指广大民众。","https://ordbokene.no/bm/37282"]]},
  "形容词|mye":{zh:"很多；大量；很、非常（依句法）",note:"Bokmålsordboka 将 mye 列为形容词，但它还能独立作代词和副词：mye vann（很多水）；jeg har mye å gjøre（我有很多事要做）；det regner mye（雨下得很大）；mye bedre（好得多）。比较级 mer，最高级 mest；可数复数名词前通常用 mange。",contexts:[["Mye arbeid gjenstår.","还有很多工作没做完。","mye 修饰不可数名词 arbeid。","https://ordbokene.no/nno/search?dict=bm%2Cnn&q=mye&scope=eif"],["Det varierer mye.","情况变化很大。","mye 作副词，修饰动词 varierer，表示程度/幅度大。","https://ordbokene.no/nno/search?dict=bm%2Cnn&q=mye&scope=eif"]]},
  "名词|rest":{zh:"剩下的部分；余量；剩菜（依语境）",note:"en rest 指整体中剩余的那部分；食物语境中可指剩菜/剩饭。resten av + 名词=……剩下的部分，如 resten av boka（书的剩余部分）；rengjørings-/material语境也可指余量。",contexts:[["Vi spiser resten av suppa til lunsj.","我们午餐把剩下的汤吃掉。","resten av suppa 是汤剩下的部分。","https://ordbokene.no/bm/rest"],["Det ligger noen rester i kjøleskapet.","冰箱里放着一些剩菜。","复数 rester 在食物场景自然译“剩菜”。","https://ordbokene.no/bm/rest"]]},
  "名词|par":{zh:"一对；一双；一对伴侣；几个/两三个（依搭配）",note:"et par 可指相配的两个物品/人，也可放在复数名词前作约数：et par hansker（一双手套）、et par dager（两三天/几天）。约数用法通常接近“两三个”，不保证精确等于两个；语境和所搭配对象决定译法。",contexts:[["Jeg trenger et par varme hansker.","我需要一双保暖手套。","物品成双搭配时，et par 表示一双。","https://ordbokene.no/bm/par"],["Vi blir her et par dager til.","我们还会在这里待两三天。","et par + 复数时间单位是近似数量表达，不一定严格两天。","https://ordbokene.no/bm/par"]]},
  "副词|nok":{zh:"足够；够了；大概、想必（依语气）",note:"nok 有几种常见副词义：放在名词/形容词之后或程度结构中，可表示“足够”（penger nok=足够的钱）；在陈述句中也可表示推测“想必/大概”（Det går nok bra=事情大概会顺利）。另有“再一个/再一次”义，如 nok en gang。",contexts:[["De har ikke nok mat.","他们的食物不够。","nok 位于名词 mat 前，表示数量足够；ikke nok=不够。","https://ordbokene.no/nno/bm/nok"],["Det går nok bra.","事情大概会顺利的。","句中 nok 是带保留的推测语气，不是“足够顺利”。","https://ordbokene.no/nno/bm/nok"]]},
  "限定词|begge":{zh:"两者都；双方；两个都",note:"begge 专指两个人、两件事或两组事物，通常放在定指复数名词前（begge foreldrene），也可独立作代词（Begge kom）。它表达“两边/两者都”，不是泛指“所有”。形式不变，搭配复数名词和复数谓语。",contexts:[["Begge foreldrene jobber.","父母双方都在工作。","begge 指这两位家长；foreldrene 为定指复数。","https://ordbokene.no/bm/4938"],["De gikk begge to.","他们两个人都去了。","begge to 强调两位成员都参与动作。","https://ordbokene.no/bm/4938"]]},
  "名词|kode":{zh:"代码；密码/门禁码；编码或编号（依领域）",note:"en kode 可指计算机代码（programmeringskode）、用于开门/验证的数字码（dørkode）、或信息编码。登录账户时的秘密文字密码通常说 passord；kode 不一定保密，也不一定只是数字。",contexts:[["Du må taste inn koden for å åpne døra.","你必须输入门禁码才能开门。","开门场景中的 kode 是门锁密码/门禁码。","https://ordbokene.no/bm/kode"],["Programmereren fant en feil i koden.","程序员在代码里发现了一个错误。","程序语境中的 koden 是程序代码。","https://ordbokene.no/bm/kode"]]},
  "限定词|elleve":{zh:"十一（基数词）",note:"elleve 是基数词 11，作数量和报时：elleve elever（十一名学生）、klokka elleve（十一点）。序数“第十一”不是 elleve，而是 ellevte；本条不把序数词义混进基数词。",contexts:[["Toget går klokka elleve.","火车十一点发车。","报时中的 elleve 表示 11 点。","https://ordbokene.no/bm/elleve"],["Hun har elleve elever i gruppa.","她的小组有十一名学生。","elleve 修饰复数名词 elever，表示基数11。","https://ordbokene.no/bm/elleve"]]},
  "名词|tall":{zh:"数字；数值；数量；（复数语境）统计数字/数据",note:"et tall 可指数学上的数、书写数字符号或某类数量：tallet 5 是数字5；elevtall 是学生人数；salgstall 是销售数据。若只是识别号码/序号，如门牌或电话数字，常用 nummer；区分数值本身与编号标签。",contexts:[["Skriv tallet med bokstaver.","请把这个数字用文字写出来。","tallet 指某个具体数字/数值。","https://ordbokene.no/nob/bm/tall"],["Salgstallene øker fra år til år.","销售数据逐年上升。","复合词 salgstallene 指销售统计数值。","https://ordbokene.no/nob/bm/tall"]]}
};
for (const entry of window.VOCAB_V2.additions) {
  const lemmaKey = entry.word.replace(/^(?:å|en|ei\/en|ei|et)\s+/u, "").trim();
  const correction = V2_REVIEW_BATCH_39[`${entry.pos}|${lemmaKey}`];
  if (correction) Object.assign(entry, correction);
}
const V2_REVIEW_BATCH_40 = {
  "动词|sovne":{zh:"入睡；睡着（从醒着变为睡着）",note:"å sovne 表示进入睡眠状态，强调“睡着的转变”；å sove 表示处于睡眠状态或睡一段时间。Jeg sovnet klokka ti=我十点睡着；Jeg sov i åtte timer=我睡了八小时。",contexts:[["Barnet sovnet i bilen på vei hjem.","孩子回家途中在车里睡着了。","sovnet 表示从醒着进入睡眠；på vei hjem 是“回家途中”，不是“回家的路上在车里”这种生硬倒装。","https://ordbokene.no/bm/sovne"],["Jeg har vanskelig for å sovne når det er varmt.","天气热的时候，我很难入睡。","ha vanskelig for å + 动词原形表示“做……有困难”；这里说的是入睡困难，不是睡眠质量差。","https://ordbokene.no/bm/sovne"]]},
  "动词|sove":{zh:"睡觉；处于睡眠状态；睡一段时间",note:"å sove 描写睡眠状态或睡了多久；与 sovne（入睡、睡着）区分。也可用于比喻：sove i timen 是上课走神；beinet sover 是腿麻了。",contexts:[["Jeg sov dårlig i natt.","我昨晚没睡好。","sov 是 sove 的过去时；dårlig 描述睡眠质量。","https://ordbokene.no/bm/SOVE"],["Barnet sover allerede.","孩子已经睡着了。","sover 描写正在睡的状态；若强调刚刚进入睡眠，可用 sovnet。","https://ordbokene.no/bm/SOVE"]]},
  "名词|pyjamasjakke":{zh:"睡衣上衣；睡衣的上衣部分",note:"ei/en pyjamasjakke 指成套睡衣的上衣，不是外穿的夹克；pyjamasbukse 是睡裤。口语也常说 pysjamasjakke，写作时遵从课程/词典采用的拼法。",contexts:[["Jeg finner ikke pyjamasjakka mi.","我找不到我的睡衣上衣了。","pyjamasjakka 是阴性定指单数，mi 与阴性名词一致。","https://ordbokene.no/nno/search?dict=bm%2Cnn&q=pyjamasjakke&scope=eif"],["Denne pyjamasjakka er myk og varm.","这件睡衣上衣柔软又暖和。","指睡衣的上衣部分；myk og varm 是触感/保暖描述。","https://ordbokene.no/nno/search?dict=bm%2Cnn&q=pyjamasjakke&scope=eif"]]},
  "副词|sakte":{zh:"慢慢地；缓慢地；轻声地（依语境）",note:"作副词修饰动作时表示速度慢或声音轻：snakke sakte=慢慢说；tale sakte 也可指轻声说。saktere 是比较级“更慢/慢一点”。同形 sakte 还可作形容词，sakte fart=较慢的速度。",contexts:[["Kan du snakke litt saktere?","你能说慢一点吗？","saktere 是比较级；litt saktere 是礼貌地请求放慢语速。","https://ordbokene.no/bm/sakte"],["Bilen kjørte sakte på den glatte veien.","汽车在湿滑的路面上开得很慢。","sakte 修饰 kjørte，说明行驶速度；不表示汽车在“慢慢地开进道路”。","https://ordbokene.no/bm/sakte"]]},
  "副词|fort":{zh:"快地；迅速地；很快（速度或短时间内）",note:"fort 描写速度快或事情在短时间内发生：kjøre fort=开得快；det blir fort vanskelig=很快就会变难。与 snart（不久、即将）不完全相同；fort 也可作形容词，如 en fort utvikling（快速的发展）。",contexts:[["Kan du snakke litt saktere? Du snakker veldig fort.","你能说慢一点吗？你说得太快了。","前句 saktere 是“更慢一点”，后句 fort 是“语速快”；两词在此形成对比。","https://ordbokene.no/bm/fort"],["Tiden går fort når vi har det gøy.","开心的时候，时间过得很快。","går fort 是“过得快”，不是钟表走得快这一字面动作。","https://ordbokene.no/bm/fort"]]},
  "限定词|deres":{zh:"你们的；他们的；她们的；它们的",note:"deres 可表示 dere 的所有关系“你们的”，也可表示 de 的“他们/她们/它们的”；词形本身不区分这两种人称。由上下文、对话对象或前文判断。与反身所有格 sin/sitt/sine 不同，deres 不要求所有者与句子主语同指。",contexts:[["Barna deres går på samme skole.","你们的孩子/他们的孩子在同一所学校上学。","单看这句，deres 的所有者可能是“你们”也可能是“他们”；真实语境需由前文确定，不应给出唯一中文人称。","https://ordbokene.no/bm/deres"],["Er dette huset deres?","这是你们的房子吗？/这是他们的房子吗？","同样需要上下文判断 deres 指向的所有者；本句单独出现时中文保留两种可能。","https://ordbokene.no/bm/deres"]]},
  "限定词|hennes":{zh:"她的",note:"hennes 是第三人称阴性单数的非反身所有格，形式不随所拥有事物的性、数变化：hennes veske（她的包）、hennes barn（她的孩子）。若所有物属于本句主语“她自己”，通常用 sin/sitt/sine。",contexts:[["Familien hennes bor i Trondheim.","她的家人住在特隆赫姆。","hennes 指属于另一位女性的家人；家人作句子主语时，hennes 仍可指句外的女性。","https://ordbokene.no/bm/hennes"],["Jeg kjenner søsteren hennes.","我认识她的姐姐/妹妹。","søster 不说明年龄先后，中文应译“姐妹/姐姐或妹妹”，避免擅自判断。","https://ordbokene.no/bm/hennes"]]},
  "限定词|sin":{zh:"自己的；其本人的（第三人称主语的反身所有格）",note:"sin/sitt/sine 回指同一分句中的第三人称主语，并按“被拥有的名词”变形：sin bil（阳性/阴性单数）、sitt hus（中性单数）、sine bøker（复数）。若所有者不是主语，通常用 hans/hennes/deres。",contexts:[["Hun besøker foreldrene sine hver helg.","她每个周末都去看自己的父母。","主语 hun 与父母的所有者相同，所以用复数 sine；若是别人的父母则可说 foreldrene hennes。","https://ordbokene.no/bm/sin"],["Per tok med seg boka si.","佩尔把自己的书带上了。","si 是阴性名词 boka 所对应的反身所有格；句子主语 Per 是书的所有者。","https://ordbokene.no/bm/sin"]]},
  "限定词|egen":{zh:"自己的；本人的；亲自的；专属的（强调独立/归属）",note:"egen/eget/egne 是形容词式所有表达，按所拥有的名词变形，常强调“自己的、独立拥有的”：sitt eget rom（他/她自己的房间）；på egen hånd（靠自己）。它可与反身 sin/sitt/sine 连用加强强调。",contexts:[["Hun har sitt eget rom hjemme.","她在家有自己的独立房间。","sitt 与中性名词 rom 一致；eget 加强“她自己有的/专属的”意味。","https://ordbokene.no/bm/egen"],["Vi lagde maten på egen hånd.","我们自己动手做了这顿饭。","på egen hånd 是固定表达“靠自己/亲自”，不是字面上的“在自己的手上”。","https://ordbokene.no/bm/egen"]]},
  "形容词|spesiell":{zh:"特别的；特殊的；与众不同的；具体的（依搭配）",note:"spesiell 可表示不同寻常、独特，也可表示某个特定/具体的；形容人的 han er noe spesiell 可能委婉地说“他有点特别”。副词 spesielt 常译“尤其/特别是”。",contexts:[["I dag er en spesiell dag for familien.","今天对这家人来说是个特别的日子。","spesiell 描述这一天对家庭有特殊意义，不只是“具体的一天”。","https://ordbokene.no/nob/bm/spesiell"],["Har du noe spesielt på hjertet?","你有什么特别想说的吗？","noe spesielt 作“特别的事情/话”；på hjertet 是“想说/挂在心上的事”。","https://ordbokene.no/nob/bm/spesiell"]]},
  "副词|hvorfor":{zh:"为什么；为何（询问原因）",note:"直接问句中 hvorfor 常置于句首并触发主句 V2：Hvorfor lærer du norsk?；间接问句中引导从句，动词不倒装：Hun forklarte hvorfor hun var forsinket. 回答原因常用 fordi。",contexts:[["Hvorfor lærer du norsk?","你为什么学挪威语？","直接问句：疑问词 hvorfor 在首位，限定动词 lærer 第二位，主语 du 随后。","https://ordbokene.no/bm/hvorfor"],["Hun forklarte hvorfor hun var forsinket.","她解释了自己迟到的原因。","间接问句为什么迟到：从属结构里主语 hun 位于动词 var 之前。","https://ordbokene.no/bm/hvorfor"]]},
  "名词|spørsmål":{zh:"问题；疑问；提问（依搭配）",note:"et spørsmål 可指需要回答的问题、疑问，也可指提出的一次提问。常见搭配 stille et spørsmål（提问）、svare på et spørsmål（回答问题）、spørsmålet er om ...（问题在于是否……）。不定复数与单数同形 spørsmål。",contexts:[["Kan jeg stille et spørsmål om oppgaven?","我可以问一个关于这项作业的问题吗？","stille et spørsmål 是“提出一个问题”，不是“站着一个问题”。","https://ordbokene.no/bm/sp%C3%B8rsm%C3%A5l"],["Læreren svarte på alle spørsmålene.","老师回答了所有问题。","spørsmålene 是定指复数，指当前这组已知的问题。","https://ordbokene.no/bm/sp%C3%B8rsm%C3%A5l"]]},
  "形容词|olympisk":{zh:"奥林匹克的；奥运会的",note:"olympisk 描述与奥林匹克运动会有关的人、赛事、纪录或组织；常见 de olympiske lekene（奥运会）、olympisk rekord（奥运纪录）。一般按语境译“奥运/奥林匹克”，不常为初学者练习比较级。",contexts:[["Hun drømmer om å delta i de olympiske lekene.","她梦想参加奥运会。","de olympiske lekene 是奥运会的完整挪威语名称。","https://ordbokene.no/bm/olympisk"],["Han satte ny olympisk rekord.","他创造了一项新的奥运纪录。","olympisk 修饰 rekord，表示这项纪录属于奥运赛事。","https://ordbokene.no/bm/olympisk"]]},
  "形容词|kjølig":{zh:"凉的；凉爽的；冷淡的；不热情的（依语境）",note:"天气、房间或饮料温度略低时译“凉/凉爽”，不一定冷到不舒服；描述语气、回应或关系时可译“冷淡、不热情”。",contexts:[["Det er kjølig om kvelden, så ta med en jakke.","晚上天气凉，带件夹克吧。","天气语境，kjølig 指气温偏凉；不等于严寒 kald。","https://ordbokene.no/bm/kj%C3%B8lig"],["Hun fikk et kjølig svar fra kontoret.","办公室给了她一个冷淡的答复。","抽象回应语境，不能译成温度上的“凉答复”。","https://ordbokene.no/bm/kj%C3%B8lig"]]},
  "动词|skinne":{zh:"发光；照耀；闪耀；（太阳）出太阳",note:"å skinne 描写光线明亮地发出或照射；说太阳时 Sola skinner 自然译“出太阳/阳光灿烂”，灯具或物体则译“发光/闪耀”。过去时 skinte，完成分词 skint。",contexts:[["Sola skinner, så vi går en tur.","太阳出来了，所以我们去散散步。","Sola skinner 是常见天气表达“出太阳”，比“太阳在照耀”更符合中文日常说法。","https://ordbokene.no/bm/skinne"],["Lampen skinte svakt i mørket.","灯在黑暗中发出微弱的光。","灯具作主语时，skinne 是发光；过去式 skinte。","https://ordbokene.no/bm/skinne"]]},
  "动词|regne":{zh:"下雨；计算；估算/推算（依结构）",note:"væruttrykket det regner 表示“下雨”；regne ut + 结果表示“算出”；regne med + 内容表示“预计/考虑到”。须看结构和宾语，不能把所有义项混成一个中文词。",contexts:[["Det regner mye i Bergen i dag.","卑尔根今天雨下得很大。","无宾语、以 det 作形式主语的天气句，regner 是“下雨”。","https://ordbokene.no/bm/regne"],["Kan du regne ut hvor mye vi skal betale?","你能算出我们要付多少钱吗？","regne ut + 疑问从句表示计算出结果；不是天气义。","https://ordbokene.no/bm/regne"]]},
  "动词|blåse":{zh:"吹；吹气；刮风；吹奏（依主语/宾语）",note:"风作主语时 det blåser=刮风；人吹气时 blåse på suppa=朝汤吹一吹；乐器语境可表示吹奏。含 det 的天气句、带介词 på 的吹气搭配要分开记。",contexts:[["Det blåser mye ved sjøen i dag.","今天海边风很大。","det blåser 是天气表达“刮风”，不是有人在吹。","https://ordbokene.no/bm/bl%C3%A5se"],["Hun blåste på suppa før hun smakte.","她尝汤之前先吹了吹，让汤凉一点。","blåse på + 食物表示对着食物吹气；不是吹奏乐器。","https://ordbokene.no/bm/bl%C3%A5se"]]},
  "动词|fryse":{zh:"觉得冷；结冰；冷冻（依主语和结构）",note:"人作主语、表示身体感受时 fryse=觉得冷；水等作主语时可表示结冰；fryse ned + 食物=冷冻保存。三种用法共享词形，但中文要按主语和搭配判断。",contexts:[["Ta på deg jakka hvis du fryser.","如果你觉得冷，就把外套穿上。","主语 du 是人，fryser 表示感觉冷。","https://ordbokene.no/bm/fryse"],["Vi frøs ned restene til senere.","我们把剩菜冷冻起来，留着以后吃。","frøs ned 是 fryse ned 的过去时搭配，表示冷冻保存；不是“我们觉得剩菜很冷”。","https://ordbokene.no/bm/fryse"]]},
  "形容词|våt":{zh:"湿的；潮湿的；被液体/雨水弄湿的（依语境）",note:"våt 表示表面或材料含水、沾湿；可能是被雨淋湿，也可能来自洗涤、洒水或其他液体。雨只是常见原因之一，不是词义本身。",contexts:[["Jeg ble våt på vei hjem fordi det regnet.","下雨了，我回家路上淋湿了。","这里 because 从句说明淋湿的原因是下雨；单独 våt 不包含“被雨淋”的意思。","https://ordbokene.no/bm/v%C3%A5t"],["Barna la de våte vottene på gulvet.","孩子们把湿手套放在地板上。","våte 与复数定指名词 vottene 搭配；手套湿了，但句子没有说明是雨水造成。","https://ordbokene.no/bm/v%C3%A5t"]]},
  "名词|karamellpudding":{zh:"焦糖布丁；焦糖布丁甜点",note:"karamellpudding 是用焦糖制作的凝固甜点，挪威常见家常/节庆甜品；pudding 不是泛指所有杯装布丁。菜名通常不加冠词，指桌上那一份时用定指 karamellpuddingen。",contexts:[["Bestemor lager karamellpudding til jul.","奶奶圣诞节会做焦糖布丁。","karamellpudding 作菜名泛指这道甜点；til jul 表示圣诞节期间。","https://ordbokene.no/bm/karamellpudding"],["Vi serverte karamellpuddingen med krem.","我们端上焦糖布丁，并配了奶油。","定指 karamellpuddingen 指已经做好的那份布丁。","https://ordbokene.no/bm/karamellpudding"]]},
  "名词|eplekake":{zh:"苹果蛋糕（挪威式烘焙蛋糕）",note:"ei/en eplekake 是加入苹果烘烤的蛋糕；不能仅凭中文“苹果蛋糕”误认为一定是有酥皮的美式苹果派。常与咖啡或香草酱搭配。",contexts:[["Bestemor bakte eplekake med epler fra hagen.","奶奶用自家花园里的苹果烤了苹果蛋糕。","bakte 是 bake 的过去时；eplekake 指烘烤的蛋糕，不直接等同于苹果派。","https://ordbokene.no/bm/12948"],["Vi fikk et stykke varm eplekake til kaffen.","喝咖啡时，我们吃了一块热苹果蛋糕。","et stykke eplekake 是“一块苹果蛋糕”；kake 在这里是配咖啡的点心。","https://ordbokene.no/bm/12948"]]},
  "名词|sjokoladekake":{zh:"巧克力蛋糕",note:"ei/en sjokoladekake 是以巧克力/可可为主要风味的蛋糕；区别于 sjokolade（巧克力本身）和 sjokoladepudding（巧克力布丁）。",contexts:[["Jeg baker en sjokoladekake til bursdagen.","我为生日烤一个巧克力蛋糕。","bake en kake 表示烘烤蛋糕；en sjokoladekake 是不定单数。","https://ordbokene.no/bm/sjokoladekake"],["Sjokoladekaka står på kjøkkenbordet.","巧克力蛋糕放在厨房桌上。","sjokoladekaka 是阴性定指单数形式；也可用阳性 sjokoladekaken。","https://ordbokene.no/bm/sjokoladekake"]]},
  "名词|bløtkake":{zh:"奶油夹层蛋糕；鲜奶油蛋糕（常用于庆祝）",note:"ei/en bløtkake 通常是柔软蛋糕胚夹奶油/奶油馅并装饰的庆祝蛋糕；中文可说奶油蛋糕，但不宜与普通奶油裱花蛋糕或硬脆蛋糕混同。",contexts:[["Vi serverte bløtkake i bursdagen til bestemor.","奶奶生日时，我们端上了奶油夹层蛋糕。","bløtkake 常作为生日庆祝蛋糕；i bursdagen til ... 指在某人的生日庆祝活动上。","https://ordbokene.no/bm/bl%C3%B8tkake"],["Hun pyntet bløtkaka med jordbær og krem.","她用草莓和奶油装饰了奶油蛋糕。","bløtkaka 是阴性定指单数；jordbær og krem 是装饰材料。","https://ordbokene.no/bm/bl%C3%B8tkake"]]},
  "名词|pudding":{zh:"布丁；凝固/蒸制的半固体菜肴；（口语比喻）疲惫的人",note:"pudding 可指在模具中煮或烤制、质地半固体的菜肴，既有甜味也有咸味品种；在血肠/肉类菜名中也可作后缀。口语 helt pudding 还可形容人累瘫了，需按上下文辨别。",contexts:[["Til dessert fikk vi karamellpudding.","甜点我们吃了焦糖布丁。","明确甜品语境，pudding 指布丁类菜肴。","https://ordbokene.no/bm%2Cnn/PUDDING"],["På søndagen lå jeg på sofaen og var helt pudding.","星期天我躺在沙发上，累得整个人都瘫了。","词典比喻用法；此处 pudding 形容疲惫的人，不是吃的布丁。","https://ordbokene.no/bm%2Cnn/PUDDING"]]},
  "名词|sjokolade":{zh:"巧克力；一板/一块巧克力（依量词）",note:"sjokolade 通常作物质名词，指巧克力这种食品或口味；计量时说 litt sjokolade（一点巧克力）、en plate sjokolade（一板巧克力）、et stykke sjokolade（一块巧克力）。某些语境可数，但不要默认每次都加冠词。",contexts:[["Jeg kjøpte en plate mørk sjokolade.","我买了一板黑巧克力。","en plate 是计量整板巧克力的量词，mørk 修饰 sjokolade。","https://ordbokene.no/bm/sjokolade"],["Barna fikk litt sjokolade etter middagen.","孩子们晚饭后吃了一点巧克力。","litt + 物质名词表示少量巧克力，不是“一块”。","https://ordbokene.no/bm/sjokolade"]]}
};
for (const entry of window.VOCAB_V2.additions) {
  const lemmaKey = entry.word.replace(/^(?:å|en|ei\/en|ei|et)\s+/u, "").trim();
  const correction = V2_REVIEW_BATCH_40[`${entry.pos}|${lemmaKey}`];
  if (correction) Object.assign(entry, correction);
}
Object.assign(V2_REVIEW_CORRECTIONS_FINAL, {
  ring:{zh:"戒指；环；圆圈；（依搭配）团体",note:"最常见的是戴在手指上的戒指，也可指环形物或圆圈：en ring på fingeren（一枚戴在手指上的戒指）、stå i ring（围成一圈）。词典另列同形中性名词 et ring（一次铃声）；本卡的 en ring 不表示铃声。",contexts:[["Hun fikk en ring av bestemoren sin.","她收到祖母送的一枚戒指。","en ring 指首饰；av bestemoren sin 表示礼物来自祖母。","https://ordbokene.no/bm/ring"],["Folk sto i ring rundt den skadde.","人们围在伤者周围，站成一圈。","词典例句；i ring 表示形成圆圈，不是每个人都戴着戒指。","https://ordbokene.no/bm/ring"]]},
  ting:{zh:"东西；物品；事情；情况（依语境）",note:"en ting 可指具体物品：hente noen ting（拿几样东西）；也可泛指一件事、情况或某个方面：det er én ting jeg ikke forstår（有一件事我不明白）。通常靠谓语和上下文判断，不必每次都译成“东西”。另有历史/政治语境的中性名词 ting（议会/代表大会），本卡先学日常阳性词。",contexts:[["Jeg må snakke med deg om en ting.","我有件事得跟你谈谈。","词典例句；om en ting 在此引出谈话的事情，不是一个物件。","https://ordbokene.no/bm/ting"],["Jeg fant noen ting i esken.","我在盒子里找到几样东西。","自拟语境句；可触摸的小物件语境下译“东西”。","https://ordbokene.no/bm/ting"]]},
  kaos:{zh:"混乱；一片混乱；无秩序状态",note:"描述人或事物无序、难以控制的状态：kaos på kjøkkenet（厨房乱成一团）、politisk kaos（政治混乱）。日常通常把 kaos 当整体状态，不常数“几个混乱”；词典虽列有 kaoser 等复数形式，初学时先掌握 kaos/kaoset。",contexts:[["Det var kaos på kjøkkenet.","厨房里乱成一团。","词典例句；kaos 不带冠词，表示当时的一片混乱。","https://ordbokene.no/nob/bm/28589"],["Det rådde politisk kaos i landet.","这个国家当时政局一片混乱。","词典例句；政治语境说明混乱发生在公共治理层面。","https://ordbokene.no/nob/bm/28589"]]},
  døgn:{zh:"一昼夜；连续24小时",note:"一个 døgn 是从某时点起连续计算的24小时，包含一天和一夜；它不是“白天”dag，也不一定从午夜开始。hele døgnet = 全天24小时，i tre døgn = 连续三昼夜。",contexts:[["Apoteket har åpent 24 timer i døgnet.","这家药房每天24小时营业。","词典例句；i døgnet 表示按每个连续24小时计算。","https://ordbokene.no/bm/d%C3%B8gn"],["Togreisen tok nesten et døgn.","这趟火车旅程花了将近一昼夜。","自拟语境句；et døgn 表示持续时长约24小时，不是某个日历日。","https://ordbokene.no/bm/d%C3%B8gn"]]},
  måned:{zh:"月；一个月；（日历中的）月份",note:"可指约30天的时段，也可指一年中的某个日历月份。三个月通常说 tre måneder（不规则复数）；每月可说 hver måned，具体月份前常用 i：i april（在四月）。",contexts:[["Kurset varer i tre måneder.","这门课程持续三个月。","三个月的持续时长用复数 måneder。","https://ordbokene.no/nob/bm/m%C3%A5ned"],["Vi betaler husleie én gang i måneden.","我们每个月交一次房租。","词典例句；i måneden 在频率表达中表示“每月”。","https://ordbokene.no/nob/bm/m%C3%A5ned"]]},
  bursdag:{zh:"生日；生日聚会/庆祝（依句型）",note:"ha bursdag 表示某人生日在某天；feire bursdag 是庆祝生日；invitere noen i bursdagen sin 可指邀请某人参加生日聚会。因此词头本义是生日，具体是否指聚会由动词和上下文决定。",contexts:[["De har bursdag på samme dag.","他们生日在同一天。","词典例句；ha bursdag 说明出生纪念日，不是在说聚会。","https://ordbokene.no/nno/search?dict=bm%2Cnn&q=bursdag&scope=eif"],["Hun inviterte hele klassen i bursdagen sin.","她邀请了全班同学来参加自己的生日聚会。","词典例句；invitere ... i bursdagen 这里指庆祝活动。","https://ordbokene.no/nno/search?dict=bm%2Cnn&q=bursdag&scope=eif"]]},
  dunk:{zh:"大桶；桶状容器（常装液体）；（另有同形词）砰的一声",note:"本卡是阳性名词 en dunk，词典指桶状容器，如一桶啤酒或废物桶；不要泛化成任何尺寸的瓶罐。词典另收同形中性名词 et dunk，表示墙上传来的“砰”声；注意冠词不同，意义也不同。",contexts:[["Vi har en dunk øl til festen.","我们为聚会准备了一桶啤酒。","词典例句；en dunk 指桶状容器，内容物由 øl 说明。","https://ordbokene.no/bm/dunk"],["Det kom et dunk fra veggen.","墙那边传来一声砰响。","词典例句；et dunk 是中性名词“砰的一声”，不是一只桶。","https://ordbokene.no/bm/dunk"]]},
  eske:{zh:"盒子；纸盒/木盒；小型收纳容器",note:"可用 ei eske 或 en eske；通常是用于收纳或运输的较小容器，尤其纸板或木制。包装、火柴盒等用 eske；尺寸更大的箱子常说 kasse。",contexts:[["En eske fyrstikker ligger i skuffen.","抽屉里有一盒火柴。","词典搭配 eske fyrstikker 指一盒火柴；eske 可用阴性或阳性冠词。","https://ordbokene.no/bm/eske"],["Legg dokumentene i esken.","把文件放进那个盒子里。","词典例句；i esken 是定指形式“放进那个盒子”。","https://ordbokene.no/bm/eske"]]},
  salami:{zh:"萨拉米香肠；萨拉米（通常切片食用）",note:"指 salamipølse，即经过调味、腌制的香肠品类；常作为面包配料或冷盘。不是专指意大利制造的某一款香肠；词典词性为阳性 en salami。",contexts:[["Jeg kjøpte en pakke salami i butikken.","我在商店买了一包萨拉米香肠。","词典例句；en pakke salami 是“一包萨拉米”。","https://ordbokene.no/bm/salami"],["Han spiser brød med salami til lunsj.","他午餐吃夹萨拉米的面包。","自拟语境句；这里 salami 是面包配料。","https://ordbokene.no/bm/salami"]]},
  skinke:{zh:"火腿；（肉类/身体部位）后腿；臀部（口语）",note:"食物语境中通常译“火腿”；词典更具体地指猪（也可指其他动物）后腿的肉。口语中 skinke 还可指臀部，如 få vondt i skinka（臀部疼）；不要在菜单或三明治语境中误译成身体部位。Bokmål 可用 ei/en skinke。",contexts:[["Henge opp skinka til speking.","把那条火腿肉挂起来腌制风干。","词典例句片段；此处 skinka 指用于腌制的后腿肉。","https://ordbokene.no/nob/bm/skinke"],["Jeg lager en sandwich med ost og skinke.","我做了一个奶酪火腿三明治。","自拟语境句；食物搭配中 skinke 是火腿。","https://ordbokene.no/nob/bm/skinke"]]},
  stenge:{zh:"关上并封闭；关门停业；封锁/阻断（依对象）",note:"stenge døra 是把门关上，常带有封闭/上锁意味；butikken stenger 表示商店停止营业；stenge veien/stenge for adgangen 表示封路或阻断通行。别把所有用法都缩成“关东西”。",contexts:[["Kafeen stenger klokka 20.","咖啡馆晚上八点打烊。","词典例句；商店或场所作主语时 stenger 表示停止营业。","https://ordbokene.no/nno/bm/stenge"],["Husk å stenge vinduet før du går.","走之前记得把窗户关好。","自拟语境句；具体物体作宾语时表示关上。","https://ordbokene.no/nno/bm/stenge"]]},
  disk:{zh:"柜台；（电脑）磁盘/存储盘；飞盘（依义项）",note:"这是同形多义名词：店铺、咖啡馆里的长柜台是阳性 en disk；计算机磁性存储盘也是 en disk；轻而会旋转飞行的塑料盘可叫 disk/frisbee。柜台语境常见 stå bak disken（在柜台后服务），硬盘通常说 harddisk。",contexts:[["Lokalet er innredet med disk, hyller og skuffer.","店里配有柜台、货架和抽屉。","词典例句；和货架、抽屉并列，disk 指柜台。","https://ordbokene.no/bm/disk"],["En disk med ekstramateriale.","一张存有附加资料的磁盘。","词典例句片段；计算机存储语境中 disk 指磁盘，不是服务柜台。","https://ordbokene.no/bm/disk"]]},
  trykke:{zh:"按压；挤压；印刷、印制（依义项）",note:"trykke på knappen = 按按钮；trykke noe inn/sammen = 把东西压进去/压紧；出版社 trykker en bok = 印刷一本书。印刷义与按压义是词典区分的两个动词义项，理解时看宾语和场景；过去时可用 trykket/trykte，完成分词有 trykket/trykt。",contexts:[["Trykk på knappen.","按下按钮。","词典例句；trykke på + 按钮表示用力按压。","https://ordbokene.no/bm/trykke"],["Forlaget trykker aviser og bøker.","出版社印刷报纸和书籍。","词典例句；主语为出版社、宾语为出版物时是“印刷”义。","https://ordbokene.no/bm/trykke"]]},
  PC:{zh:"个人电脑；个人计算机（台式机或笔记本）",note:"PC 是 personal computer 的缩写，指供个人使用的电脑；可为台式机或笔记本，是否便携要由 bærbar（笔记本/便携式）等词说明。与 telefon/mobil（手机）区分。",contexts:[["Bærbare og stasjonære PC-er.","笔记本电脑和台式电脑。","词典例句片段；PC 本身是个人电脑总称，bærbar 与 stasjonær 再区分形态。","https://ordbokene.no/bm/pc"],["Jeg bruker PC-en til å skrive oppgaven.","我用电脑写作业。","自拟语境句；PC-en 是 PC 的定指单数。","https://ordbokene.no/bm/pc"]]},
  modell:{zh:"模型；型号/款式；模特；理论模式（依语境）",note:"modell av noe 通常是某个东西的模型；bil/mobil 的 modell 是型号或款式；jobbe/sitte modell 表示当模特；研究或计划中的 modell 是简化的理论模型。用搭配识别意思，不能只背“模型”。",contexts:[["De har laget en modell av bydelen.","他们制作了一个这个城区的模型。","词典例句；modell av + 地点表示按实物缩小制作的模型。","https://ordbokene.no/bm/modell"],["Bilen er en eldre modell.","这辆车是较早的款型。","词典例句；谈汽车时 modell 指型号/款式，不是实体模型。","https://ordbokene.no/bm/modell"]]},
  politi:{zh:"警方；警察机关；（另有阳性用法）一名警察",note:"本卡按最常见的中性名词 et politi 学“警方/警察机关”，常说 ringe politiet。词典另收阳性 en politi，表示一名警察，但初学者更稳妥、常用的个人称呼是 en politibetjent；不能把 politiet 当成一名警员。",contexts:[["Politiet kom på stedet like etter ulykken.","事故发生后不久，警方就赶到了现场。","词典例句；定指中性 politiet 指警察机关/警方整体。","https://ordbokene.no/nob/bm/politi"],["En politibetjent snakket med vitnene.","一名警员和目击者交谈。","自拟对比例句；单个执法人员常用 politibetjent。","https://ordbokene.no/nob/bm/politi"]]},
  samfunn:{zh:"社会；共同体/社群；地方社区（依范围）",note:"可指一国由共同制度、法律和传统组成的社会整体；也可指有共同目标/信仰的社群、一个城镇或地方社区，甚至动物群体。det norske samfunnet 通常是“挪威社会”，et lite samfunn 可是小型社区；不是只指抽象“社会体系”。",contexts:[["Språket gjør det lettere å delta i samfunnet.","掌握语言会让人更容易参与社会生活。","自拟语境句；delta i samfunnet 表示参与社会生活。","https://ordbokene.no/bm/samfunn"],["Mauren lever i samfunn.","蚂蚁以群体形式生活。","词典例句；生物语境中 samfunn 指有组织的动物群体。","https://ordbokene.no/bm/samfunn"]]},
  hensyn:{zh:"考虑因素；顾及；体谅（常见固定搭配）",note:"ta hensyn til 可表示把某条件纳入考虑，也可表示体谅、照顾某人；vise hensyn 是体谅他人；av hensyn til 是“出于……考虑/为了顾及……”。抽象意义常以复数 hensyn 出现，如 det er mange hensyn å ta（有很多因素要考虑）。",contexts:[["Det er mange hensyn å ta.","有很多因素需要考虑。","词典例句；hensyn 在这里是需要纳入权衡的条件。","https://ordbokene.no/bm/hensyn"],["Vis hensyn til de minste barna.","请多体谅年幼的孩子。","词典搭配；vise hensyn til 指待人时多加体谅、照顾。","https://ordbokene.no/bm/hensyn"]]},
  representere:{zh:"代表；作为代表出席/参赛；体现、代表某种特点",note:"representere Norge i en konkurranse = 代表挪威参赛；代表公司/国家办事是代表其出面；颜色、数据或作品也可 representere（体现/代表）某类事物。看宾语判断是“代表谁”还是“体现什么”。",contexts:[["Han representerer Norge i konkurransen.","他代表挪威参加这项比赛。","词典例句；representere + 国家 + i + 比赛表示代表该国参赛。","https://ordbokene.no/bm/representere"],["Boka representerer noe nytt.","这本书体现了一种新的东西/新方向。","词典例句；抽象宾语语境下代表/体现一种新事物，而不是代替某人出席。","https://ordbokene.no/bm/representere"]]},
  fredspris:{zh:"和平事业奖项；和平奖",note:"为个人或团体在和平事业上的特别贡献颁发的荣誉奖项；Nobels fredspris 特指诺贝尔和平奖。单词不只指诺贝尔奖，其他组织也可以设立 fredspris。",contexts:[["Nobels fredspris deles ut i Oslo.","诺贝尔和平奖在奥斯陆颁发。","Nobels fredspris 是该专名的固定形式；挪威诺贝尔委员会在奥斯陆颁奖。","https://ordbokene.no/bm/17708"],["Hun fikk en internasjonal fredspris for arbeidet sitt.","她因自己的工作获得了一项国际和平奖。","自拟语境句；fredspris 可泛指各类和平事业奖项。","https://ordbokene.no/bm/17708"]]},
  møtes:{zh:"见面；相遇；会合/汇合（依主语）",note:"人作主语时 møtes 表示彼此见面或偶然相遇；河流、道路等作主语时可指汇合。它是相互动词，表示双方/多方彼此发生会面；与 møte noen（某人会见/碰到另一个人）区分。",contexts:[["De møttes tilfeldigvis på gata.","他们在街上偶然碰见了。","词典例句；人作主语时 møttes 表示彼此相遇。","https://ordbokene.no/nob/bm/M%C3%98TES"],["De to elvene møtes nede i dalen.","两条河在山谷下游汇合。","词典例句；河流作主语时 møtes 是汇合，不是“见面”。","https://ordbokene.no/nob/bm/M%C3%98TES"]]},
  speilreflekskamera:{zh:"单镜头反光相机；单反相机（可为胶片或数码）",note:"相机类型名称，中文常简称“单反”。speilreflekskamera 不自动表示数码；胶片或数码机型都可能属于单反，需说 digitalt speilreflekskamera 才明确是数码单反。",contexts:[["Hun tok bilder av fjellene med et speilreflekskamera.","她用一台单反相机拍了群山。","med et speilreflekskamera 表示使用单反相机拍摄；没有说明胶片或数码。","https://ordbokene.no/search?dict=bm%2Cnn&q=speilreflekskamera&scope=eif"],["Et digitalt speilreflekskamera har et speil i kamerahuset.","数码单反相机的机身内有一面反光镜。","自拟定义句；digitalt 才明确说明是数码单反。","https://ordbokene.no/search?dict=bm%2Cnn&q=speilreflekskamera&scope=eif"]]},
  uskarp:{zh:"模糊的；不清楚的；（刀刃等）不锋利的",note:"描述照片/轮廓时是模糊、不清楚：et uskarpt bilde；描述刀刃时是不锋利：en uskarp kniv。两种意思都与 sharp（清晰/锋利）的反义相关，需根据修饰对象选译。",contexts:[["En uskarp kniv.","一把不锋利的刀。","词典例句片段；修饰 kniv 时 uskarp 是刃口不锋利。","https://ordbokene.no/bm/uskarp"],["Bildet ble uskarpt fordi kameraet beveget seg.","相机移动了，所以照片拍糊了。","自拟语境句；修饰 bilde 时表示成像模糊。","https://ordbokene.no/bm/uskarp"]]},
  nasjonalitet:{zh:"国籍；民族身份/国别身份（依语境）",note:"核心是归属于某个国家/民族的身份；个人资料表格里通常问护照或国家意义上的“国籍”，有时也可指不同民族身份。它不等于 språk（语言）或 etnisitet（族裔，某些语境中需进一步区分）。",contexts:[["Han er av polsk nasjonalitet.","他是波兰国籍。","词典例句；av + 国籍形容词说明所属国籍。","https://ordbokene.no/bm/nasjonalitet"],["Deltakere av mange nasjonaliteter.","来自许多不同国家/民族身份的参与者。","词典例句片段；复数 nasjonaliteter 指不同国籍/民族身份。","https://ordbokene.no/bm/nasjonalitet"]]},
  arm:{zh:"手臂；上肢；（物体）臂状部分/分支",note:"人体部位是手臂（手之外、连接肩部的上肢部分）；也可指章鱼的腕足、独轮车的把手/支臂，或峡湾向外伸出的一支。注意 arm 是手臂，hånd 是手。另有同形形容词 arm（可怜的/贫穷的），不是这张名词卡。",contexts:[["Jeg har vondt i armene.","我手臂疼。","词典例句；armene 指人的手臂，和 hånd（手）相区别。","https://ordbokene.no/bm/arm"],["Armene på en trillebår.","独轮车的两根支臂。","词典例句片段；描述器具时 arm 是形状/功能类似手臂的支臂。","https://ordbokene.no/bm/arm"]]}
});
for (const entry of window.VOCAB_V2.additions) {
  const lemmaKey = entry.word.replace(/^(?:å|en|ei|et)\s+/u, "").trim();
  const finalCorrection = V2_REVIEW_CORRECTIONS_FINAL[entry.id] || V2_REVIEW_CORRECTIONS_FINAL[lemmaKey];
  if (finalCorrection) Object.assign(entry, finalCorrection);
}
Object.assign(V2_REVIEW_CORRECTIONS_FINAL, {
  skremme:{zh:"吓到；使害怕；吓走、驱赶（依结构）",note:"skremme noen 表示把某人吓到；bli skremt 是“受到惊吓”；skremme bort fugler 则是把鸟吓走。注意施事和受事：Den høye lyden skremte meg 是“巨响吓了我一跳”。",contexts:[["Du skremmer ikke meg.","你吓不倒我。","词典例句；skremmer 的主语 du 是施事，meg 是被吓的人。","https://ordbokene.no/bm/skremme"],["Bonden prøvde å skremme bort trostene.","农场主试着把那些乌鸫赶走。","词典搭配 skremme bort trost 指把鸟吓走；bort 表示远离。","https://ordbokene.no/bm/skremme"]]},
  tåre:{zh:"眼泪；一滴泪；泪水（常用复数 tårer）",note:"tåre 是眼泪这一滴液体，常以复数 tårer 表示流泪：tårer i øynene（眼里含着泪）。固定搭配 felle en tåre 是“流下一滴泪”，ta til tårene 是“哭起来”。不要与动词 gråte（哭）混淆。",contexts:[["Hun fikk tårer i øynene av medlidenhet.","她因同情而眼里泛起泪水。","词典例句；tårer i øynene 描写眼里含泪，av medlidenhet 说明原因。","https://ordbokene.no/bm/t%C3%A5re"],["Han lo så tårene trillet.","他笑得眼泪都流出来了。","词典例句；tårene trillet 是眼泪流下，不表示悲伤。","https://ordbokene.no/bm/t%C3%A5re"]]},
  lykkelig:{zh:"幸福的；感到幸福/快乐的；顺利的、幸运的（事件/结果）",note:"形容人时多指幸福或快乐的状态；描述开局、结果时可表示顺利、称心、幸运：en lykkelig start（顺利的开端）、et lykkelig utfall（圆满的结果）。一时高兴也可用 glad；不要把所有 lykkelig 都译为“幸运”。",contexts:[["Han var lykkelig over utfallet.","他对这个结果感到很满意、很高兴。","词典例句；lykkelig over + 结果表示因结果而感到幸福/高兴。","https://ordbokene.no/bm/lykkelig"],["De håper på en lykkelig slutt.","他们盼望有个圆满的结局。","自拟语境句；形容结局时 lykkelig 表示圆满、顺遂，不是人的情绪。","https://ordbokene.no/bm/lykkelig"]]},
  stemning:{zh:"情绪/心情；气氛；态度或倾向（依语境）",note:"可指个人或群体当时的心情，也可指场所营造的氛围；det var stemning for å utsette saken 表示大家倾向于推迟此事。与 stemme（声音/投票）不是同一个意思。",contexts:[["Stemningen i salen var høy.","大厅里的气氛很热烈。","词典例句；指人群共同形成的现场气氛。","https://ordbokene.no/bm/stemning"],["Det var stemning for å utsette saken.","当时大家倾向于把这件事推迟。","词典例句；stemning for + 动词/事项表示群体倾向，不是现场情绪气氛。","https://ordbokene.no/bm/stemning"]]},
  bekymret:{zh:"担心的；忧虑的；（表情）显出担忧的",note:"描述一个人感到担心，或表情显出担忧。常用 bekymret for + 人/事、bekymret for at + 从句，也见 bekymret over + 发展/情况。与 bekymrende（令人担忧的）区分：原因令人担忧，人则感到担心。",contexts:[["Forskere er bekymret over utviklingen.","研究人员对事态的发展感到担忧。","词典例句；bekymret over + 发展情况说明担忧的缘由。","https://ordbokene.no/bm/bekymret"],["Hun hadde et bekymret uttrykk i ansiktet.","她脸上带着担忧的神情。","词典例句；修饰表情时译“显出担忧”，不是说表情本身在担心。","https://ordbokene.no/bm/bekymret"]]},
  ensom:{zh:"孤独的；感到寂寞的；偏僻、孤零零的（地点）",note:"形容人时通常是缺少陪伴而感到孤独，带主观感受；形容地点时可指偏僻、孤零零地坐落。alene 只说明“独自”，不一定难过；ensom ulv 是独来独往的人。",contexts:[["Han kjente seg ensom og forlatt.","他觉得孤独无依。","词典搭配片段；ensom og forlatt 描写主观孤独感。","https://ordbokene.no/bm/ensom"],["Huset ligger ensomt til.","那栋房子坐落在偏僻处。","词典例句；形容房屋位置时 ensomt 是“孤零零/偏僻”，不是房子感到寂寞。","https://ordbokene.no/bm/ensom"]]},
  flau:{zh:"尴尬的；难为情的；令人难堪的；（味道/笑话）淡而无味、乏味的",note:"人因出糗而感到难为情：bli flau over noe；事件本身令人尴尬：en flau affære。词典还收录 flau vin（味道淡而无味）、flau vind（微风，特定风力级别）和 flaue vitser（乏味的笑话）。按修饰对象选择意思。",contexts:[["Hun ble flau over kommentaren sin.","她为自己说的那句话感到难为情。","词典搭配片段；flau over + 事情表示为此感到尴尬。","https://ordbokene.no/bm/flau"],["Dette var en flau affære.","这件事真让人难堪。","词典例句；修饰 affære 时 flau 是“令人尴尬/难堪的”，不是当事人的心情。","https://ordbokene.no/bm/flau"]]},
  nervøs:{zh:"紧张不安的；焦虑的；神经系统相关的；（市场/局势）不稳定的",note:"常见日常义是因等待、考试或压力而紧张；也可用于神经系统疾病等医学语境。比喻说市场 nervøst 表示波动、不稳定。不是诊断人的医学标签；可说 nervøs for/over noe，nervøs før en eksamen。",contexts:[["Studentene var nervøse før eksamen.","学生们考前都很紧张。","词典例句；复数 nervøse 描写考试前的情绪状态。","https://ordbokene.no/bm/nerv%C3%B8s"],["Et nervøst aksjemarked reagerte raskt.","波动不稳的股市迅速作出反应。","自拟语境句；形容市场时 nervøs 是“波动、不稳定”，不是市场在害怕。","https://ordbokene.no/bm/nerv%C3%B8s"]]},
  redd:{zh:"害怕的；恐惧的；担心的（常见结构 redd for）",note:"redd 描写感到害怕，也可表示担心某事会发生。redd for + 名词可说害怕对象；redd for å + 动词表示害怕做某事；redd for at + 从句常是担心某种结果。比如 jeg er redd du ... 可译“我怕/担心……”，不一定是强烈恐惧。",contexts:[["De er redde for å bli angrepet.","他们担心会遭到袭击。","词典例句；redde for å + 动词表示害怕/担心将发生的事。","https://ordbokene.no/bm/redd"],["Jeg er redd du ikke vil lykkes.","我担心你可能不会成功。","词典例句；此处是委婉表达担心，不是害怕对方本人。","https://ordbokene.no/bm/redd"]]},
  sint:{zh:"生气的；愤怒的",note:"表示正在生气或表现出愤怒。常用 sint på + 人（生某人的气）、sint for + 事（因某事生气）：på 引出对象，for 常引出缘由。语气强弱依场景；不要把它和“受伤心”混为一谈。",contexts:[["Han var sint på naboen.","他在生邻居的气。","词典例句结构；sint på + 人说明愤怒指向谁。","https://ordbokene.no/bm/sint"],["Hun var sint for at ingen hadde ringt.","她因为没人打电话而生气。","自拟语境句；for at 从句说明生气的原因。","https://ordbokene.no/bm/sint"]]},
  spent:{zh:"期待、兴奋的；紧张的；（情势）紧绷的；绷紧的（依语境）",note:"等待结果、期待活动时通常是带期待的兴奋，也可含紧张；形容关系或局势时可指紧张、敌意浓；物体/肌肉可指绷紧。så jeg spent på resultatet ≠ 单纯“绷紧”。",contexts:[["Hun venter spent på resultatet.","她满怀期待地等着结果。","词典例句；spent 修饰等待状态，侧重期待，也可能带一点紧张。","https://ordbokene.no/bm/spent"],["Situasjonen mellom naboene er spent.","邻居之间的关系很紧张。","词典例句；描述局势时 spent 表示关系紧绷，并非期待。","https://ordbokene.no/bm/spent"]]},
  urolig:{zh:"坐立不安的；担心的；动荡/不平静的（人、环境或局势）",note:"一个词覆盖几类“不安”：人不停移动/难安静、心里焦虑；天气、海面、睡眠或政治局势不平稳。urolig for + 人/事是“为……担心”；描述 urolig sjø 是“海面不平静”。",contexts:[["Hun er urolig for framtiden.","她对未来感到担忧。","词典例句；urolig for + 事项表示心里担心。","https://ordbokene.no/bm/urolig"],["Det var urolig sjø langs kysten.","沿岸海面风浪不平静。","自拟语境句；修饰 sjø 时 urolig 描写水面状况，不是心情。","https://ordbokene.no/bm/urolig"]]},
  smil:{zh:"微笑；笑容；一个微笑（名词）",note:"本卡是中性名词 et smil，表示脸上的笑容/微笑；动词是 å smile（微笑）。常说 sende noen et smil（朝某人微微一笑）、med et smil（带着笑容）。",contexts:[["Ansiktet lyste opp i et stort smil.","她的脸上绽开灿烂的笑容。","词典例句；et stort smil 是灿烂的笑容；句子主语“脸”可自然译成“她的脸”。","https://ordbokene.no/bm/smil"],["Hun trakk på smilet.","她忍不住露出一丝笑意。","词典例句；trekke på smilet 是略微笑起来，不等于放声大笑。","https://ordbokene.no/bm/smil"]]},
  synd:{zh:"罪；过错；可惜/遗憾（固定句型 det er synd）",note:"宗教或道德语境中是“罪/过错”；日常 Det er synd at ...、Så synd! 通常表示“真可惜/遗憾”。synes synd på noen 则是“同情某人”。这几个句型意思不同，不要把所有 synd 都译为“罪”。",contexts:[["Det var synd at de ikke kunne komme.","他们没能来，真可惜。","词典例句；det var synd at + 从句表示遗憾。","https://ordbokene.no/bm/synd"],["Bonden synes synd på dyra.","农场主很同情那些动物。","词典例句；synes synd på + 人/动物是“同情……”，句子不是在说罪过。","https://ordbokene.no/bm/synd"]]},
  usikker:{zh:"不确定的；没有把握的；不安全/不稳定的；不可靠的（依语境）",note:"描述答案、未来时“未知/不确定”；人 føler seg usikker 是缺乏把握或不安；冰面、道路、环境 usikker 则有危险、不安全的意思；预报/推测可指不可靠。常用 usikker på + 问题。",contexts:[["Utfallet er høyst usikkert.","结果仍很难预料。","词典例句；usikkert 描述结果未知，不是人没有信心。","https://ordbokene.no/bm/usikker"],["Isen er usikker.","冰面不牢靠，有危险。","词典例句；物理安全语境中 usikker 表示不安全，不能译成“冰不确定”。","https://ordbokene.no/bm/usikker"]]},
  rødme:{zh:"脸红；变红、泛红（动词；另有同形名词）",note:"动词 rødme 可指人因羞愧等而脸红，也可描写天空变红：rødme av skam、himmelen rødmet i øst。注意词库另有同形阳性名词 en rødme（红晕），本卡只练动词。",contexts:[["Hun rødmet av skam.","她羞得脸红了。","词典例句；av skam 说明脸红的原因是羞愧。","https://ordbokene.no/bm/r%C3%B8dme"],["Himmelen rødmet i øst.","东方天空泛起了红色。","词典例句；himmelen 作主语，rødmet 描写天色变红，不是人物脸红。","https://ordbokene.no/bm/r%C3%B8dme"]]},
  sikkert:{zh:"很可能；想必；确实/当然；安全地、稳妥地（依句法）",note:"作副词时常有两种语气：判断概率“很可能/想必” (Hun kommer sikkert senere)；表示说话人确信“当然/肯定”。动词方式语境可表示稳稳地、安全地 (arbeide jevnt og sikkert)。本卡不把它同形的中性形容词 sikkert（安全、可靠）混为一谈。",contexts:[["Hun er sikkert kommet allerede.","她想必已经到了。","词典例句；sikkert 修饰整个判断，表达“很可能/想必”，不是“安全地到了”。","https://ordbokene.no/bm/sikker"],["Det kan du sikkert klare selv.","这件事你肯定能自己办到。","自拟语境句；sikkert 表示说话人的信心/推断，可译“肯定、应该”。","https://ordbokene.no/bm/sikker"]]},
  menneske:{zh:"人；一个人；人类（依语境）",note:"et menneske 可指一个具体的人，也可指人这种生物类别（区别于动物/植物）。复数 mennesker 常表示人们；中文泛指“人类”时要看是否是物种/整体，而不是把每个单数 et menneske 都译成“人类”。",contexts:[["Mennesker og dyr trenger mat.","人和动物都需要食物。","自拟完整句；词典以 mennesker og dyr（人和动物）说明人与动物的对照。","https://ordbokene.no/bm/menneske"],["Det var ikke et menneske å se.","一个人影也看不见。","词典例句；et menneske å se 是“看见一个人”，这里不是在谈整个人类。","https://ordbokene.no/bm/menneske"]]},
  berømt:{zh:"著名的；闻名的；广为人知的（常用 berømt for）",note:"指在较广范围内为人所知；常用 være/ bli berømt for + 事物说明“因……而闻名”。不必然表示受欢迎或值得赞美。另见“那次著名的……”的定指用法。",contexts:[["Hun ble berømt for romanen sin.","她因自己的小说而闻名。","词典搭配；berømt for + 原因/作品说明闻名缘由。","https://ordbokene.no/bm/ber%C3%B8mt"],["Det var den berømte turen alle snakket om.","那就是大家一直在谈的那次著名旅行。","自拟语境句，采用词典词组 den berømte turen；den berømte 是定指单数形式，修饰双方已知的那次旅行。","https://ordbokene.no/bm/ber%C3%B8mt"]]},
  dronning:{zh:"女王；王后；蜂后；（比喻）某领域地位最高的女性；国际象棋后",word:"ei/en dronning",forms:["ei/en dronning","dronninga/dronningen","dronninger","dronningene"],note:"指女性君主时译“女王”；国王的妻子可译“王后”；蜂群中的产卵雌蜂叫蜂后；还可指国际象棋的后，或比喻某领域地位突出的女性。Bokmål 可用 ei 或 en，定指形式也有阴/阳性变体。",contexts:[["Dronningen regjerte i 45 år.","女王执政了45年。","词典例句；语境中是女性君主。","https://ordbokene.no/bm/dronning"],["Arbeidsbiene er svært lojale mot dronningen.","工蜂对蜂后非常忠诚。","词典例句；昆虫语境中 dronningen 是蜂后，不是王室成员。","https://ordbokene.no/bm/dronning"]]},
  folk:{zh:"人们；人民/国民；民族；群体（依数和语境）",note:"裸用复数 folk 常表示“人们”：det bor folk her（这里有人住）；et folk 是一个民族/族群；定指 folket 可指某国人民/国民，也可指前文那群人。虽是中性名词，口语“很多人”也常说 mange folk；更中性的正式表达是 mange mennesker。",contexts:[["Det norske folk har talt.","挪威人民已经作出选择。","词典搭配；定指单数 folket 指一个国家的人民/国民整体。","https://ordbokene.no/bm/folk"],["Det var mange folk på bussen.","公交车上有很多人。","词典例句；mange folk 是口语常见的“很多人”，不是“许多民族”。","https://ordbokene.no/bm/folk"]]},
  binde:{zh:"绑；系；捆；连接；使受约束/承担义务（依结构）",note:"具体物体：binde et tau（系绳子）、binde noe fast（绑牢）；连接：veien binder bygdene sammen（道路把村庄连接起来）；抽象义可指受合同、保密义务等约束。过去时 bandt，完成分词 bundet。",contexts:[["Rytteren bandt hesten til et tre.","骑手把马拴在一棵树上。","词典例句；bandt 是 binde 的过去时，til et tre 标出拴系位置。","https://ordbokene.no/bm/binde"],["Veien binder bygdene sammen.","这条路把几个村庄连接起来。","词典例句；binder sammen 是连接，不是用绳子捆绑。","https://ordbokene.no/bm/binde"]]},
  kaste:{zh:"扔；投掷；丢弃/放下；抛出、引发；（固定表达）浪费、摆脱等",note:"核心是把东西抛出或放下；不同宾语/小品词会引申：kaste ball（投球）、kaste klærne（脱掉衣服）、kaste bort tiden（浪费时间）、kaste skygge（投下影子）、kaste opp（呕吐）。根据搭配选译，不要把每个 kaste 都翻作“扔”。",contexts:[["Han kastet kofferten på sofaen.","他把行李箱往沙发上一扔。","词典例句；kastet + 物体 + på + 落点描述投掷/放下动作。","https://ordbokene.no/bm/kaste"],["Du kaster bort tiden.","你这是在浪费时间。","词典搭配；kaste bort + 时间/资源是固定的“浪费”。","https://ordbokene.no/bm/kaste"]]},
  rusle:{zh:"慢慢走；溜达；（另有同形义）发出轻微的沙沙声；琐碎地做点事",note:"最常见的走路义是慢慢、不慌不忙地走：rusle bortover veien。词典还分别列出同形动词义“发出轻微响声/沙沙声”及 rusle med noe（做点琐碎小事）；需看主语与结构，别把风声、脚步声都误当散步。",contexts:[["De rusler bortover veien.","他们沿着路慢慢走着。","词典例句；描述人的步行方式，rusler 表示慢慢走。","https://ordbokene.no/bm/rusle"],["Noen ruslet ute i bislaget.","门廊外传来轻微的窸窣声。","词典例句；此义描述轻微声响，不应按另一义译成“有人散步”。","https://ordbokene.no/bm/rusle"]]},
  miste:{zh:"失去；弄丢；错过（公交等班次）；失去某种能力/希望/控制（依宾语）",note:"miste nøklene 是把钥匙弄丢；miste bussen 不是“丢了公交车”，而是没赶上那班车；也可搭配 håpet、motet、synet、oversikten（失去希望、勇气、视力、头绪）。过去时/完成分词 mistet 或 mista。",contexts:[["De mistet alt de eide i brannen.","火灾中，他们失去了所有家当。","词典例句；miste + 财物表示失去，不一定是自己弄丢。","https://ordbokene.no/bm/miste"],["Hun mistet bussen på vei til jobb.","她上班路上没赶上公交车。","词典搭配；miste bussen 指迟到而错过班车，不是把车弄丢。","https://ordbokene.no/bm/miste"]]}
});
for (const entry of window.VOCAB_V2.additions) {
  const lemmaKey = entry.word.replace(/^(?:å|en|ei|et)\s+/u, "").trim();
  const finalCorrection = V2_REVIEW_CORRECTIONS_FINAL[entry.id] || V2_REVIEW_CORRECTIONS_FINAL[lemmaKey];
  if (finalCorrection) Object.assign(entry, finalCorrection);
}
Object.assign(V2_REVIEW_CORRECTIONS_FINAL, {
  varmegrad:{zh:"零上温度；零上几度",note:"天气口语中，én varmegrad 是零上1度，fem varmegrader 是零上5度；通常省略‘摄氏’，因为挪威日常天气温度默认用摄氏度。它说的是高于零的温度，不是泛指暖和，也不是‘一度暖温’。这是由 varme（暖）+ grad（温度单位）构成的透明词；零下说 minusgrader。",contexts:[["Det blir tre varmegrader i Oslo i morgen.","奥斯陆明天将是零上3度。","varmegrader 表明温度在零度以上；数字和复数 -er 相配。","https://ordbokene.no/bm/grad https://ordbokene.no/bm/minusgrad"],["Om natta kan temperaturen synke til én varmegrad.","夜里气温可能降到零上1度。","én varmegrad 是零上1度；数字 én 与单数形式 varmegrad 搭配。"]]},
  værvarsel:{zh:"天气预报",note:"指对未来一段时间天气状况的预报；普通天气预报不等于恶劣天气警报。若需要强调警报，应由 værvarsel 的具体内容或 farevarsel 等词说明。",contexts:[["værvarsler som gjelder til i morgen kveld","有效期到明晚的天气预报","词典搭配片段；gjelder til 标出这份预报适用的时间范围。","https://ordbokene.no/bm/v%C3%A6rvarsel"],["Værvarselet sier at det blir kaldere i morgen.","天气预报说，明天会降温。","værvarselet 是定指单数；它预报天气变化，不表示发布了警报。"]]},
  årstid:{zh:"季节；一年中的时节",note:"指一年中具有相对典型温度和生长条件的一段时期；常说四季 vår（春）、sommer（夏）、høst（秋）、vinter（冬）。Bokmål 可用 en årstid / ei årstid。",contexts:[["de fire årstidene vår, sommer, høst og vinter","春、夏、秋、冬四季","词典例句片段；årstidene 是定指复数，列举一年中的四季。","https://ordbokene.no/bm/%C3%A5rstid"],["Hvilken årstid liker du best?","你最喜欢哪个季节？","årstid 是提问的对象；best 表示在这些季节中最喜欢。"]]},
  fjernkontroll:{zh:"遥控器；远距离控制设备的手持装置",note:"通过远距离发出指令来控制电视等设备的装置。fjernkontroll 指器具本身；遥控这项功能/操作不是同一个名词。透明复合词 fjern（远程）+ kontroll（控制）。",contexts:[["Kan du gi meg fjernkontrollen?","你能把遥控器递给我吗？","gi meg + 物品表示‘把某物递给我’；fjernkontrollen 是双方已知的那个遥控器。","https://ordbokene.no/bm/fjernkontroll"],["Jeg finner ikke fjernkontrollen til TV-en.","我找不到电视遥控器了。","til TV-en 说明这是电视的遥控器；finner ikke 表示找不到。"]]},
  male:{zh:"粉刷；给……涂漆；绘画/画画",note:"本卡主学给表面上漆和用颜料作画：male huset（给房子刷漆）、male et bilde（画一幅画）。同形还有词源不同的 male（研磨/磨碎）以及猫发出满足的呼噜声；初学时依宾语辨义，不要把这些意义都硬塞进同一句。",contexts:[["Vi skal male kjøkkenet lyst før jul.","我们打算圣诞节前把厨房刷成浅色。","male + 房间/物件表示粉刷；lyst 是补语，说明最后刷成浅色。","https://ordbokene.no/bm/male%7Cm%C3%A5la%7Cm%C3%A5le"],["Hun malte et bilde av fjellene.","她画了一幅山景画。","male et bilde 表示创作一幅画；malte 是过去时。","https://ordbokene.no/bm/male%7Cm%C3%A5la%7Cm%C3%A5le"]]},
  ramme:{zh:"框；画框；框架；范围/界限（依语境）",note:"可指包在照片或物件周围的实体框，也可指安排、活动的背景/环境，或规定和预算所设的范围：sette et bilde i ramme（把照片装框）、økonomiske rammer（经济限额）。本条是名词；同形动词 ramme 表示击中或波及，是另一词性。",contexts:[["sette et fotografi i glass og ramme","把一张照片装进玻璃和画框里","词典搭配片段；ramme 是照片外面的实体框。","https://ordbokene.no/bm/ramme"],["De økonomiske rammene er begrensede.","经费额度有限。","复数 rammene 在这里指预算/经费所设的限额，不是实体画框。"]]},
  stearinlys:{zh:"硬脂蜡烛；蜡烛",note:"中性复合名词 et stearinlys，指由 stearin（硬脂）制成的蜡烛；日常泛指蜡烛也常直接说 et lys。不要把 stearinlys 当作所有类型蜡烛的材料说明。",contexts:[["bordet er pyntet med blomster og stearinlys","桌上摆着鲜花和蜡烛作为装饰","词典例句片段；stearinlys 与花并列，是桌面装饰物。","https://ordbokene.no/bm/stearinlys"],["Vi tente stearinlys da strømmen gikk.","停电时我们点上了蜡烛。","tenne stearinlys 是‘点蜡烛’；不定复数形式与词头同形。"]]},
  bestevenn:{zh:"最好的朋友；关系特别亲近的朋友",note:"官方词典义为关系非常亲密的朋友。bestevenn 的语法性别为阳性，但指男性或女性朋友都可以；性别不决定朋友本人的性别。bli bestevenner 表示两人成为挚友。",contexts:[["de er bestevenner","他们/她们是最好的朋友","词典例句片段；bestevenner 是复数表语，描述两人关系亲密。","https://ordbokene.no/bm/bestevenn"],["Hun er bestevennen min.","她是我最好的朋友。","bestevennen min 是定指形式加后置所有格；虽然词尾形式是阳性名词，所指可以是女性。"]]},
  enebarn:{zh:"独生子女；没有兄弟姐妹的孩子",note:"中性名词 et enebarn，指没有兄弟姐妹的人；词本身不标记性别。中文‘独生子’容易被理解为男性，泛指时优先说‘独生子女’。",contexts:[["hun er enebarn","她是独生子女","词典例句片段；enebarn 不区分孩子的性别。","https://ordbokene.no/bm/enebarn"],["Jeg er enebarn og vokste opp uten søsken.","我是独生子女，长大过程中没有兄弟姐妹。","uten søsken 解释 enebarn 的具体意思；søsken 是兄弟姐妹的统称。"]]},
  farfar:{zh:"爷爷；父亲的父亲",note:"明确指父亲的父亲；母亲的父亲是 morfar。farfar 是阳性名词，平时称呼家人时常直接说 farfar，不一定加 en。不要把它泛化为所有祖父。",contexts:[["bestefar på farssiden","父亲那一边的祖父","词典释义片段；farssiden 指父系，因此中文对应‘爷爷’。","https://ordbokene.no/nob/bm/farfar"],["Farfar bor i et hus ved sjøen.","爷爷住在海边的一栋房子里。","Farfar 作称呼/亲属称谓直接作主语；语境指说话者父亲的父亲。"]]},
  farmor:{zh:"奶奶；父亲的母亲",note:"明确指父亲的母亲；母亲的母亲是 mormor。官方词典接受阴性或阳性，日常也可说 farmora（阴性定指）。中文‘奶奶’和‘外婆’不是同一支系，要按 farmor/mormor 区分。",contexts:[["bestemor på farssiden","父亲那一边的祖母","词典释义片段；farssiden 指父系，因此中文对应‘奶奶’。","https://ordbokene.no/bm/farmor"],["Farmora mi lager verdens beste vafler.","我奶奶做的华夫饼最好吃。","farmora mi 是阴性定指形式加后置所有格 mi。"]]},
  storesøster:{zh:"姐姐；年长的姐妹",note:"指比本人年长的姐姐；也可特指家中最大的姐姐。阳性/阴性形式可用 en storesøster 或 ei storesøster；复数 storesøstre，词干发生变化。",contexts:[["eldre (særlig eldste) søster","年长的（尤其是最大的）姐姐","词典释义片段；eldre 表示年龄较大，særlig eldste 强调可能是最大的姐姐。","https://ordbokene.no/bm/stores%C3%B8ster"],["Han har to storesøstre.","他有两个姐姐。","storesøstre 是不定复数；这句明确说她们都比 Han 年长。"]]}
});
